INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_basic#9','math',3,2,'u6','L02','g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C3',2,'sa','auto','그림그래프에서 제기차기를 좋아하는 학생은 연날리기를 좋아하는 학생보다 몇 명 더 많나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u6-C3","difficulty":2,"kind":"sa","stem":"그림그래프에서 제기차기를 좋아하는 학생은 연날리기를 좋아하는 학생보다 몇 명 더 많나요? 숫자로 쓰세요.","answer":["12"],"explanation":["제기차기는 38명, 연날리기는 26명이에요.","더 많은 수에서 적은 수를 빼요.","38 − 26 = 12명이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 학생 수","head":"민속놀이","cols":["윷놀이","투호","연날리기","제기차기"],"counts":[33,21,26,38],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 초록 농장에서 기르는 오리는 바람 농장에서 기르는 오리보다 몇 마리 더 많나요? 숫자로 쓰세요.","answer":["14"],"explanation":["초록 농장은 24마리, 바람 농장은 10마리예요.","더 많은 수에서 적은 수를 빼요.","24 − 10 = 14마리예요."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["초록 농장","햇살 농장","바람 농장","들꽃 농장"],"counts":[24,9,10,36],"units":[10,1],"icon":"🦆","unit":"마리","vh":"오리의 수"}},{"stem":"그림그래프에서 판매한 샌들은 판매한 구두보다 몇 켤레 더 많나요? 숫자로 쓰세요.","answer":["24"],"explanation":["샌들은 31켤레, 구두는 7켤레예요.","더 많은 수에서 적은 수를 빼요.","31 − 7 = 24켤레예요."],"asset":{"type":"picg","title":"종류별 판매한 신발의 수","head":"종류","cols":["운동화","구두","샌들","장화"],"counts":[33,7,31,36],"units":[10,1],"icon":"👟","unit":"켤레","vh":"신발의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_basic#10','math',3,2,'u6','L02','g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C2',3,'ox','auto','장화 줄에는 그림이 5개 있으니까 판매한 장화는 5켤레예요.',ARRAY['M3-2-u6-X01']::text[],true,'{"seq":10,"concept":"M3-2-u6-C2","difficulty":3,"kind":"ox","stem":"장화 줄에는 그림이 5개 있으니까 판매한 장화는 5켤레예요.","answer":"X","reason_options":[{"t":"큰 그림은 10켤레, 작은 그림은 1켤레라 14켤레여서","correct":true},{"t":"그림 한 개가 1켤레여서","mis":"M3-2-u6-X01"}],"mis":"M3-2-u6-X01","explanation":["큰 그림과 작은 그림이 나타내는 수가 달라요.","장화 줄은 10켤레 그림 1개와 1켤레 그림 4개예요.","14켤레이므로 틀린 말이에요(X)."],"asset":{"type":"picg","title":"종류별 판매한 신발의 수","head":"종류","cols":["운동화","구두","샌들","장화"],"counts":[17,48,36,14],"units":[10,1],"icon":"👟","unit":"켤레","vh":"신발의 수"},"variant_rule":{"alt":[{"stem":"크림도넛 줄은 10개 그림 3개와 1개 그림 6개이므로 판매한 크림도넛은 36개예요.","answer":"O","reason_options":[{"t":"큰 그림부터 세고 작은 그림을 더하면 36이어서","correct":true},{"t":"그림의 개수만 세어야 해서","mis":"M3-2-u6-X01"}],"explanation":["큰 그림 한 개는 10개, 작은 그림 한 개는 1개예요.","10개 그림 3개와 1개 그림 6개.","36개가 맞아요(O)."],"asset":{"type":"picg","title":"종류별 판매한 도넛의 수","head":"종류","cols":["크림도넛","초코도넛","딸기도넛","꿀도넛"],"counts":[36,12,45,48],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"}},{"stem":"2반 줄에는 그림이 8개 있으니까 2반에서 빌린 책은 8권이에요.","answer":"X","reason_options":[{"t":"큰 그림은 10권, 작은 그림은 1권이라 35권이어서","correct":true},{"t":"그림 한 개가 1권이어서","mis":"M3-2-u6-X01"}],"explanation":["큰 그림과 작은 그림이 나타내는 수가 달라요.","2반 줄은 10권 그림 3개와 1권 그림 5개예요.","35권이므로 틀린 말이에요(X)."],"asset":{"type":"picg","title":"반별 빌린 책의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[28,35,17,25],"units":[10,1],"icon":"📕","unit":"권","vh":"책의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#1','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 지유가 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 지유가 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["23"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","지유 줄은 5회 그림 4개와 1회 그림 3개예요.","지유가 운동한 횟수는 23회예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[7,11,12,23],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 지유가 훌라후프를 한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["24"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","지유 줄은 5회 그림 4개와 1회 그림 4개예요.","지유가 훌라후프를 한 횟수는 24회예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[5,17,14,24],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}},{"stem":"그림그래프를 보고 해바라기는 몇 송이인지 구하세요. 숫자로 쓰세요.","answer":["13"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5송이, 작은 그림 1송이.","해바라기 줄은 5송이 그림 2개와 1송이 그림 3개예요.","해바라기는 13송이예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[28,11,4,13],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#2','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C1',2,'sa','auto','좋아하는 과일별 학생 수 표예요. 배와 포도를 좋아하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C1","difficulty":2,"kind":"sa","stem":"좋아하는 과일별 학생 수 표예요. 배와 포도를 좋아하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["배는 5명, 포도는 27명이에요.","모두 몇인지 물으면 더해요.","5 + 27 = 32명이에요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["귤","사과","포도","배"],"counts":[12,9,27,5],"unit":"명","vh":"학생 수","title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"배우고 싶어 하는 악기별 학생 수 표예요. 우쿨렐레와 가야금을 배우고 싶어 하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["우쿨렐레는 9명, 가야금은 10명이에요.","모두 몇인지 물으면 더해요.","9 + 10 = 19명이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[10,26,9,21],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수"}},{"stem":"여행 가고 싶어 하는 나라별 학생 수 표예요. 영국과 프랑스에 가고 싶어 하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["영국은 10명, 프랑스는 17명이에요.","모두 몇인지 물으면 더해요.","10 + 17 = 27명이에요."],"asset":{"type":"picg","only":"table","head":"나라","cols":["미국","일본","영국","프랑스"],"counts":[25,8,10,17],"unit":"명","vh":"학생 수","title":"여행 가고 싶어 하는 나라별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#3','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',3,'sa','auto','그림그래프를 보고 학생 수의 합계를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"그림그래프를 보고 학생 수의 합계를 구하세요. 숫자로 쓰세요.","answer":["77"],"explanation":["줄마다 수를 먼저 읽어요 — 당근 31, 시금치 10, 오이 13, 콩나물 23.","네 수를 모두 더해요.","31 + 10 + 13 + 23 = 77명이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[31,10,13,23],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림그래프를 보고 학생 수의 합계를 구하세요. 숫자로 쓰세요.","answer":["32"],"explanation":["줄마다 수를 먼저 읽어요 — 놀이공원 5, 박물관 4, 과학관 6, 동물원 17.","네 수를 모두 더해요.","5 + 4 + 6 + 17 = 32명이에요."],"asset":{"type":"picg","title":"가고 싶어 하는 체험 학습 장소별 학생 수","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[5,4,6,17],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"이번에는 다른 그림이에요. 그림그래프를 보고 학생 수의 합계를 구하세요. 숫자로 쓰세요.","answer":["137"],"explanation":["줄마다 수를 먼저 읽어요 — 합창부 16, 로봇부 40, 축구부 49, 미술부 32.","네 수를 모두 더해요.","16 + 40 + 49 + 32 = 137명이에요."],"asset":{"type":"picg","title":"가입한 동아리별 학생 수","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[16,40,49,32],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#4','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',3,'mc','auto','반별 빌린 책의 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 1반은 10권이에요.  ㉡ 가장 적은 것은 3반이에요.  ㉢ 4반은 1반보다 10권 더 많아요.',ARRAY['M3-2-u6-X16','M3-2-u6-X01']::text[],true,'{"seq":4,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"반별 빌린 책의 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 1반은 10권이에요.  ㉡ 가장 적은 것은 3반이에요.  ㉢ 4반은 1반보다 10권 더 많아요.","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M3-2-u6-X16"},{"t":"㉢","mis":"M3-2-u6-X16"},{"t":"모두 옳아요","mis":"M3-2-u6-X01"}],"explanation":["줄마다 수를 읽어요 — 1반 37, 2반 48, 3반 15, 4반 47.","말 하나하나를 그래프와 맞춰 봐요.","옳지 않은 것은 ㉠이에요."],"asset":{"type":"picg","title":"반별 빌린 책의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[37,48,15,47],"units":[10,1],"icon":"📕","unit":"권","vh":"책의 수"},"variant_rule":{"alt":[{"stem":"마을별 심은 나무의 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 바람 마을은 4그루예요.  ㉡ 가장 적은 것은 구름 마을이에요.  ㉢ 구름 마을은 햇살 마을보다 18그루 더 많아요.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u6-X16"},{"t":"㉢","mis":"M3-2-u6-X16"},{"t":"모두 옳아요","mis":"M3-2-u6-X16"}],"explanation":["줄마다 수를 읽어요 — 햇살 마을 24, 바람 마을 4, 구름 마을 42, 별빛 마을 23.","말 하나하나를 그래프와 맞춰 봐요.","옳지 않은 것은 ㉡이에요."],"asset":{"type":"picg","title":"마을별 심은 나무의 수","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[24,4,42,23],"units":[10,1],"icon":"🌳","unit":"그루","vh":"나무의 수"}},{"stem":"반별 모은 빈 병의 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 2반은 20개예요.  ㉡ 가장 적은 것은 4반이에요.  ㉢ 3반은 2반보다 15개 더 많아요.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u6-X16"},{"t":"㉢","mis":"M3-2-u6-X16"},{"t":"모두 옳아요","mis":"M3-2-u6-X16"}],"explanation":["줄마다 수를 읽어요 — 1반 22, 2반 20, 3반 35, 4반 42.","말 하나하나를 그래프와 맞춰 봐요.","옳지 않은 것은 ㉡이에요."],"asset":{"type":"picg","title":"반별 모은 빈 병의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[22,20,35,42],"units":[10,1],"icon":"🍾","unit":"개","vh":"빈 병의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#5','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',3,'mc','auto','그림그래프를 보고 가장 많은 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16','M3-2-u6-X03']::text[],true,'{"seq":5,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"그림그래프를 보고 가장 많은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"별빛 마을 → 구름 마을 → 햇살 마을 → 바람 마을","correct":true},{"t":"햇살 마을 → 별빛 마을 → 바람 마을 → 구름 마을","mis":"M3-2-u6-X04"},{"t":"바람 마을 → 햇살 마을 → 구름 마을 → 별빛 마을","mis":"M3-2-u6-X16"},{"t":"구름 마을 → 별빛 마을 → 햇살 마을 → 바람 마을","mis":"M3-2-u6-X03"}],"explanation":["줄마다 수를 읽어요 — 햇살 마을 9, 바람 마을 6, 구름 마을 11, 별빛 마을 24.","그림 개수가 아니라 나타내는 수로 차례를 정해요.","별빛 마을 → 구름 마을 → 햇살 마을 → 바람 마을."],"asset":{"type":"picg","title":"마을별 심은 나무의 수","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[9,6,11,24],"units":[10,1],"icon":"🌳","unit":"그루","vh":"나무의 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 가장 적은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"3반 → 1반 → 2반 → 4반","correct":true},{"t":"3반 → 1반 → 4반 → 2반","mis":"M3-2-u6-X04"},{"t":"4반 → 2반 → 1반 → 3반","mis":"M3-2-u6-X16"},{"t":"1반 → 3반 → 2반 → 4반","mis":"M3-2-u6-X03"}],"explanation":["줄마다 수를 읽어요 — 1반 8, 2반 37, 3반 3, 4반 45.","그림 개수가 아니라 나타내는 수로 차례를 정해요.","3반 → 1반 → 2반 → 4반."],"asset":{"type":"picg","title":"반별 모은 빈 병의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[8,37,3,45],"units":[10,1],"icon":"🍾","unit":"개","vh":"빈 병의 수"}},{"stem":"이번에는 다른 그림이에요. 그림그래프를 보고 가장 많은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"우쿨렐레 → 플루트 → 오카리나 → 가야금","correct":true},{"t":"가야금 → 우쿨렐레 → 플루트 → 오카리나","mis":"M3-2-u6-X04"},{"t":"가야금 → 오카리나 → 플루트 → 우쿨렐레","mis":"M3-2-u6-X16"},{"t":"플루트 → 우쿨렐레 → 오카리나 → 가야금","mis":"M3-2-u6-X03"}],"explanation":["줄마다 수를 읽어요 — 가야금 19, 오카리나 21, 우쿨렐레 45, 플루트 30.","그림 개수가 아니라 나타내는 수로 차례를 정해요.","우쿨렐레 → 플루트 → 오카리나 → 가야금."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[19,21,45,30],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#6','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',3,'sa','auto','그림그래프에서 15개보다 많은 반 은 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"그림그래프에서 15개보다 많은 반 은 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["줄마다 수를 읽어요 — 1반 7, 2반 49, 3반 15, 4반 45, 5반 46.","15보다 큰 수만 골라요(같은 수는 넣지 않아요).","모두 3가지예요."],"asset":{"type":"picg","title":"반별 모은 빈 병의 수","head":"반","cols":["1반","2반","3반","4반","5반"],"counts":[7,49,15,45,46],"units":[10,1],"icon":"🍾","unit":"개","vh":"빈 병의 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 38명보다 많은 악기 는 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["줄마다 수를 읽어요 — 가야금 41, 오카리나 38, 우쿨렐레 9, 플루트 47, 리코더 7.","38보다 큰 수만 골라요(같은 수는 넣지 않아요).","모두 2가지예요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트","리코더"],"counts":[41,38,9,47,7],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"그림그래프에서 22명보다 많은 여가 활동 은 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["줄마다 수를 읽어요 — 배드민턴 49, 산책 40, 자전거 타기 13, 줄넘기 17, 수영 22.","22보다 큰 수만 골라요(같은 수는 넣지 않아요).","모두 2가지예요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기","수영"],"counts":[49,40,13,17,22],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#7','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C2',3,'error','auto','그림그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u6-X01','M3-2-u6-X16','M3-2-u6-X02']::text[],true,'{"seq":7,"concept":"M3-2-u6-C2","difficulty":3,"kind":"error","stem":"그림그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「우쿨렐레 그림이 7개니까 7명이야.」","correct":true,"mis_target":"M3-2-u6-X01"},{"t":"시우 — 「가장 많은 것은 플루트예요.」","mis":"M3-2-u6-X16"},{"t":"은우 — 「가장 적은 것은 오카리나예요.」","mis":"M3-2-u6-X16"},{"t":"하랑 — 「큰 그림은 10명을 나타내.」","mis":"M3-2-u6-X02"}],"explanation":["그림의 개수만 세면 안 돼요.","우쿨렐레 줄은 10명 그림 3개와 1명 그림 4개라서 34명이에요.","서윤의 말이 잘못이에요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[17,6,34,48],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「배드민턴 그림이 10개니까 10명이야.」","correct":true,"mis_target":"M3-2-u6-X01"},{"t":"은우 — 「가장 많은 것은 줄넘기예요.」","mis":"M3-2-u6-X16"},{"t":"하랑 — 「가장 적은 것은 산책이에요.」","mis":"M3-2-u6-X16"},{"t":"지아 — 「큰 그림은 10명을 나타내.」","mis":"M3-2-u6-X02"}],"explanation":["그림의 개수만 세면 안 돼요.","배드민턴 줄은 10명 그림 3개와 1명 그림 7개라서 37명이에요.","시우의 말이 잘못이에요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[37,31,46,48],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"이번에는 다른 그림이에요. 그림그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「당근 그림이 3개니까 3명이야.」","correct":true,"mis_target":"M3-2-u6-X01"},{"t":"하랑 — 「가장 많은 것은 콩나물이에요.」","mis":"M3-2-u6-X16"},{"t":"지아 — 「가장 적은 것은 당근이에요.」","mis":"M3-2-u6-X16"},{"t":"민호 — 「큰 그림은 10명을 나타내.」","mis":"M3-2-u6-X02"}],"explanation":["그림의 개수만 세면 안 돼요.","당근 줄은 1명 그림 3개라서 3명이에요.","은우의 말이 잘못이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[3,35,8,49],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#8','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',4,'sa','auto','학생 수의 합계는 152명이에요. 그림그래프에서 줄넘기 줄이 지워졌어요. 줄넘기를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u6-C3","difficulty":4,"kind":"sa","stem":"학생 수의 합계는 152명이에요. 그림그래프에서 줄넘기 줄이 지워졌어요. 줄넘기를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["보이는 줄의 수를 읽어요 — 29, 44, 33.","모르는 수 = 합계 − 아는 수들이에요.","152 − 29 − 44 − 33 = 46명이에요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[29,44,33,null],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[3]},"variant_rule":{"alt":[{"stem":"학생 수의 합계는 61명이에요. 그림그래프에서 콩나물 줄이 지워졌어요. 콩나물을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["보이는 줄의 수를 읽어요 — 4, 7, 33.","모르는 수 = 합계 − 아는 수들이에요.","61 − 4 − 7 − 33 = 17명이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[4,7,33,null],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[3]}},{"stem":"학생 수의 합계는 48명이에요. 그림그래프에서 박물관 줄이 지워졌어요. 박물관에 가고 싶어 하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["보이는 줄의 수를 읽어요 — 13, 15, 16.","모르는 수 = 합계 − 아는 수들이에요.","48 − 13 − 15 − 16 = 4명이에요."],"asset":{"type":"picg","title":"가고 싶어 하는 체험 학습 장소별 학생 수","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[13,null,15,16],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#9','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',4,'sa','auto','㉠은 그림이 8개, ㉡은 그림이 3개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u6-C3","difficulty":4,"kind":"sa","stem":"㉠은 그림이 8개, ㉡은 그림이 3개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.","answer":["4"],"explanation":["그림이 많다고 수가 많은 것은 아니에요.","㉠은 26, ㉡은 30이라 ㉡이 더 많아요.","30 − 26 = 4예요."],"asset":{"type":"picg","title":"그림의 개수와 수","head":"채소","cols":["㉠","㉡"],"counts":[26,30],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"㉠은 그림이 9개, ㉡은 그림이 5개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.","answer":["5"],"explanation":["그림이 많다고 수가 많은 것은 아니에요.","㉠은 27, ㉡은 32라 ㉡이 더 많아요.","32 − 27 = 5예요."],"asset":{"type":"picg","title":"그림의 개수와 수","head":"장소","cols":["㉠","㉡"],"counts":[27,32],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"㉠은 그림이 8개, ㉡은 그림이 4개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.","answer":["14"],"explanation":["그림이 많다고 수가 많은 것은 아니에요.","㉠은 26, ㉡은 40이라 ㉡이 더 많아요.","40 − 26 = 14예요."],"asset":{"type":"picg","title":"그림의 개수와 수","head":"동아리","cols":["㉠","㉡"],"counts":[26,40],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L02_challenge#10','math',3,2,'u6','L02','g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C2',4,'essay','teacher','친구가 그림그래프에서 큰 그림 2개와 작은 그림 4개를 보고 「6명이야.」라고 말했어요. 큰 그림은 10명, 작은 그림은 1명일 때 잘못된 까닭을 쓰고 바르게 읽어 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C2","difficulty":4,"kind":"essay","stem":"친구가 그림그래프에서 큰 그림 2개와 작은 그림 4개를 보고 「6명이야.」라고 말했어요. 큰 그림은 10명, 작은 그림은 1명일 때 잘못된 까닭을 쓰고 바르게 읽어 보세요.","answer_guide":{"answer":"예: 큰 그림과 작은 그림이 나타내는 수가 다른데 그림의 개수만 세었다. 큰 그림 2개는 20명, 작은 그림 4개는 4명이므로 모두 24명이다.","scoring_points":["그림의 개수만 세었다고 까닭을 썼는가","큰 그림 2개를 20명, 작은 그림 4개를 4명으로 읽었는가","24명이라고 바르게 읽었는가"]},"explanation":["그림 뜻을 먼저 봐요.","큰 그림 2개 = 20명, 작은 그림 4개 = 4명.","20 + 4 = 24(명)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#1','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',1,'sa','auto','놀이공원에 가고 싶어 하는 학생 21명을 그림그래프로 나타내요. 큰 그림이 10명, 작은 그림이 1명을 나타낼 때 10명 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C4","difficulty":1,"kind":"sa","stem":"놀이공원에 가고 싶어 하는 학생 21명을 그림그래프로 나타내요. 큰 그림이 10명, 작은 그림이 1명을 나타낼 때 10명 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","21명은 10명 그림 2개와 1명 그림 1개예요.","10명 그림은 2개예요."],"variant_rule":{"alt":[{"stem":"로봇부에 가입한 학생 14명을 그림그래프로 나타내요. 큰 그림이 10명, 작은 그림이 1명을 나타낼 때 10명 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["1"],"explanation":["큰 그림부터 그려요.","14명은 10명 그림 1개와 1명 그림 4개예요.","10명 그림은 1개예요."],"asset":null},{"stem":"연날리기를 좋아하는 학생 14명을 그림그래프로 나타내요. 큰 그림이 10명, 작은 그림이 1명을 나타낼 때 10명 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["1"],"explanation":["큰 그림부터 그려요.","14명은 10명 그림 1개와 1명 그림 4개예요.","10명 그림은 1개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#2','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',1,'sa','auto','합창부에 가입한 학생 17명을 그림그래프로 나타내요. 큰 그림이 10명, 작은 그림이 1명을 나타낼 때 1명 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C4","difficulty":1,"kind":"sa","stem":"합창부에 가입한 학생 17명을 그림그래프로 나타내요. 큰 그림이 10명, 작은 그림이 1명을 나타낼 때 1명 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["7"],"explanation":["큰 그림부터 그려요.","17명은 10명 그림 1개와 1명 그림 7개예요.","1명 그림은 7개예요."],"variant_rule":{"alt":[{"stem":"투호를 좋아하는 학생 21명을 그림그래프로 나타내요. 큰 그림이 10명, 작은 그림이 1명을 나타낼 때 1명 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["1"],"explanation":["큰 그림부터 그려요.","21명은 10명 그림 2개와 1명 그림 1개예요.","1명 그림은 1개예요."],"asset":null},{"stem":"바람 농장에서 기르는 오리 24마리를 그림그래프로 나타내요. 큰 그림이 10마리, 작은 그림이 1마리를 나타낼 때 1마리 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 그림부터 그려요.","24마리는 10마리 그림 2개와 1마리 그림 4개예요.","1마리 그림은 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#3','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',1,'mc','auto','그림그래프로 나타내는 네 걸음 가운데 ③는 무엇인가요?  ① 알맞은 제목 → ② 그림과 단위 → ③ ? → ④ 그림',ARRAY['M3-2-u6-X07']::text[],true,'{"seq":3,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"그림그래프로 나타내는 네 걸음 가운데 ③는 무엇인가요?  ① 알맞은 제목 → ② 그림과 단위 → ③ ? → ④ 그림","options":[{"t":"조사한 항목을 빠짐없이 써요","correct":true},{"t":"알맞은 제목을 써요","mis":"M3-2-u6-X07"},{"t":"그림과 단위를 정해요","mis":"M3-2-u6-X07"},{"t":"합계를 구해요","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지를 갖추어 나타내요.","③ 걸음은 「조사한 항목을 빠짐없이 써요」예요.","순서는 꼭 지키지 않아도 되지만 네 가지는 빠짐없이 있어야 해요."],"variant_rule":{"alt":[{"stem":"그림그래프로 나타내는 네 걸음 가운데 ②는 무엇인가요?  ① 알맞은 제목 → ② ? → ③ 항목 → ④ 그림","options":[{"t":"그림과 단위를 정해요","correct":true},{"t":"알맞은 제목을 써요","mis":"M3-2-u6-X07"},{"t":"조사한 항목을 빠짐없이 써요","mis":"M3-2-u6-X07"},{"t":"합계를 구해요","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지를 갖추어 나타내요.","② 걸음은 「그림과 단위를 정해요」예요.","순서는 꼭 지키지 않아도 되지만 네 가지는 빠짐없이 있어야 해요."],"asset":null},{"stem":"그림그래프로 나타내는 네 걸음 가운데 ④는 무엇인가요?  ① 알맞은 제목 → ② 그림과 단위 → ③ 항목 → ④ ?","options":[{"t":"수에 맞게 그림으로 나타내요","correct":true},{"t":"알맞은 제목을 써요","mis":"M3-2-u6-X07"},{"t":"그림과 단위를 정해요","mis":"M3-2-u6-X07"},{"t":"합계를 구해요","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지를 갖추어 나타내요.","④ 걸음은 「수에 맞게 그림으로 나타내요」예요.","순서는 꼭 지키지 않아도 되지만 네 가지는 빠짐없이 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#4','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',1,'mc','auto','그림그래프로 나타낼 때 어떤 그림을 먼저 그리면 수를 견주기 쉬운가요?',ARRAY['M3-2-u6-X06','M3-2-u6-X07']::text[],true,'{"seq":4,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"그림그래프로 나타낼 때 어떤 그림을 먼저 그리면 수를 견주기 쉬운가요?","options":[{"t":"큰 수를 나타내는 그림","correct":true},{"t":"작은 수를 나타내는 그림","mis":"M3-2-u6-X06"},{"t":"아무 그림이나","mis":"M3-2-u6-X07"},{"t":"가장 예쁜 그림","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 큰 그림부터 그려요.","그러면 큰 그림의 개수로 많고 적음을 바로 견줄 수 있어요.","답은 「큰 수를 나타내는 그림」이에요."],"variant_rule":{"alt":[{"stem":"표의 수를 그림그래프로 옮길 때 먼저 정해야 하는 것은 무엇인가요?","options":[{"t":"그림과 그림이 나타내는 수(단위)","correct":true},{"t":"그림의 색깔","mis":"M3-2-u6-X07"},{"t":"그림을 그릴 연필","mis":"M3-2-u6-X07"},{"t":"그래프의 크기","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 큰 그림부터 그려요.","그러면 큰 그림의 개수로 많고 적음을 바로 견줄 수 있어요.","답은 「그림과 그림이 나타내는 수(단위)」예요."],"asset":null},{"stem":"큰 그림과 작은 그림을 그릴 때 알맞은 방법은 무엇인가요?","options":[{"t":"큰 그림을 먼저 그리고 남은 수를 작은 그림으로 그려요","correct":true},{"t":"작은 그림을 먼저 그리고 남은 수를 큰 그림으로 그려요","mis":"M3-2-u6-X06"},{"t":"작은 그림만 수만큼 그려요","mis":"M3-2-u6-X06"},{"t":"큰 그림만 수만큼 그려요","mis":"M3-2-u6-X02"}],"explanation":["그림그래프는 큰 그림부터 그려요.","그러면 큰 그림의 개수로 많고 적음을 바로 견줄 수 있어요.","답은 「큰 그림을 먼저 그리고 남은 수를 작은 그림으로 그려요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#5','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',2,'mc','auto','합창부에 가입한 학생 49명을 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":5,"concept":"M3-2-u6-C4","difficulty":2,"kind":"mc","stem":"합창부에 가입한 학생 49명을 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10명 그림 4개와 1명 그림 9개","correct":true},{"t":"10명 그림 9개와 1명 그림 4개","mis":"M3-2-u6-X05"},{"t":"10명 그림 4개","mis":"M3-2-u6-X06"},{"t":"10명 그림 5개와 1명 그림 9개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 10명이에요.","49명은 큰 그림 4개, 남은 9명은 작은 그림 9개예요.","답은 「10명 그림 4개와 1명 그림 9개」예요."],"variant_rule":{"alt":[{"stem":"투호를 좋아하는 학생 16명을 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10명 그림 1개와 1명 그림 6개","correct":true},{"t":"10명 그림 6개와 1명 그림 1개","mis":"M3-2-u6-X05"},{"t":"10명 그림 1개","mis":"M3-2-u6-X06"},{"t":"10명 그림 2개와 1명 그림 6개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 10명이에요.","16명은 큰 그림 1개, 남은 6명은 작은 그림 6개예요.","답은 「10명 그림 1개와 1명 그림 6개」예요."],"asset":null},{"stem":"바람 농장에서 기르는 오리 42마리를 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10마리 그림 4개와 1마리 그림 2개","correct":true},{"t":"10마리 그림 2개와 1마리 그림 4개","mis":"M3-2-u6-X05"},{"t":"10마리 그림 4개","mis":"M3-2-u6-X06"},{"t":"10마리 그림 5개와 1마리 그림 2개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 10마리예요.","42마리는 큰 그림 4개, 남은 2마리는 작은 그림 2개예요.","답은 「10마리 그림 4개와 1마리 그림 2개」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#6','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',2,'sa','auto','그림그래프를 보고 떡국을 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u6-C4","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 떡국을 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["190"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 100명, 가운데 그림 10명, 작은 그림 1명.","떡국 줄은 100명 그림 1개와 10명 그림 9개예요.","떡국을 좋아하는 학생은 190명이에요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[190,45,232,153],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 여름의 산불 발생 건수는 몇 건인지 구하세요. 숫자로 쓰세요.","answer":["47"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 100건, 가운데 그림 10건, 작은 그림 1건.","여름 줄은 10건 그림 4개와 1건 그림 7개예요.","여름의 산불 발생 건수는 47건이에요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[109,47,260,392],"units":[100,10,1],"icon":"🔥","unit":"건","vh":"발생 건수"}},{"stem":"그림그래프를 보고 수요일에 도서관을 찾은 사람은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["391"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 100명, 가운데 그림 10명, 작은 그림 1명.","수요일 줄은 100명 그림 3개, 10명 그림 9개와 1명 그림 1개예요.","수요일에 도서관을 찾은 사람은 391명이에요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[378,44,391,286],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"사람 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#7','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',2,'mc','auto','그림그래프에 꼭 있어야 하는 것이 아닌 것은 무엇인가요?',ARRAY['M3-2-u6-X07']::text[],true,'{"seq":7,"concept":"M3-2-u6-C4","difficulty":2,"kind":"mc","stem":"그림그래프에 꼭 있어야 하는 것이 아닌 것은 무엇인가요?","options":[{"t":"조사한 사람의 이름","correct":true},{"t":"제목","mis":"M3-2-u6-X07"},{"t":"그림이 나타내는 수","mis":"M3-2-u6-X07"},{"t":"조사한 항목","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지로 이루어져요.","단위가 없으면 그림을 읽을 수 없어요.","답은 「조사한 사람의 이름」이에요."],"variant_rule":{"alt":[{"stem":"그림그래프를 보고 무엇을 조사했는지 알려면 무엇을 보면 되나요?","options":[{"t":"제목","correct":true},{"t":"가장 큰 그림","mis":"M3-2-u6-X01"},{"t":"그림의 색깔","mis":"M3-2-u6-X07"},{"t":"작은 그림의 개수","mis":"M3-2-u6-X01"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지로 이루어져요.","단위가 없으면 그림을 읽을 수 없어요.","답은 「제목」이에요."],"asset":null},{"stem":"그림그래프에 그림이 나타내는 수를 쓰지 않으면 어떤 일이 생기나요?","options":[{"t":"그림이 몇을 나타내는지 몰라 수를 읽을 수 없어요","correct":true},{"t":"제목을 알 수 없어요","mis":"M3-2-u6-X07"},{"t":"항목이 늘어나요","mis":"M3-2-u6-X07"},{"t":"아무 일도 없어요","mis":"M3-2-u6-X02"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지로 이루어져요.","단위가 없으면 그림을 읽을 수 없어요.","답은 「그림이 몇을 나타내는지 몰라 수를 읽을 수 없어요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#8','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C5',2,'mc','auto','가장 많은 학생이 좋아하는 전통 음식을 급식에 넣으려고 해요. 무엇을 넣으면 될까요?',ARRAY['M3-2-u6-X16','M3-2-u6-X04']::text[],true,'{"seq":8,"concept":"M3-2-u6-C5","difficulty":2,"kind":"mc","stem":"가장 많은 학생이 좋아하는 전통 음식을 급식에 넣으려고 해요. 무엇을 넣으면 될까요?","options":[{"t":"불고기","correct":true},{"t":"떡국","mis":"M3-2-u6-X16"},{"t":"비빔밥","mis":"M3-2-u6-X04"},{"t":"잡채","mis":"M3-2-u6-X04"}],"explanation":["그림그래프에서 줄마다 수를 읽어요 — 떡국 40, 불고기 267, 비빔밥 92, 잡채 249.","가장 많은 것을 찾아요.","「불고기」예요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[40,267,92,249],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"가장 적은 학생이 좋아하는 채소를 더 맛있게 만들어 보려고 해요. 무엇을 고르면 될까요?","options":[{"t":"당근","correct":true},{"t":"시금치","mis":"M3-2-u6-X04"},{"t":"오이","mis":"M3-2-u6-X04"},{"t":"콩나물","mis":"M3-2-u6-X16"}],"explanation":["그림그래프에서 줄마다 수를 읽어요 — 당근 5, 시금치 33, 오이 26, 콩나물 41.","가장 적은 것을 찾아요.","「당근」이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[5,33,26,41],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"가장 많은 학생이 좋아하는 과일을 급식에 넣으려고 해요. 무엇을 넣으면 될까요?","options":[{"t":"귤","correct":true},{"t":"사과","mis":"M3-2-u6-X04"},{"t":"포도","mis":"M3-2-u6-X16"},{"t":"배","mis":"M3-2-u6-X04"}],"explanation":["그림그래프에서 줄마다 수를 읽어요 — 귤 40, 사과 11, 포도 5, 배 9.","가장 많은 것을 찾아요.","「귤」이에요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["귤","사과","포도","배"],"counts":[40,11,5,9],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#9','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',2,'mc','auto','그림그래프에서 산불이 가장 많이 난 계절은 언제인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16','M3-2-u6-X03']::text[],true,'{"seq":9,"concept":"M3-2-u6-C4","difficulty":2,"kind":"mc","stem":"그림그래프에서 산불이 가장 많이 난 계절은 언제인가요?","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M3-2-u6-X04"},{"t":"여름","mis":"M3-2-u6-X16"},{"t":"가을","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 봄 89, 여름 86, 가을 177, 겨울 242.","가장 많은 것은 「겨울」이에요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[89,86,177,242],"units":[100,10,1],"icon":"🔥","unit":"건","vh":"발생 건수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 도서관을 찾은 사람이 가장 많은 요일은 언제인가요?","options":[{"t":"월요일","correct":true},{"t":"화요일","mis":"M3-2-u6-X03"},{"t":"수요일","mis":"M3-2-u6-X04"},{"t":"목요일","mis":"M3-2-u6-X16"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 월요일 364, 화요일 266, 수요일 299, 목요일 192.","가장 많은 것은 「월요일」이에요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[364,266,299,192],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"사람 수"}},{"stem":"그림그래프에서 사과를 가장 많이 생산한 마을은 어느 마을인가요?","options":[{"t":"바람 마을","correct":true},{"t":"햇살 마을","mis":"M3-2-u6-X03"},{"t":"구름 마을","mis":"M3-2-u6-X04"},{"t":"별빛 마을","mis":"M3-2-u6-X16"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 햇살 마을 209, 바람 마을 350, 구름 마을 176, 별빛 마을 94.","가장 많은 것은 「바람 마을」이에요."],"asset":{"type":"picg","title":"마을별 사과 생산량","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[209,350,176,94],"units":[100,10,1],"icon":"🍎","unit":"상자","vh":"생산량"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_basic#10','math',3,2,'u6','L03','g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',3,'ox','auto','판매한 운동화 23켤레를 10켤레 그림 3개와 1켤레 그림 2개로 나타냈어요.',ARRAY['M3-2-u6-X01']::text[],true,'{"seq":10,"concept":"M3-2-u6-C4","difficulty":3,"kind":"ox","stem":"판매한 운동화 23켤레를 10켤레 그림 3개와 1켤레 그림 2개로 나타냈어요.","answer":"X","reason_options":[{"t":"10켤레 그림 3개는 30켤레라 수가 달라서","correct":true},{"t":"그림의 개수를 모두 더하면 5개라 맞아서","mis":"M3-2-u6-X01"}],"mis":"M3-2-u6-X01","explanation":["십의 자리 수만큼 큰 그림, 일의 자리 수만큼 작은 그림을 그려요.","23켤레는 10켤레 그림 2개와 1켤레 그림 3개예요.","개수를 바꾸어 그려서 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"판매한 초코도넛 24개를 10개 그림 2개와 1개 그림 4개로 나타냈어요.","answer":"O","reason_options":[{"t":"10개 그림 2개는 20개, 1개 그림 4개는 4개여서","correct":true},{"t":"큰 그림과 작은 그림의 개수를 바꾸어도 되어서","mis":"M3-2-u6-X05"}],"explanation":["십의 자리 수만큼 큰 그림, 일의 자리 수만큼 작은 그림을 그려요.","24개는 10개 그림 2개와 1개 그림 4개예요.","바르게 나타냈어요(O)."],"asset":null},{"stem":"3반에서 빌린 책 45권을 10권 그림 5개와 1권 그림 4개로 나타냈어요.","answer":"X","reason_options":[{"t":"10권 그림 5개는 50권이라 수가 달라서","correct":true},{"t":"그림의 개수를 모두 더하면 9개라 맞아서","mis":"M3-2-u6-X01"}],"explanation":["십의 자리 수만큼 큰 그림, 일의 자리 수만큼 작은 그림을 그려요.","45권은 10권 그림 4개와 1권 그림 5개예요.","개수를 바꾸어 그려서 틀렸어요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#1','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',2,'sa','auto','햇살 마을의 사과 생산량 182상자를 그림그래프로 나타내요. 큰 그림이 100상자, 가운데 그림이 10상자, 작은 그림이 1상자를 나타낼 때 10상자 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C4","difficulty":2,"kind":"sa","stem":"햇살 마을의 사과 생산량 182상자를 그림그래프로 나타내요. 큰 그림이 100상자, 가운데 그림이 10상자, 작은 그림이 1상자를 나타낼 때 10상자 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["8"],"explanation":["큰 그림부터 그려요.","182상자는 100상자 그림 1개, 10상자 그림 8개와 1상자 그림 2개예요.","10상자 그림은 8개예요."],"variant_rule":{"alt":[{"stem":"불고기를 좋아하는 학생 194명을 그림그래프로 나타내요. 큰 그림이 100명, 가운데 그림이 10명, 작은 그림이 1명을 나타낼 때 10명 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["9"],"explanation":["큰 그림부터 그려요.","194명은 100명 그림 1개, 10명 그림 9개와 1명 그림 4개예요.","10명 그림은 9개예요."],"asset":null},{"stem":"가을의 산불 발생 건수 215건을 그림그래프로 나타내요. 큰 그림이 100건, 가운데 그림이 10건, 작은 그림이 1건을 나타낼 때 10건 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["1"],"explanation":["큰 그림부터 그려요.","215건은 100건 그림 2개, 10건 그림 1개와 1건 그림 5개예요.","10건 그림은 1개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#2','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',2,'sa','auto','가입한 동아리별 학생 수 표예요. 합계는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C4","difficulty":2,"kind":"sa","stem":"가입한 동아리별 학생 수 표예요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["101"],"explanation":["합계는 항목의 수를 모두 더한 것이에요.","11 + 20 + 45 + 25.","101명이에요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[11,20,45,25],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수","total":null},"variant_rule":{"alt":[{"stem":"가고 싶어 하는 체험 학습 장소별 학생 수 표예요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["99"],"explanation":["합계는 항목의 수를 모두 더한 것이에요.","9 + 49 + 18 + 23.","99명이에요."],"asset":{"type":"picg","only":"table","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[9,49,18,23],"unit":"명","vh":"학생 수","title":"가고 싶어 하는 체험 학습 장소별 학생 수","total":null}},{"stem":"좋아하는 여가 활동별 학생 수 표예요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["146"],"explanation":["합계는 항목의 수를 모두 더한 것이에요.","46 + 32 + 44 + 24.","146명이에요."],"asset":{"type":"picg","only":"table","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[46,32,44,24],"unit":"명","vh":"학생 수","title":"좋아하는 여가 활동별 학생 수","total":null}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#3','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',3,'sa','auto','이 표를 큰 그림 하나가 10개, 작은 그림 하나가 1개를 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C4","difficulty":3,"kind":"sa","stem":"이 표를 큰 그림 하나가 10개, 작은 그림 하나가 1개를 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.","answer":["27"],"explanation":["줄마다 큰 그림과 작은 그림의 개수를 구해요.","43 → 7개, 40 → 4개, 39 → 12개, 31 → 4개.","7 + 4 + 12 + 4 = 27개예요."],"asset":{"type":"picg","only":"table","head":"종류","cols":["크림도넛","초코도넛","딸기도넛","꿀도넛"],"counts":[43,40,39,31],"unit":"개","vh":"도넛의 수","title":"종류별 판매한 도넛의 수","total":false},"variant_rule":{"alt":[{"stem":"이 표를 큰 그림 하나가 10권, 작은 그림 하나가 1권을 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.","answer":["30"],"explanation":["줄마다 큰 그림과 작은 그림의 개수를 구해요.","36 → 9개, 24 → 6개, 22 → 4개, 47 → 11개.","9 + 6 + 4 + 11 = 30개예요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반"],"counts":[36,24,22,47],"unit":"권","vh":"책의 수","title":"반별 빌린 책의 수","total":false}},{"stem":"이 표를 큰 그림 하나가 10그루, 작은 그림 하나가 1그루를 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.","answer":["29"],"explanation":["줄마다 큰 그림과 작은 그림의 개수를 구해요.","46 → 10개, 14 → 5개, 29 → 11개, 21 → 3개.","10 + 5 + 11 + 3 = 29개예요."],"asset":{"type":"picg","only":"table","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[46,14,29,21],"unit":"그루","vh":"나무의 수","title":"마을별 심은 나무의 수","total":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#4','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',3,'mc','auto','표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?',ARRAY['M3-2-u6-X13']::text[],true,'{"seq":4,"concept":"M3-2-u6-C4","difficulty":3,"kind":"mc","stem":"표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"햇살 마을","correct":true},{"t":"바람 마을","mis":"M3-2-u6-X13"},{"t":"구름 마을","mis":"M3-2-u6-X13"},{"t":"별빛 마을","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","햇살 마을 줄은 1그루 그림 8개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「햇살 마을」이에요."],"asset":{"type":"picg","title":"마을별 심은 나무의 수","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[8,16,3,18],"units":[10,1],"icon":"🌳","unit":"그루","vh":"나무의 수","table":true,"pieces":[[8,0],[1,6],[0,3],[1,8]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"1반","correct":true},{"t":"2반","mis":"M3-2-u6-X13"},{"t":"3반","mis":"M3-2-u6-X13"},{"t":"4반","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","1반 줄은 10개 그림 2개와 1개 그림 3개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「1반」이에요."],"asset":{"type":"picg","title":"반별 모은 빈 병의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[23,14,21,27],"units":[10,1],"icon":"🍾","unit":"개","vh":"빈 병의 수","table":true,"pieces":[[3,2],[1,4],[2,1],[2,7]]}},{"stem":"이번에는 다른 그림이에요. 표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"우쿨렐레","correct":true},{"t":"가야금","mis":"M3-2-u6-X13"},{"t":"오카리나","mis":"M3-2-u6-X13"},{"t":"플루트","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","우쿨렐레 줄은 10명 그림 1개와 1명 그림 6개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「우쿨렐레」예요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[38,37,16,26],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","table":true,"pieces":[[3,8],[3,7],[6,1],[2,6]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#5','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',3,'sa','auto','그림그래프에서 떡국을 좋아하는 학생은 불고기를 좋아하는 학생보다 몇 명 더 많나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u6-C4","difficulty":3,"kind":"sa","stem":"그림그래프에서 떡국을 좋아하는 학생은 불고기를 좋아하는 학생보다 몇 명 더 많나요? 숫자로 쓰세요.","answer":["225"],"explanation":["떡국은 337명, 불고기는 112명이에요.","더 많은 수에서 적은 수를 빼요.","337 − 112 = 225명이에요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[337,112,42,230],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 봄의 산불 발생 건수는 겨울의 산불 발생 건수보다 몇 건 더 많나요? 숫자로 쓰세요.","answer":["226"],"explanation":["봄은 378건, 겨울은 152건이에요.","더 많은 수에서 적은 수를 빼요.","378 − 152 = 226건이에요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[378,344,327,152],"units":[100,10,1],"icon":"🔥","unit":"건","vh":"발생 건수"}},{"stem":"그림그래프에서 화요일에 도서관을 찾은 사람은 수요일에 도서관을 찾은 사람보다 몇 명 더 많나요? 숫자로 쓰세요.","answer":["6"],"explanation":["화요일은 129명, 수요일은 123명이에요.","더 많은 수에서 적은 수를 빼요.","129 − 123 = 6명이에요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[157,129,123,201],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"사람 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#6','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C5',3,'mc','auto','그림그래프를 보고 「떡국을 급식에 넣어요.」라고 정했어요. 알맞은 까닭은 무엇인가요?',ARRAY['M3-2-u6-X17']::text[],true,'{"seq":6,"concept":"M3-2-u6-C5","difficulty":3,"kind":"mc","stem":"그림그래프를 보고 「떡국을 급식에 넣어요.」라고 정했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"가장 많은 학생이 좋아하기 때문이에요","correct":true},{"t":"가장 적은 학생이 좋아하기 때문이에요","mis":"M3-2-u6-X17"},{"t":"그림이 가장 예쁘기 때문이에요","mis":"M3-2-u6-X17"},{"t":"표의 맨 앞에 있기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["정한 일과 그림그래프에서 읽은 사실이 맞아야 해요.","줄마다 수 — 떡국 130, 불고기 82, 비빔밥 64, 잡채 51.","알맞은 까닭 — 가장 많은 학생이 좋아하기 때문이에요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[130,82,64,51],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 「식혜를 더 맛있게 만들어 봐요.」라고 정했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"좋아하는 학생이 가장 적어서 더 많은 학생이 좋아하게 하려고요","correct":true},{"t":"가장 많은 학생이 좋아하기 때문이에요","mis":"M3-2-u6-X17"},{"t":"그림을 가장 많이 그렸기 때문이에요","mis":"M3-2-u6-X04"},{"t":"이름이 가장 짧기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["정한 일과 그림그래프에서 읽은 사실이 맞아야 해요.","줄마다 수 — 떡국 124, 불고기 95, 비빔밥 71, 식혜 38.","알맞은 까닭 — 좋아하는 학생이 가장 적어서 더 많은 학생이 좋아하게 하려고요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜"],"counts":[124,95,71,38],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"그림그래프를 보고 「오이 반찬을 자주 내요.」라고 정했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"좋아하는 학생이 가장 많기 때문이에요","correct":true},{"t":"좋아하는 학생이 가장 적기 때문이에요","mis":"M3-2-u6-X17"},{"t":"작은 그림이 가장 많기 때문이에요","mis":"M3-2-u6-X04"},{"t":"채소 이름이 두 글자이기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["정한 일과 그림그래프에서 읽은 사실이 맞아야 해요.","줄마다 수 — 당근 18, 시금치 10, 오이 24, 콩나물 15.","알맞은 까닭 — 좋아하는 학생이 가장 많기 때문이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[18,10,24,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#7','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',3,'mc','auto','이 표를 그림그래프로 나타내려고 해요. 그림을 너무 많이 그리지 않으면서 수를 바르게 나타내려면 어떤 그림으로 정하면 좋을까요?',ARRAY['M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":7,"concept":"M3-2-u6-C4","difficulty":3,"kind":"mc","stem":"이 표를 그림그래프로 나타내려고 해요. 그림을 너무 많이 그리지 않으면서 수를 바르게 나타내려면 어떤 그림으로 정하면 좋을까요?","options":[{"t":"100명 그림, 10명 그림, 1명 그림","correct":true},{"t":"1명 그림만","mis":"M3-2-u6-X06"},{"t":"10명 그림만","mis":"M3-2-u6-X06"},{"t":"1000명 그림과 1명 그림","mis":"M3-2-u6-X02"}],"explanation":["수의 크기를 보고 단위를 정해요.","가장 큰 수가 302라 세 자리 수 — 100·10·1 세 가지면 그림이 적어요.","답은 「100명 그림, 10명 그림, 1명 그림」이에요."],"asset":{"type":"picg","only":"table","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[235,148,302,176],"unit":"명","vh":"사람 수","title":"요일별 도서관을 찾은 사람 수","total":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 표를 그림그래프로 나타내려고 해요. 그림을 너무 많이 그리지 않으면서 수를 바르게 나타내려면 어떤 그림으로 정하면 좋을까요?","options":[{"t":"10명 그림과 1명 그림","correct":true},{"t":"100명 그림과 1명 그림","mis":"M3-2-u6-X02"},{"t":"1명 그림만","mis":"M3-2-u6-X06"},{"t":"100명 그림만","mis":"M3-2-u6-X06"}],"explanation":["수의 크기를 보고 단위를 정해요.","가장 큰 수가 35라 두 자리 수 — 10과 1이면 충분해요.","답은 「10명 그림과 1명 그림」이에요."],"asset":{"type":"picg","only":"table","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[12,27,35,18],"unit":"명","vh":"학생 수","title":"좋아하는 여가 활동별 학생 수","total":false}},{"stem":"이번에는 다른 그림이에요. 이 표를 그림그래프로 나타내려고 해요. 그림을 너무 많이 그리지 않으면서 수를 바르게 나타내려면 어떤 그림으로 정하면 좋을까요?","options":[{"t":"100건 그림, 10건 그림, 1건 그림","correct":true},{"t":"1건 그림만","mis":"M3-2-u6-X06"},{"t":"1000건 그림과 1건 그림","mis":"M3-2-u6-X02"},{"t":"10건 그림만","mis":"M3-2-u6-X06"}],"explanation":["수의 크기를 보고 단위를 정해요.","가장 큰 수가 377이라 세 자리 수 — 100·10·1 세 가지면 그림이 적어요.","답은 「100건 그림, 10건 그림, 1건 그림」이에요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"unit":"건","vh":"발생 건수","title":"계절별 산불 발생 건수","total":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#8','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',4,'mc','auto','이 표를 큰 그림 하나가 10개, 작은 그림 하나가 1개를 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X01']::text[],true,'{"seq":8,"concept":"M3-2-u6-C4","difficulty":4,"kind":"mc","stem":"이 표를 큰 그림 하나가 10개, 작은 그림 하나가 1개를 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?","options":[{"t":"3반","correct":true},{"t":"1반","mis":"M3-2-u6-X03"},{"t":"2반","mis":"M3-2-u6-X01"},{"t":"4반","mis":"M3-2-u6-X01"}],"explanation":["그림 수 = 십의 자리 수 + 일의 자리 수예요.","1반 4 → 4개, 2반 19 → 10개, 3반 10 → 1개, 4반 41 → 5개.","가장 적게 그리는 것은 3반이에요 — 수가 가장 작은 것과 다를 수 있어요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반"],"counts":[4,19,10,41],"unit":"개","vh":"빈 병의 수","title":"반별 모은 빈 병의 수","total":false},"variant_rule":{"alt":[{"stem":"이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?","options":[{"t":"플루트","correct":true},{"t":"가야금","mis":"M3-2-u6-X01"},{"t":"오카리나","mis":"M3-2-u6-X01"},{"t":"우쿨렐레","mis":"M3-2-u6-X03"}],"explanation":["그림 수 = 십의 자리 수 + 일의 자리 수예요.","가야금 39 → 12개, 오카리나 49 → 13개, 우쿨렐레 33 → 6개, 플루트 41 → 5개.","가장 적게 그리는 것은 플루트예요 — 수가 가장 작은 것과 다를 수 있어요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[39,49,33,41],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수","total":false}},{"stem":"이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?","options":[{"t":"산책","correct":true},{"t":"배드민턴","mis":"M3-2-u6-X01"},{"t":"자전거 타기","mis":"M3-2-u6-X03"},{"t":"줄넘기","mis":"M3-2-u6-X01"}],"explanation":["그림 수 = 십의 자리 수 + 일의 자리 수예요.","배드민턴 27 → 9개, 산책 40 → 4개, 자전거 타기 9 → 9개, 줄넘기 32 → 5개.","가장 적게 그리는 것은 산책이에요 — 수가 가장 작은 것과 다를 수 있어요."],"asset":{"type":"picg","only":"table","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[27,40,9,32],"unit":"명","vh":"학생 수","title":"좋아하는 여가 활동별 학생 수","total":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#9','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',4,'sa','auto','큰 그림 10회, 작은 그림 1회로 나타낸 그림그래프를 큰 그림 5회, 작은 그림 1회로 다시 그리려고 해요. 은비 줄에 5회 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u6-C4","difficulty":4,"kind":"sa","stem":"큰 그림 10회, 작은 그림 1회로 나타낸 그림그래프를 큰 그림 5회, 작은 그림 1회로 다시 그리려고 해요. 은비 줄에 5회 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["4"],"explanation":["먼저 은비 줄의 수를 읽어요 — 24회.","24회는 5회 그림 4개와 1회 그림 4개예요.","4개예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[24,11,27,13],"units":[10,1],"icon":"⭕","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"큰 그림 10송이, 작은 그림 1송이로 나타낸 그림그래프를 큰 그림 5송이, 작은 그림 1송이로 다시 그리려고 해요. 백합 줄에 1송이 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["1"],"explanation":["먼저 백합 줄의 수를 읽어요 — 26송이.","26송이는 5송이 그림 5개와 1송이 그림 1개예요.","1개예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[12,18,26,17],"units":[10,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"}},{"stem":"큰 그림 10장, 작은 그림 1장으로 나타낸 그림그래프를 큰 그림 5장, 작은 그림 1장으로 다시 그리려고 해요. 달님 모둠 줄에 5장 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["4"],"explanation":["먼저 달님 모둠 줄의 수를 읽어요 — 24장.","24장은 5장 그림 4개와 1장 그림 4개예요.","4개예요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[21,24,27,26],"units":[10,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L03_challenge#10','math',3,2,'u6','L03','g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C5',4,'essay','teacher','좋아하는 전통 음식별 학생 수 그림그래프를 보고 우리 반 급식에 넣을 음식을 하나 정하려고 해요. 떡국 130명, 불고기 82명, 비빔밥 64명, 식혜 51명일 때 무엇을 정할지 쓰고, 그림그래프에서 읽은 사실로 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C5","difficulty":4,"kind":"essay","stem":"좋아하는 전통 음식별 학생 수 그림그래프를 보고 우리 반 급식에 넣을 음식을 하나 정하려고 해요. 떡국 130명, 불고기 82명, 비빔밥 64명, 식혜 51명일 때 무엇을 정할지 쓰고, 그림그래프에서 읽은 사실로 까닭을 써 보세요.","answer_guide":{"answer":"예: 떡국을 급식에 넣겠다. 그림그래프에서 100명 그림이 있는 음식은 떡국뿐이고 130명으로 가장 많은 학생이 좋아하기 때문이다. (또는 식혜를 맛있게 만들어 좋아하는 학생을 늘리겠다 — 51명으로 가장 적기 때문이다.)","scoring_points":["정한 음식을 썼는가","그림그래프에서 읽은 수(가장 많음·적음)로 까닭을 썼는가","큰 그림부터 보고 수를 바르게 읽었는가"]},"explanation":["줄마다 수를 읽어요.","가장 많은 것·가장 적은 것을 찾아요.","정한 일과 읽은 사실이 맞으면 좋은 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_basic#1','math',3,2,'u6','L04','g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',1,'mc','auto','「상자에 종이를 넣어요.」라고 했어요. 어떤 조사 방법인가요?',ARRAY['M3-2-u6-X11']::text[],true,'{"seq":1,"concept":"M3-2-u6-C6","difficulty":1,"kind":"mc","stem":"「상자에 종이를 넣어요.」라고 했어요. 어떤 조사 방법인가요?","options":[{"t":"투표하기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["조사 방법에는 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기가 있어요.","「상자에 종이를 넣어요.」 하는 일은 「투표하기」의 모습이에요.","답은 「투표하기」예요."],"variant_rule":{"alt":[{"stem":"「좋아하는 것에 손을 들어 주세요.」라고 했어요. 어떤 조사 방법인가요?","options":[{"t":"손 들기","correct":true},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["조사 방법에는 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기가 있어요.","「좋아하는 것에 손을 들어 주세요.」 하는 일은 「손 들기」의 모습이에요.","답은 「손 들기」예요."],"asset":null},{"stem":"「칠판의 칸에 붙임딱지를 붙여요.」라고 했어요. 어떤 조사 방법인가요?","options":[{"t":"붙임딱지 붙이기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["조사 방법에는 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기가 있어요.","「칠판의 칸에 붙임딱지를 붙여요.」 하는 일은 「붙임딱지 붙이기」의 모습이에요.","답은 「붙임딱지 붙이기」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_basic#2','math',3,2,'u6','L04','g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',1,'mc','auto','조사할 항목은 몇 개쯤으로 정하면 좋을까요?',ARRAY['M3-2-u6-X10']::text[],true,'{"seq":2,"concept":"M3-2-u6-C6","difficulty":1,"kind":"mc","stem":"조사할 항목은 몇 개쯤으로 정하면 좋을까요?","options":[{"t":"4~6개","correct":true},{"t":"1개","mis":"M3-2-u6-X10"},{"t":"20개","mis":"M3-2-u6-X10"},{"t":"정하지 않아요","mis":"M3-2-u6-X10"}],"explanation":["항목이 너무 적으면 견줄 것이 없고, 너무 많으면 정리하기 어려워요.","그래서 4~6개 사이로 정해요.","답은 「4~6개」예요."],"variant_rule":{"alt":[{"stem":"그림그래프로 나타내기 좋게 항목을 정하려고 해요. 항목의 수로 알맞은 것은 무엇인가요?","options":[{"t":"4~6개","correct":true},{"t":"1개","mis":"M3-2-u6-X10"},{"t":"20개","mis":"M3-2-u6-X10"},{"t":"정하지 않아요","mis":"M3-2-u6-X10"}],"explanation":["항목이 너무 적으면 견줄 것이 없고, 너무 많으면 정리하기 어려워요.","그래서 4~6개 사이로 정해요.","답은 「4~6개」예요."],"asset":null},{"stem":"좋아하는 운동을 조사할 때 항목의 수로 알맞은 것은 무엇인가요?","options":[{"t":"4~6개","correct":true},{"t":"1개","mis":"M3-2-u6-X10"},{"t":"20개","mis":"M3-2-u6-X10"},{"t":"정하지 않아요","mis":"M3-2-u6-X10"}],"explanation":["항목이 너무 적으면 견줄 것이 없고, 너무 많으면 정리하기 어려워요.","그래서 4~6개 사이로 정해요.","답은 「4~6개」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_basic#3','math',3,2,'u6','L04','g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',1,'sa','auto','투표로 모은 자료를 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C6","difficulty":1,"kind":"sa","stem":"투표로 모은 자료를 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["99"],"explanation":["표의 수를 모두 더해요.","24 + 20 + 21 + 34.","99명이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[24,20,21,34],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수","total":null},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 투표로 모은 자료를 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["102"],"explanation":["표의 수를 모두 더해요.","24 + 32 + 21 + 25.","102명이에요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[24,32,21,25],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수","total":null}},{"stem":"이번에는 다른 그림이에요. 투표로 모은 자료를 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["표의 수를 모두 더해요.","31 + 27 + 15 + 22.","95명이에요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["귤","사과","포도","배"],"counts":[31,27,15,22],"unit":"명","vh":"학생 수","title":"좋아하는 과일별 학생 수","total":null}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_basic#4','math',3,2,'u6','L04','g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',1,'mc','auto','사람이 많으면 시간이 오래 걸리지만 궁금한 점을 바로 물어볼 수 있는 방법은 무엇인가요?',ARRAY['M3-2-u6-X11']::text[],true,'{"seq":4,"concept":"M3-2-u6-C6","difficulty":1,"kind":"mc","stem":"사람이 많으면 시간이 오래 걸리지만 궁금한 점을 바로 물어볼 수 있는 방법은 무엇인가요?","options":[{"t":"돌아다니며 묻기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"}],"explanation":["방법마다 좋은 점과 어려운 점이 달라요.","물음에 나온 좋은 점·어려운 점을 방법에 맞춰 봐요.","답은 「돌아다니며 묻기」예요."],"variant_rule":{"alt":[{"stem":"빠르게 셀 수 있지만 다른 친구가 무엇을 고르는지 보여서 따라 할 수 있는 방법은 무엇인가요?","options":[{"t":"손 들기","correct":true},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["방법마다 좋은 점과 어려운 점이 달라요.","물음에 나온 좋은 점·어려운 점을 방법에 맞춰 봐요.","답은 「손 들기」예요."],"asset":null},{"stem":"다른 친구가 무엇을 골랐는지 몰라 자기 생각대로 고를 수 있지만 종이를 모아 세는 데 시간이 걸리는 방법은 무엇인가요?","options":[{"t":"투표하기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["방법마다 좋은 점과 어려운 점이 달라요.","물음에 나온 좋은 점·어려운 점을 방법에 맞춰 봐요.","답은 「투표하기」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_basic#5','math',3,2,'u6','L04','g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',2,'mc','auto','우리 반이 직접 조사하기 어려운 주제는 무엇인가요?',ARRAY['M3-2-u6-X10']::text[],true,'{"seq":5,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"우리 반이 직접 조사하기 어려운 주제는 무엇인가요?","options":[{"t":"우리나라 모든 어린이가 좋아하는 과일","correct":true},{"t":"우리 반이 좋아하는 운동","mis":"M3-2-u6-X10"},{"t":"우리 모둠이 좋아하는 색깔","mis":"M3-2-u6-X10"},{"t":"우리 반이 배우고 싶은 악기","mis":"M3-2-u6-X10"}],"explanation":["주제는 우리가 직접 모을 수 있어야 해요.","그리고 무엇을 조사하는지 분명해야 해요.","답은 「우리나라 모든 어린이가 좋아하는 과일」이에요."],"variant_rule":{"alt":[{"stem":"우리 학년이 직접 자료를 모을 수 있는 주제는 무엇인가요?","options":[{"t":"우리 학년이 좋아하는 급식 반찬","correct":true},{"t":"세계 모든 사람이 좋아하는 동물","mis":"M3-2-u6-X10"},{"t":"우리나라 어른들이 가장 많이 타는 차","mis":"M3-2-u6-X10"},{"t":"지구에 사는 새의 수","mis":"M3-2-u6-X10"}],"explanation":["주제는 우리가 직접 모을 수 있어야 해요.","그리고 무엇을 조사하는지 분명해야 해요.","답은 「우리 학년이 좋아하는 급식 반찬」이에요."],"asset":null},{"stem":"무엇을 조사하는지 분명한 주제는 무엇인가요?","options":[{"t":"우리 반이 한 달 동안 읽은 책의 수","correct":true},{"t":"우리 반 친구들의 이것저것","mis":"M3-2-u6-X10"},{"t":"재미있는 것","mis":"M3-2-u6-X10"},{"t":"여러 가지 좋은 것","mis":"M3-2-u6-X10"}],"explanation":["주제는 우리가 직접 모을 수 있어야 해요.","그리고 무엇을 조사하는지 분명해야 해요.","답은 「우리 반이 한 달 동안 읽은 책의 수」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_basic#6','math',3,2,'u6','L04','g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',2,'sa','auto','표에서 가야금을 배우고 싶어 하는 학생은 우쿨렐레를 배우고 싶어 하는 학생보다 몇 명 더 많나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u6-C6","difficulty":2,"kind":"sa","stem":"표에서 가야금을 배우고 싶어 하는 학생은 우쿨렐레를 배우고 싶어 하는 학생보다 몇 명 더 많나요? 숫자로 쓰세요.","answer":["13"],"explanation":["가야금은 34, 우쿨렐레는 21이에요.","몇 명 더 많은지는 큰 수에서 작은 수를 빼요.","34 − 21 = 13명이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[34,18,21,33],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수"},"variant_rule":{"alt":[{"stem":"표에서 로봇부에 가입한 학생은 합창부에 가입한 학생보다 몇 명 더 많나요? 숫자로 쓰세요.","answer":["15"],"explanation":["로봇부는 33, 합창부는 18이에요.","몇 명 더 많은지는 큰 수에서 작은 수를 빼요.","33 − 18 = 15명이에요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[18,33,22,32],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수"}},{"stem":"표에서 동물원에 가고 싶어 하는 학생은 과학관에 가고 싶어 하는 학생보다 몇 명 더 많나요? 숫자로 쓰세요.","answer":["7"],"explanation":["동물원은 23, 과학관은 16이에요.","몇 명 더 많은지는 큰 수에서 작은 수를 빼요.","23 − 16 = 7명이에요."],"asset":{"type":"picg","only":"table","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[33,17,16,23],"unit":"명","vh":"학생 수","title":"가고 싶어 하는 체험 학습 장소별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
