INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_basic#9','math',3,2,'u6','L04','g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',2,'mc','auto','우리 반 학생 25명에게 좋아하는 과일을 물었어요. 조사 대상은 누구인가요?',ARRAY['M3-2-u6-X10']::text[],true,'{"seq":9,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"우리 반 학생 25명에게 좋아하는 과일을 물었어요. 조사 대상은 누구인가요?","options":[{"t":"우리 반 학생","correct":true},{"t":"좋아하는 과일","mis":"M3-2-u6-X10"},{"t":"과일 가게","mis":"M3-2-u6-X10"},{"t":"우리 학교 선생님","mis":"M3-2-u6-X10"}],"explanation":["주제는 무엇을 조사할지, 대상은 누구에게 조사할지예요.","물음이 주제를 묻는지 대상을 묻는지 먼저 봐요.","답은 「우리 반 학생」이에요."],"variant_rule":{"alt":[{"stem":"3학년 1반 친구들이 좋아하는 운동을 손 들기로 조사했어요. 조사 주제는 무엇인가요?","options":[{"t":"좋아하는 운동","correct":true},{"t":"3학년 1반 친구들","mis":"M3-2-u6-X10"},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"운동장","mis":"M3-2-u6-X10"}],"explanation":["주제는 무엇을 조사할지, 대상은 누구에게 조사할지예요.","물음이 주제를 묻는지 대상을 묻는지 먼저 봐요.","답은 「좋아하는 운동」이에요."],"asset":null},{"stem":"우리 모둠 학생에게 한 달 동안 운동한 횟수를 물어보기로 했어요. 조사 대상은 누구인가요?","options":[{"t":"우리 모둠 학생","correct":true},{"t":"한 달 동안 운동한 횟수","mis":"M3-2-u6-X10"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"},{"t":"체육 선생님","mis":"M3-2-u6-X10"}],"explanation":["주제는 무엇을 조사할지, 대상은 누구에게 조사할지예요.","물음이 주제를 묻는지 대상을 묻는지 먼저 봐요.","답은 「우리 모둠 학생」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_basic#10','math',3,2,'u6','L04','g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',3,'ox','auto','우리 반 학생 25명에게 하나씩 투표하게 했는데 표의 합계가 26명이 나왔어요. 종이를 잘못 세었을 수 있어요.',ARRAY['M3-2-u6-X13']::text[],true,'{"seq":10,"concept":"M3-2-u6-C6","difficulty":3,"kind":"ox","stem":"우리 반 학생 25명에게 하나씩 투표하게 했는데 표의 합계가 26명이 나왔어요. 종이를 잘못 세었을 수 있어요.","answer":"O","reason_options":[{"t":"한 사람이 하나씩 냈으니 합계는 25명이어야 해서","correct":true},{"t":"합계가 조사한 학생 수보다 많아도 괜찮아서","mis":"M3-2-u6-X13"}],"mis":"M3-2-u6-X13","explanation":["한 사람이 한 장씩 투표했어요.","그러면 합계는 조사한 학생 수 25명과 같아야 해요.","26명이 나왔으니 두 번 센 종이가 있을 수 있어요(O)."],"variant_rule":{"alt":[{"stem":"우리 반 학생 24명에게 하나씩 투표하게 했어요. 표의 합계가 26명이면 빠짐없이 바르게 센 것이에요.","answer":"X","reason_options":[{"t":"합계는 조사한 학생 수 24명과 같아야 해서","correct":true},{"t":"합계는 많을수록 좋아서","mis":"M3-2-u6-X13"}],"explanation":["한 사람이 한 장씩 냈어요.","합계는 24명이어야 해요.","26명은 맞지 않아요(X)."],"asset":null},{"stem":"우리 반 학생 26명에게 하나씩 투표하게 했는데 표의 합계가 27명이 나왔어요. 종이를 잘못 세었을 수 있어요.","answer":"O","reason_options":[{"t":"한 사람이 하나씩 냈으니 합계는 26명이어야 해서","correct":true},{"t":"합계가 조사한 학생 수보다 많아도 괜찮아서","mis":"M3-2-u6-X13"}],"explanation":["한 사람이 한 장씩 투표했어요.","그러면 합계는 조사한 학생 수 26명과 같아야 해요.","27명이 나왔으니 두 번 센 종이가 있을 수 있어요(O)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#1','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',2,'mc','auto','「우리 반 친구들이 좋아하는 간식」을 조사할 때 항목으로 알맞게 정한 것은 무엇인가요?',ARRAY['M3-2-u6-X10']::text[],true,'{"seq":1,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"「우리 반 친구들이 좋아하는 간식」을 조사할 때 항목으로 알맞게 정한 것은 무엇인가요?","options":[{"t":"떡볶이, 김밥, 과자, 과일, 빵","correct":true},{"t":"떡볶이","mis":"M3-2-u6-X10"},{"t":"맛있는 것, 싫은 것","mis":"M3-2-u6-X10"},{"t":"떡볶이, 김밥, 과자, 과일, 빵, 음료, 젤리, 사탕, 국수, 만두, 피자, 치킨","mis":"M3-2-u6-X10"}],"explanation":["항목은 4~6개 사이로, 겹치지 않고 분명하게 정해요.","너무 적거나 너무 많으면 견주고 정리하기 어려워요.","답은 「떡볶이, 김밥, 과자, 과일, 빵」이에요."],"variant_rule":{"alt":[{"stem":"좋아하는 계절을 조사할 때 항목으로 알맞은 것은 무엇인가요?","options":[{"t":"봄, 여름, 가을, 겨울","correct":true},{"t":"봄, 여름","mis":"M3-2-u6-X10"},{"t":"더운 날, 추운 날, 좋은 날","mis":"M3-2-u6-X10"},{"t":"1월부터 12월까지 12개","mis":"M3-2-u6-X10"}],"explanation":["항목은 4~6개 사이로, 겹치지 않고 분명하게 정해요.","너무 적거나 너무 많으면 견주고 정리하기 어려워요.","답은 「봄, 여름, 가을, 겨울」이에요."],"asset":null},{"stem":"배우고 싶은 악기를 조사할 때 항목으로 알맞은 것은 무엇인가요?","options":[{"t":"가야금, 오카리나, 우쿨렐레, 플루트","correct":true},{"t":"가야금","mis":"M3-2-u6-X10"},{"t":"소리 나는 것, 소리 안 나는 것","mis":"M3-2-u6-X10"},{"t":"세상의 모든 악기","mis":"M3-2-u6-X10"}],"explanation":["항목은 4~6개 사이로, 겹치지 않고 분명하게 정해요.","너무 적거나 너무 많으면 견주고 정리하기 어려워요.","답은 「가야금, 오카리나, 우쿨렐레, 플루트」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#2','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',2,'match','auto','조사 방법과 그 방법의 특징을 바르게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C6","difficulty":2,"kind":"match","stem":"조사 방법과 그 방법의 특징을 바르게 이으세요.","pairs":[{"l":"손 들기","r":"빠르게 세지만 다른 친구를 따라 고를 수 있어요"},{"l":"투표하기","r":"자기 생각대로 고르지만 종이를 모아 세야 해요"},{"l":"붙임딱지 붙이기","r":"붙인 것이 남아 한눈에 보여요"},{"l":"돌아다니며 묻기","r":"궁금한 점을 바로 물을 수 있지만 오래 걸려요"}],"mis":"M3-2-u6-X11","explanation":["방법마다 하는 일을 떠올려요.","손은 보이고, 투표는 안 보이고, 붙임딱지는 남고, 묻기는 대화해요.","네 쌍을 모두 바르게 이어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 조사 방법과 그 방법의 특징을 바르게 이으세요.","pairs":[{"l":"투표하기","r":"자기 생각대로 고르지만 종이를 모아 세야 해요"},{"l":"붙임딱지 붙이기","r":"붙인 것이 남아 한눈에 보여요"},{"l":"돌아다니며 묻기","r":"궁금한 점을 바로 물을 수 있지만 오래 걸려요"},{"l":"손 들기","r":"빠르게 세지만 다른 친구를 따라 고를 수 있어요"}],"explanation":["방법마다 하는 일을 떠올려요.","손은 보이고, 투표는 안 보이고, 붙임딱지는 남고, 묻기는 대화해요.","네 쌍을 모두 바르게 이어요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 조사 방법과 그 방법의 특징을 바르게 이으세요.","pairs":[{"l":"붙임딱지 붙이기","r":"붙인 것이 남아 한눈에 보여요"},{"l":"돌아다니며 묻기","r":"궁금한 점을 바로 물을 수 있지만 오래 걸려요"},{"l":"손 들기","r":"빠르게 세지만 다른 친구를 따라 고를 수 있어요"},{"l":"투표하기","r":"자기 생각대로 고르지만 종이를 모아 세야 해요"}],"explanation":["방법마다 하는 일을 떠올려요.","손은 보이고, 투표는 안 보이고, 붙임딱지는 남고, 묻기는 대화해요.","네 쌍을 모두 바르게 이어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#3','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'mc','auto','우리 반 30명이 모두 하나씩 골랐는데 표의 합계가 29명이에요. 가장 먼저 할 일은 무엇인가요?',ARRAY['M3-2-u6-X13','M3-2-u6-X10']::text[],true,'{"seq":3,"concept":"M3-2-u6-C6","difficulty":3,"kind":"mc","stem":"우리 반 30명이 모두 하나씩 골랐는데 표의 합계가 29명이에요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"빠뜨린 자료가 없는지 다시 세어 봐요","correct":true},{"t":"합계를 30명으로 고쳐 써요","mis":"M3-2-u6-X13"},{"t":"그대로 그림그래프를 그려요","mis":"M3-2-u6-X13"},{"t":"항목을 하나 더 만들어요","mis":"M3-2-u6-X10"}],"explanation":["합계는 조사한 사람 수와 같아야 해요.","30명과 29명이 달라 빠뜨린 자료가 있어요.","다시 세어 확인해요."],"variant_rule":{"alt":[{"stem":"우리 반 28명이 모두 하나씩 골랐는데 표의 합계가 26명이에요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"빠뜨린 자료가 없는지 다시 세어 봐요","correct":true},{"t":"합계를 28명으로 고쳐 써요","mis":"M3-2-u6-X13"},{"t":"그대로 그림그래프를 그려요","mis":"M3-2-u6-X13"},{"t":"항목을 하나 더 만들어요","mis":"M3-2-u6-X10"}],"explanation":["합계는 조사한 사람 수와 같아야 해요.","28명과 26명이 달라 빠뜨린 자료가 있어요.","다시 세어 확인해요."],"asset":null},{"stem":"우리 반 26명이 모두 하나씩 골랐는데 표의 합계가 25명이에요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"빠뜨린 자료가 없는지 다시 세어 봐요","correct":true},{"t":"합계를 26명으로 고쳐 써요","mis":"M3-2-u6-X13"},{"t":"그대로 그림그래프를 그려요","mis":"M3-2-u6-X13"},{"t":"항목을 하나 더 만들어요","mis":"M3-2-u6-X10"}],"explanation":["합계는 조사한 사람 수와 같아야 해요.","26명과 25명이 달라 빠뜨린 자료가 있어요.","다시 세어 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#4','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'sa','auto','표의 한 칸이 지워졌어요. 합계를 보고 오카리나를 배우고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u6-C6","difficulty":3,"kind":"sa","stem":"표의 한 칸이 지워졌어요. 합계를 보고 오카리나를 배우고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["27"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들.","116 − 33 − 21 − 35 = 27이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[33,null,21,35],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수","total":116},"variant_rule":{"alt":[{"stem":"표의 한 칸이 지워졌어요. 합계를 보고 로봇부에 가입한 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["24"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들.","76 − 14 − 15 − 23 = 24예요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[14,null,15,23],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수","total":76}},{"stem":"표의 한 칸이 지워졌어요. 합계를 보고 박물관에 가고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["24"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들.","66 − 16 − 12 − 14 = 24예요."],"asset":{"type":"picg","only":"table","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[16,null,12,14],"unit":"명","vh":"학생 수","title":"가고 싶어 하는 체험 학습 장소별 학생 수","total":66}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#5','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'sa','auto','친구들이 좋아하는 과일을 붙임딱지에 써서 모았어요. 표로 정리할 때 자두 칸에는 몇을 쓰나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u6-C6","difficulty":3,"kind":"sa","stem":"친구들이 좋아하는 과일을 붙임딱지에 써서 모았어요. 표로 정리할 때 자두 칸에는 몇을 쓰나요? 숫자로 쓰세요.","answer":["2"],"explanation":["붙임딱지를 하나씩 세면서 표시해요.","자두를 고른 친구를 빠짐없이 세어요.","2명이에요."],"asset":{"type":"cards","topic":"fruit","items":[["가온","키위"],["나래","감"],["다솜","감"],["라온","자두"],["마루","포도"],["바다","키위"],["사랑","감"],["아라","키위"],["자람","감"],["차미","자두"],["하늘","포도"],["하람","포도"]]},"variant_rule":{"alt":[{"stem":"친구들이 좋아하는 과일을 붙임딱지에 써서 모았어요. 표로 정리할 때 포도 칸에는 몇을 쓰나요? 숫자로 쓰세요.","answer":["3"],"explanation":["붙임딱지를 하나씩 세면서 표시해요.","포도를 고른 친구를 빠짐없이 세어요.","3명이에요."],"asset":{"type":"cards","topic":"fruit","items":[["가온","포도"],["나래","감"],["다솜","자두"],["라온","감"],["마루","자두"],["바다","감"],["사랑","자두"],["아라","감"],["자람","자두"],["차미","포도"],["하늘","감"],["하람","포도"]]}},{"stem":"친구들이 좋아하는 과일을 붙임딱지에 써서 모았어요. 표로 정리할 때 키위 칸에는 몇을 쓰나요? 숫자로 쓰세요.","answer":["3"],"explanation":["붙임딱지를 하나씩 세면서 표시해요.","키위를 고른 친구를 빠짐없이 세어요.","3명이에요."],"asset":{"type":"cards","topic":"fruit","items":[["가온","감"],["나래","자두"],["다솜","감"],["라온","포도"],["마루","키위"],["바다","포도"],["사랑","자두"],["아라","감"],["자람","키위"],["차미","감"],["하늘","자두"],["하람","키위"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#6','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'mc','auto','항목을 정할 때 알맞은 방법은 무엇인가요?',ARRAY['M3-2-u6-X10','M3-2-u6-X12']::text[],true,'{"seq":6,"concept":"M3-2-u6-C6","difficulty":3,"kind":"mc","stem":"항목을 정할 때 알맞은 방법은 무엇인가요?","options":[{"t":"서로 겹치지 않게 정해요","correct":true},{"t":"비슷한 것을 여러 번 써요","mis":"M3-2-u6-X10"},{"t":"항목은 하나만 정해요","mis":"M3-2-u6-X10"},{"t":"조사한 뒤에 정해요","mis":"M3-2-u6-X12"}],"explanation":["조사 계획은 주제·대상·항목부터 정해요.","항목은 겹치지 않고 빠짐없게 정해요.","답은 「서로 겹치지 않게 정해요」예요."],"variant_rule":{"alt":[{"stem":"어느 항목에도 들어가지 않는 답이 있을 때는 어떻게 하면 좋을까요?","options":[{"t":"「기타」 항목을 만들어 넣어요","correct":true},{"t":"그 답은 버려요","mis":"M3-2-u6-X13"},{"t":"아무 항목에나 넣어요","mis":"M3-2-u6-X13"},{"t":"조사를 처음부터 다시 해요","mis":"M3-2-u6-X12"}],"explanation":["조사 계획은 주제·대상·항목부터 정해요.","항목은 겹치지 않고 빠짐없게 정해요.","답은 「「기타」 항목을 만들어 넣어요」예요."],"asset":null},{"stem":"조사 계획을 세울 때 가장 먼저 정할 것은 무엇인가요?","options":[{"t":"무엇을 누구에게 조사할지","correct":true},{"t":"그림그래프의 그림","mis":"M3-2-u6-X12"},{"t":"표의 합계","mis":"M3-2-u6-X12"},{"t":"그림의 크기","mis":"M3-2-u6-X12"}],"explanation":["조사 계획은 주제·대상·항목부터 정해요.","항목은 겹치지 않고 빠짐없게 정해요.","답은 「무엇을 누구에게 조사할지」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#7','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'mc','auto','친구들이 누구를 골랐는지 서로 모르게 하고 싶어요. 알맞은 조사 방법은 무엇인가요?',ARRAY['M3-2-u6-X11']::text[],true,'{"seq":7,"concept":"M3-2-u6-C6","difficulty":3,"kind":"mc","stem":"친구들이 누구를 골랐는지 서로 모르게 하고 싶어요. 알맞은 조사 방법은 무엇인가요?","options":[{"t":"투표하기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["하고 싶은 것과 방법의 좋은 점을 맞춰 봐요.","투표하기의 좋은 점이 물음과 맞아요.","답은 「투표하기」예요."],"variant_rule":{"alt":[{"stem":"쉬는 시간에 다른 반 친구들의 생각을 자세히 들어 보고 싶어요. 알맞은 조사 방법은 무엇인가요?","options":[{"t":"돌아다니며 묻기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"}],"explanation":["하고 싶은 것과 방법의 좋은 점을 맞춰 봐요.","돌아다니며 묻기의 좋은 점이 물음과 맞아요.","답은 「돌아다니며 묻기」예요."],"asset":null},{"stem":"수업 시간에 아주 빠르게 우리 반 생각을 알아보고 싶어요. 알맞은 조사 방법은 무엇인가요?","options":[{"t":"손 들기","correct":true},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["하고 싶은 것과 방법의 좋은 점을 맞춰 봐요.","손 들기의 좋은 점이 물음과 맞아요.","답은 「손 들기」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#8','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',4,'sa','auto','표에서 가장 많은 것과 가장 적은 것은 몇 명 차이가 나나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u6-C6","difficulty":4,"kind":"sa","stem":"표에서 가장 많은 것과 가장 적은 것은 몇 명 차이가 나나요? 숫자로 쓰세요.","answer":["18"],"explanation":["가장 많은 것은 플루트 33, 가장 적은 것은 오카리나 15예요.","차는 큰 수에서 작은 수를 빼요.","33 − 15 = 18명이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트","리코더"],"counts":[18,15,21,33,30],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 표에서 가장 많은 것과 가장 적은 것은 몇 명 차이가 나나요? 숫자로 쓰세요.","answer":["23"],"explanation":["가장 많은 것은 독서부 32, 가장 적은 것은 미술부 9예요.","차는 큰 수에서 작은 수를 빼요.","32 − 9 = 23명이에요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부","독서부"],"counts":[16,18,31,9,32],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 표에서 가장 많은 것과 가장 적은 것은 몇 명 차이가 나나요? 숫자로 쓰세요.","answer":["25"],"explanation":["가장 많은 것은 놀이공원 34, 가장 적은 것은 과학관 9예요.","차는 큰 수에서 작은 수를 빼요.","34 − 9 = 25명이에요."],"asset":{"type":"picg","only":"table","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[34,20,9,21],"unit":"명","vh":"학생 수","title":"가고 싶어 하는 체험 학습 장소별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#9','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',4,'mc','auto','투표가 끝난 뒤 늦게 온 4명이 모두 오카리나를 골랐어요. 이제 가장 많은 학생이 고른 것은 무엇인가요?',ARRAY['M3-2-u6-X08','M3-2-u6-X16']::text[],true,'{"seq":9,"concept":"M3-2-u6-C6","difficulty":4,"kind":"mc","stem":"투표가 끝난 뒤 늦게 온 4명이 모두 오카리나를 골랐어요. 이제 가장 많은 학생이 고른 것은 무엇인가요?","options":[{"t":"오카리나","correct":true},{"t":"가야금","mis":"M3-2-u6-X08"},{"t":"우쿨렐레","mis":"M3-2-u6-X16"},{"t":"플루트","mis":"M3-2-u6-X08"}],"explanation":["오카리나는 18명에 4명을 더하면 22명이에요.","처음 가장 많았던 우쿨렐레는 21명보다 많아져요.","이제 가장 많은 것은 「오카리나」예요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[16,18,21,17],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수"},"variant_rule":{"alt":[{"stem":"투표가 끝난 뒤 늦게 온 5명이 모두 미술부를 골랐어요. 이제 가장 많은 학생이 고른 것은 무엇인가요?","options":[{"t":"미술부","correct":true},{"t":"합창부","mis":"M3-2-u6-X16"},{"t":"로봇부","mis":"M3-2-u6-X08"},{"t":"축구부","mis":"M3-2-u6-X08"}],"explanation":["미술부는 21명에 5명을 더하면 26명이에요.","처음 가장 많았던 합창부는 25명보다 많아져요.","이제 가장 많은 것은 「미술부」예요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[25,16,18,21],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수"}},{"stem":"투표가 끝난 뒤 늦게 온 5명이 모두 과학관을 골랐어요. 이제 가장 많은 학생이 고른 것은 무엇인가요?","options":[{"t":"과학관","correct":true},{"t":"놀이공원","mis":"M3-2-u6-X16"},{"t":"박물관","mis":"M3-2-u6-X08"},{"t":"동물원","mis":"M3-2-u6-X08"}],"explanation":["과학관은 19명에 5명을 더하면 24명이에요.","처음 가장 많았던 놀이공원은 23명보다 많아져요.","이제 가장 많은 것은 「과학관」이에요."],"asset":{"type":"picg","only":"table","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[23,16,19,18],"unit":"명","vh":"학생 수","title":"가고 싶어 하는 체험 학습 장소별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L04_challenge#10','math',3,2,'u6','L04','g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',4,'essay','teacher','우리 모둠이 조사해 그림그래프로 나타낼 계획을 세우려고 해요. 주제·대상·항목(4~6개)·조사 방법을 정해 쓰고, 그 조사 방법을 고른 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C6","difficulty":4,"kind":"essay","stem":"우리 모둠이 조사해 그림그래프로 나타낼 계획을 세우려고 해요. 주제·대상·항목(4~6개)·조사 방법을 정해 쓰고, 그 조사 방법을 고른 까닭을 써 보세요.","answer_guide":{"answer":"예: 주제 — 우리 반이 좋아하는 운동, 대상 — 우리 반 학생 25명, 항목 — 축구·피구·줄넘기·배드민턴·달리기, 방법 — 투표하기. 친구가 무엇을 골랐는지 몰라 자기 생각대로 고를 수 있기 때문이다.","scoring_points":["직접 조사할 수 있는 분명한 주제와 대상을 썼는가","겹치지 않는 항목 4~6개를 썼는가","조사 방법과 그 방법의 좋은 점으로 까닭을 썼는가"]},"explanation":["무엇을, 누구에게 조사할지 정해요.","항목은 4~6개, 겹치지 않게.","방법의 좋은 점으로 까닭을 대요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#1','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',1,'sa','auto','장미 16송이를 그림그래프로 나타내요. 큰 그림이 5송이, 작은 그림이 1송이를 나타낼 때 5송이 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C7","difficulty":1,"kind":"sa","stem":"장미 16송이를 그림그래프로 나타내요. 큰 그림이 5송이, 작은 그림이 1송이를 나타낼 때 5송이 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 그림부터 그려요.","16송이는 5송이 그림 3개와 1송이 그림 1개예요.","5송이 그림은 3개예요."],"variant_rule":{"alt":[{"stem":"달님 모둠이 모은 붙임딱지 26장을 그림그래프로 나타내요. 큰 그림이 5장, 작은 그림이 1장을 나타낼 때 5장 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["5"],"explanation":["큰 그림부터 그려요.","26장은 5장 그림 5개와 1장 그림 1개예요.","5장 그림은 5개예요."],"asset":null},{"stem":"은비가 운동한 횟수 11회를 그림그래프로 나타내요. 큰 그림이 5회, 작은 그림이 1회를 나타낼 때 5회 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","11회는 5회 그림 2개와 1회 그림 1개예요.","5회 그림은 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#2','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',1,'mc','auto','그림그래프에서 훌라후프를 가장 많이 한 사람은 누구인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X16','M3-2-u6-X04']::text[],true,'{"seq":2,"concept":"M3-2-u6-C7","difficulty":1,"kind":"mc","stem":"그림그래프에서 훌라후프를 가장 많이 한 사람은 누구인가요?","options":[{"t":"은비","correct":true},{"t":"건우","mis":"M3-2-u6-X03"},{"t":"도윤","mis":"M3-2-u6-X16"},{"t":"지유","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 은비 25, 건우 8, 도윤 3, 지유 23.","가장 많은 것은 「은비」예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[25,8,3,23],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 가장 많은 꽃은 무엇인가요?","options":[{"t":"해바라기","correct":true},{"t":"장미","mis":"M3-2-u6-X04"},{"t":"튤립","mis":"M3-2-u6-X03"},{"t":"백합","mis":"M3-2-u6-X16"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 장미 19, 튤립 18, 백합 13, 해바라기 21.","가장 많은 것은 「해바라기」예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[19,18,13,21],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"}},{"stem":"그림그래프에서 붙임딱지를 가장 많이 모은 모둠은 어느 모둠인가요?","options":[{"t":"별님 모둠","correct":true},{"t":"해님 모둠","mis":"M3-2-u6-X03"},{"t":"달님 모둠","mis":"M3-2-u6-X16"},{"t":"구름 모둠","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 해님 모둠 15, 달님 모둠 13, 별님 모둠 25, 구름 모둠 22.","가장 많은 것은 「별님 모둠」이에요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[15,13,25,22],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#3','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',1,'sa','auto','해님 모둠이 모은 붙임딱지 17장을 그림그래프로 나타내요. 큰 그림이 5장, 작은 그림이 1장을 나타낼 때 1장 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C7","difficulty":1,"kind":"sa","stem":"해님 모둠이 모은 붙임딱지 17장을 그림그래프로 나타내요. 큰 그림이 5장, 작은 그림이 1장을 나타낼 때 1장 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","17장은 5장 그림 3개와 1장 그림 2개예요.","1장 그림은 2개예요."],"variant_rule":{"alt":[{"stem":"서준이 운동한 횟수 22회를 그림그래프로 나타내요. 큰 그림이 5회, 작은 그림이 1회를 나타낼 때 1회 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","22회는 5회 그림 4개와 1회 그림 2개예요.","1회 그림은 2개예요."],"asset":null},{"stem":"도윤이 훌라후프를 한 횟수 27회를 그림그래프로 나타내요. 큰 그림이 5회, 작은 그림이 1회를 나타낼 때 1회 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","27회는 5회 그림 5개와 1회 그림 2개예요.","1회 그림은 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#4','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',1,'mc','auto','모은 자료를 표(장미 11송이, 튤립 22송이, 백합 18송이, 해바라기 13송이)로 정리한 뒤 친구가 그림그래프로 나타냈어요. 무엇이 잘못되었나요?',ARRAY['M3-2-u6-X07','M3-2-u6-X15','M3-2-u6-X13']::text[],true,'{"seq":4,"concept":"M3-2-u6-C7","difficulty":1,"kind":"mc","stem":"모은 자료를 표(장미 11송이, 튤립 22송이, 백합 18송이, 해바라기 13송이)로 정리한 뒤 친구가 그림그래프로 나타냈어요. 무엇이 잘못되었나요?","options":[{"t":"백합이 빠졌어요","correct":true},{"t":"제목이 없어요","mis":"M3-2-u6-X07"},{"t":"그림이 너무 커요","mis":"M3-2-u6-X15"},{"t":"잘못된 것이 없어요","mis":"M3-2-u6-X13"}],"explanation":["표의 항목과 그림그래프의 항목을 하나씩 맞춰 봐요.","백합 줄이 통째로 없어요.","조사한 항목을 빠짐없이 써야 해요 — 백합이 빠졌어요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","해바라기"],"counts":[11,22,13],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수","table":false},"variant_rule":{"alt":[{"stem":"모은 자료를 표(해님 모둠 3장, 달님 모둠 22장, 별님 모둠 8장, 구름 모둠 11장)로 정리한 뒤 친구가 그림그래프로 나타냈어요. 무엇이 잘못되었나요?","options":[{"t":"구름 모둠이 빠졌어요","correct":true},{"t":"제목이 없어요","mis":"M3-2-u6-X07"},{"t":"그림이 너무 커요","mis":"M3-2-u6-X15"},{"t":"잘못된 것이 없어요","mis":"M3-2-u6-X13"}],"explanation":["표의 항목과 그림그래프의 항목을 하나씩 맞춰 봐요.","구름 모둠 줄이 통째로 없어요.","조사한 항목을 빠짐없이 써야 해요 — 구름 모둠이 빠졌어요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠"],"counts":[3,22,8],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수","table":false}},{"stem":"모은 자료를 표(건우 4회, 서준 11회, 은비 6회, 지유 3회)로 정리한 뒤 친구가 그림그래프로 나타냈어요. 무엇이 잘못되었나요?","options":[{"t":"서준이 빠졌어요","correct":true},{"t":"제목이 없어요","mis":"M3-2-u6-X07"},{"t":"그림이 너무 커요","mis":"M3-2-u6-X15"},{"t":"잘못된 것이 없어요","mis":"M3-2-u6-X13"}],"explanation":["표의 항목과 그림그래프의 항목을 하나씩 맞춰 봐요.","서준 줄이 통째로 없어요.","조사한 항목을 빠짐없이 써야 해요 — 서준이 빠졌어요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","은비","지유"],"counts":[4,6,3],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수","table":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#5','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'sa','auto','그림그래프를 보고 횟수의 합계를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u6-C7","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 횟수의 합계를 구하세요. 숫자로 쓰세요.","answer":["75"],"explanation":["줄마다 수를 먼저 읽어요 — 은비 23, 건우 4, 도윤 26, 지유 22.","네 수를 모두 더해요.","23 + 4 + 26 + 22 = 75회예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[23,4,26,22],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 꽃의 수의 합계를 구하세요. 숫자로 쓰세요.","answer":["54"],"explanation":["줄마다 수를 먼저 읽어요 — 장미 5, 튤립 15, 백합 26, 해바라기 8.","네 수를 모두 더해요.","5 + 15 + 26 + 8 = 54송이예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[5,15,26,8],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"}},{"stem":"그림그래프를 보고 붙임딱지의 수의 합계를 구하세요. 숫자로 쓰세요.","answer":["74"],"explanation":["줄마다 수를 먼저 읽어요 — 해님 모둠 25, 달님 모둠 28, 별님 모둠 9, 구름 모둠 12.","네 수를 모두 더해요.","25 + 28 + 9 + 12 = 74장이에요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[25,28,9,12],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#6','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'mc','auto','그림그래프에서 붙임딱지를 가장 적게 모은 모둠은 어느 모둠인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16','M3-2-u6-X03']::text[],true,'{"seq":6,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"그림그래프에서 붙임딱지를 가장 적게 모은 모둠은 어느 모둠인가요?","options":[{"t":"구름 모둠","correct":true},{"t":"해님 모둠","mis":"M3-2-u6-X04"},{"t":"달님 모둠","mis":"M3-2-u6-X16"},{"t":"별님 모둠","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 가장 적은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 해님 모둠 15, 달님 모둠 27, 별님 모둠 26, 구름 모둠 13.","가장 적은 것은 「구름 모둠」이에요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[15,27,26,13],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 가장 적게 운동한 사람은 누구인가요?","options":[{"t":"은비","correct":true},{"t":"건우","mis":"M3-2-u6-X03"},{"t":"서준","mis":"M3-2-u6-X16"},{"t":"지유","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 가장 적은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 건우 9, 서준 12, 은비 4, 지유 7.","가장 적은 것은 「은비」예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[9,12,4,7],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수"}},{"stem":"그림그래프에서 훌라후프를 가장 적게 한 사람은 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"은비","mis":"M3-2-u6-X04"},{"t":"건우","mis":"M3-2-u6-X03"},{"t":"지유","mis":"M3-2-u6-X16"}],"explanation":["큰 그림이 가장 적은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 은비 10, 건우 13, 도윤 7, 지유 25.","가장 적은 것은 「도윤」이에요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[10,13,7,25],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#7','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'mc','auto','그림그래프를 다 그린 뒤 무엇을 확인하면 좋을까요?',ARRAY['M3-2-u6-X13','M3-2-u6-X07','M3-2-u6-X06']::text[],true,'{"seq":7,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"그림그래프를 다 그린 뒤 무엇을 확인하면 좋을까요?","options":[{"t":"그림이 나타내는 수의 합이 표의 합계와 같은지","correct":true},{"t":"그림이 모두 같은 색인지","mis":"M3-2-u6-X13"},{"t":"제목이 가장 긴지","mis":"M3-2-u6-X07"},{"t":"그림이 모두 작은지","mis":"M3-2-u6-X06"}],"explanation":["다 그린 뒤에는 빠짐과 틀림을 확인해요.","항목은 표와, 그림의 합은 표의 합계와 견줘요.","답은 「그림이 나타내는 수의 합이 표의 합계와 같은지」예요."],"variant_rule":{"alt":[{"stem":"그림그래프에 빠진 항목이 없는지 알아보려면 무엇과 견주면 되나요?","options":[{"t":"표의 항목","correct":true},{"t":"그림의 크기","mis":"M3-2-u6-X15"},{"t":"그림의 색깔","mis":"M3-2-u6-X13"},{"t":"제목의 글자 수","mis":"M3-2-u6-X07"}],"explanation":["다 그린 뒤에는 빠짐과 틀림을 확인해요.","항목은 표와, 그림의 합은 표의 합계와 견줘요.","답은 「표의 항목」이에요."],"asset":null},{"stem":"그림을 덜 그리거나 더 그린 곳이 있는지 알아보는 방법은 무엇인가요?","options":[{"t":"그림이 나타내는 수를 모두 더해 표의 합계와 견주어요","correct":true},{"t":"그림의 개수만 세어 봐요","mis":"M3-2-u6-X01"},{"t":"가장 큰 그림만 세어 봐요","mis":"M3-2-u6-X04"},{"t":"제목을 다시 읽어요","mis":"M3-2-u6-X07"}],"explanation":["다 그린 뒤에는 빠짐과 틀림을 확인해요.","항목은 표와, 그림의 합은 표의 합계와 견줘요.","답은 「그림이 나타내는 수를 모두 더해 표의 합계와 견주어요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#8','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'sa','auto','그림그래프를 보고 건우가 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u6-C7","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 건우가 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["12"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","건우 줄은 5회 그림 2개와 1회 그림 2개예요.","건우가 운동한 횟수는 12회예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[12,27,21,3],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 지유가 훌라후프를 한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["9"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","지유 줄은 5회 그림 1개와 1회 그림 4개예요.","지유가 훌라후프를 한 횟수는 9회예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[18,13,24,9],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}},{"stem":"그림그래프를 보고 해바라기는 몇 송이인지 구하세요. 숫자로 쓰세요.","answer":["15"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5송이, 작은 그림 1송이.","해바라기 줄은 5송이 그림 3개예요.","해바라기는 15송이예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[20,9,29,15],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#9','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'sa','auto','표의 합계는 80장이에요. 친구가 그린 그림그래프에서 그림이 나타내는 수를 모두 더하면 몇 장인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u6-C7","difficulty":2,"kind":"sa","stem":"표의 합계는 80장이에요. 친구가 그린 그림그래프에서 그림이 나타내는 수를 모두 더하면 몇 장인가요? 숫자로 쓰세요.","answer":["78"],"explanation":["줄마다 수를 읽어요 — 해님 모둠 22, 달님 모둠 27, 별님 모둠 18, 구름 모둠 11.","모두 더하면 22 + 27 + 18 + 11 = 78이에요.","표의 합계 80과 달라 어딘가를 덜 그렸어요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[22,27,20,11],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수","drawn":[22,27,18,11]},"variant_rule":{"alt":[{"stem":"표의 합계는 68회예요. 친구가 그린 그림그래프에서 그림이 나타내는 수를 모두 더하면 몇 회인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["줄마다 수를 읽어요 — 건우 11, 서준 4, 은비 19, 지유 29.","모두 더하면 11 + 4 + 19 + 29 = 63이에요.","표의 합계 68과 달라 어딘가를 덜 그렸어요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[16,4,19,29],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수","drawn":[11,4,19,29]}},{"stem":"표의 합계는 59회예요. 친구가 그린 그림그래프에서 그림이 나타내는 수를 모두 더하면 몇 회인가요? 숫자로 쓰세요.","answer":["57"],"explanation":["줄마다 수를 읽어요 — 은비 22, 건우 4, 도윤 15, 지유 16.","모두 더하면 22 + 4 + 15 + 16 = 57이에요.","표의 합계 59와 달라 어딘가를 덜 그렸어요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[22,4,15,18],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수","drawn":[22,4,15,16]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_basic#10','math',3,2,'u6','L05','g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',3,'ox','auto','큰 그림이 5회, 작은 그림이 1회인 그림그래프예요. 은비 줄은 큰 그림 4개와 작은 그림 2개이니 42회예요.',ARRAY['M3-2-u6-X02']::text[],true,'{"seq":10,"concept":"M3-2-u6-C7","difficulty":3,"kind":"ox","stem":"큰 그림이 5회, 작은 그림이 1회인 그림그래프예요. 은비 줄은 큰 그림 4개와 작은 그림 2개이니 42회예요.","answer":"X","reason_options":[{"t":"큰 그림 4개는 20회라 모두 22회여서","correct":true},{"t":"큰 그림 하나가 10회여서","mis":"M3-2-u6-X02"}],"mis":"M3-2-u6-X02","explanation":["큰 그림 한 개는 5회예요.","4 × 5 = 20, 20 + 2 = 22.","22회가 맞아 틀린 말이에요(X)."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우"],"counts":[22,23],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"큰 그림이 5송이, 작은 그림이 1송이인 그림그래프예요. 장미 줄은 큰 그림 5개와 작은 그림 4개이니 29송이예요.","answer":"O","reason_options":[{"t":"큰 그림 5개는 25송이, 작은 그림 4개는 4송이여서","correct":true},{"t":"그림이 모두 9개라서","mis":"M3-2-u6-X01"}],"explanation":["큰 그림 한 개는 5송이예요.","25 + 4 = 29.","맞는 말이에요(O)."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립"],"counts":[29,6],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"}},{"stem":"큰 그림이 5장, 작은 그림이 1장인 그림그래프예요. 해님 모둠 줄은 큰 그림 4개와 작은 그림 3개이니 43장이에요.","answer":"X","reason_options":[{"t":"큰 그림 4개는 20장이라 모두 23장이어서","correct":true},{"t":"큰 그림 하나가 10장이어서","mis":"M3-2-u6-X02"}],"explanation":["큰 그림 한 개는 5장이에요.","4 × 5 = 20, 20 + 3 = 23.","23장이 맞아 틀린 말이에요(X)."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠"],"counts":[23,24],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#1','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',2,'mc','auto','해님 모둠이 모은 붙임딱지 11장을 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":1,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"해님 모둠이 모은 붙임딱지 11장을 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5장 그림 2개와 1장 그림 1개","correct":true},{"t":"5장 그림 1개와 1장 그림 2개","mis":"M3-2-u6-X05"},{"t":"1장 그림 11개","mis":"M3-2-u6-X06"},{"t":"5장 그림 1개와 1장 그림 1개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 5장이에요.","11장은 큰 그림 2개, 남은 1장은 작은 그림 1개예요.","답은 「5장 그림 2개와 1장 그림 1개」예요."],"variant_rule":{"alt":[{"stem":"서준이 운동한 횟수 29회를 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5회 그림 5개와 1회 그림 4개","correct":true},{"t":"5회 그림 4개와 1회 그림 5개","mis":"M3-2-u6-X05"},{"t":"1회 그림 29개","mis":"M3-2-u6-X06"},{"t":"5회 그림 2개와 1회 그림 9개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 5회예요.","29회는 큰 그림 5개, 남은 4회는 작은 그림 4개예요.","답은 「5회 그림 5개와 1회 그림 4개」예요."],"asset":null},{"stem":"도윤이 훌라후프를 한 횟수 22회를 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5회 그림 4개와 1회 그림 2개","correct":true},{"t":"5회 그림 2개와 1회 그림 4개","mis":"M3-2-u6-X05"},{"t":"1회 그림 22개","mis":"M3-2-u6-X06"},{"t":"5회 그림 2개와 1회 그림 2개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 5회예요.","22회는 큰 그림 4개, 남은 2회는 작은 그림 2개예요.","답은 「5회 그림 4개와 1회 그림 2개」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#2','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',2,'sa','auto','그림그래프에서 건우가 운동한 횟수는 서준이 운동한 횟수보다 몇 회 더 많나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C7","difficulty":2,"kind":"sa","stem":"그림그래프에서 건우가 운동한 횟수는 서준이 운동한 횟수보다 몇 회 더 많나요? 숫자로 쓰세요.","answer":["7"],"explanation":["건우는 14회, 서준은 7회예요.","더 많은 수에서 적은 수를 빼요.","14 − 7 = 7회예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[14,7,25,3],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 도윤이 훌라후프를 한 횟수는 건우가 훌라후프를 한 횟수보다 몇 회 더 많나요? 숫자로 쓰세요.","answer":["13"],"explanation":["도윤은 22회, 건우는 9회예요.","더 많은 수에서 적은 수를 빼요.","22 − 9 = 13회예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[3,9,22,8],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}},{"stem":"그림그래프에서 튤립은 장미보다 몇 송이 더 많나요? 숫자로 쓰세요.","answer":["14"],"explanation":["튤립은 27송이, 장미는 13송이예요.","더 많은 수에서 적은 수를 빼요.","27 − 13 = 14송이예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[13,27,5,24],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#3','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'mc','auto','표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?',ARRAY['M3-2-u6-X13']::text[],true,'{"seq":3,"concept":"M3-2-u6-C7","difficulty":3,"kind":"mc","stem":"표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"은비","correct":true},{"t":"건우","mis":"M3-2-u6-X13"},{"t":"도윤","mis":"M3-2-u6-X13"},{"t":"지유","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","은비 줄은 5회 그림 1개와 1회 그림 4개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「은비」예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[9,22,11,21],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수","table":true,"pieces":[[4,1],[4,2],[2,1],[4,1]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"장미","correct":true},{"t":"튤립","mis":"M3-2-u6-X13"},{"t":"백합","mis":"M3-2-u6-X13"},{"t":"해바라기","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","장미 줄은 5송이 그림 1개와 1송이 그림 3개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「장미」예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[8,11,27,26],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수","table":true,"pieces":[[3,1],[2,1],[5,2],[5,1]]}},{"stem":"이번에는 다른 그림이에요. 표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"별님 모둠","correct":true},{"t":"해님 모둠","mis":"M3-2-u6-X13"},{"t":"달님 모둠","mis":"M3-2-u6-X13"},{"t":"구름 모둠","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","별님 모둠 줄은 5장 그림 5개와 1장 그림 2개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「별님 모둠」이에요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[17,29,27,11],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수","table":true,"pieces":[[3,2],[5,4],[2,5],[2,1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#4','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'sa','auto','표를 보고 그린 그림그래프에서 장미 줄을 덜 그렸어요. 1송이 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"표를 보고 그린 그림그래프에서 장미 줄을 덜 그렸어요. 1송이 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["표에서 장미는 19송이예요.","그림은 17송이만 나타내고 있어요.","19 − 17 = 2개 더 그려요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[19,29,22,9],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수","table":true,"pieces":[[3,2],[5,4],[4,2],[1,4]]},"variant_rule":{"alt":[{"stem":"표를 보고 그린 그림그래프에서 별님 모둠 줄을 덜 그렸어요. 1장 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["표에서 별님 모둠은 28장이에요.","그림은 27장만 나타내고 있어요.","28 − 27 = 1개 더 그려요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[27,12,28,3],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수","table":true,"pieces":[[5,2],[2,2],[5,2],[0,3]]}},{"stem":"표를 보고 그린 그림그래프에서 은비 줄을 덜 그렸어요. 1회 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["표에서 은비는 14회예요.","그림은 11회만 나타내고 있어요.","14 − 11 = 3개 더 그려요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[22,23,14,7],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수","table":true,"pieces":[[4,2],[4,3],[2,1],[1,2]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#5','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'sa','auto','표를 보고 그림그래프를 그리고 있어요. 비어 있는 구름 모둠 줄에 5장 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"표를 보고 그림그래프를 그리고 있어요. 비어 있는 구름 모둠 줄에 5장 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["표에서 구름 모둠은 14장이에요.","5장 그림 2개와 1장 그림 4개예요.","2개예요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[19,26,28,14],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수","table":true,"blank":[3]},"variant_rule":{"alt":[{"stem":"표를 보고 그림그래프를 그리고 있어요. 비어 있는 건우 줄에 1회 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["표에서 건우는 11회예요.","5회 그림 2개와 1회 그림 1개예요.","1개예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,16,24,13],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수","table":true,"blank":[0]}},{"stem":"표를 보고 그림그래프를 그리고 있어요. 비어 있는 도윤 줄에 5회 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["표에서 도윤은 15회예요.","5회 그림 3개예요.","3개예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[29,25,15,17],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수","table":true,"blank":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#6','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'sa','auto','큰 그림 10회, 작은 그림 1회로 나타낸 그림그래프예요. 서준 줄을 큰 그림 5회, 작은 그림 1회로 바꾸어 그리면 그림은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"큰 그림 10회, 작은 그림 1회로 나타낸 그림그래프예요. 서준 줄을 큰 그림 5회, 작은 그림 1회로 바꾸어 그리면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["서준은 27회예요.","5회 그림 5개와 1회 그림 2개예요.","모두 7개예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[29,27,18,16],"units":[10,1],"icon":"🏃","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"큰 그림 10회, 작은 그림 1회로 나타낸 그림그래프예요. 도윤 줄을 큰 그림 5회, 작은 그림 1회로 바꾸어 그리면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["도윤은 11회예요.","5회 그림 2개와 1회 그림 1개예요.","모두 3개예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[27,24,11,12],"units":[10,1],"icon":"⭕","unit":"회","vh":"횟수"}},{"stem":"큰 그림 10송이, 작은 그림 1송이로 나타낸 그림그래프예요. 튤립 줄을 큰 그림 5송이, 작은 그림 1송이로 바꾸어 그리면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["튤립은 21송이예요.","5송이 그림 4개와 1송이 그림 1개예요.","모두 5개예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[17,21,23,27],"units":[10,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#7','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'error','auto','그림그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u6-X01','M3-2-u6-X16','M3-2-u6-X02']::text[],true,'{"seq":7,"concept":"M3-2-u6-C7","difficulty":3,"kind":"error","stem":"그림그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「구름 모둠 그림이 4개니까 4장이야.」","correct":true,"mis_target":"M3-2-u6-X01"},{"t":"시우 — 「가장 많은 것은 별님 모둠이에요.」","mis":"M3-2-u6-X16"},{"t":"은우 — 「가장 적은 것은 해님 모둠이에요.」","mis":"M3-2-u6-X16"},{"t":"하랑 — 「큰 그림은 5장을 나타내.」","mis":"M3-2-u6-X02"}],"explanation":["그림의 개수만 세면 안 돼요.","구름 모둠 줄은 5장 그림 2개와 1장 그림 2개라서 12장이에요.","서윤의 말이 잘못이에요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[7,9,19,12],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「건우 그림이 4개니까 4회이야.」","correct":true,"mis_target":"M3-2-u6-X01"},{"t":"은우 — 「가장 많은 것은 서준이에요.」","mis":"M3-2-u6-X16"},{"t":"하랑 — 「가장 적은 것은 지유예요.」","mis":"M3-2-u6-X16"},{"t":"지아 — 「큰 그림은 5회를 나타내.」","mis":"M3-2-u6-X02"}],"explanation":["그림의 개수만 세면 안 돼요.","건우 줄은 5회 그림 1개와 1회 그림 3개라서 8회예요.","시우의 말이 잘못이에요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[8,12,6,4],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수"}},{"stem":"이번에는 다른 그림이에요. 그림그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「도윤 그림이 3개니까 3회이야.」","correct":true,"mis_target":"M3-2-u6-X01"},{"t":"하랑 — 「가장 많은 것은 건우예요.」","mis":"M3-2-u6-X16"},{"t":"지아 — 「가장 적은 것은 도윤이에요.」","mis":"M3-2-u6-X16"},{"t":"민호 — 「큰 그림은 5회를 나타내.」","mis":"M3-2-u6-X02"}],"explanation":["그림의 개수만 세면 안 돼요.","도윤 줄은 5회 그림 1개와 1회 그림 2개라서 7회예요.","은우의 말이 잘못이에요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[16,29,7,11],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#8','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',4,'sa','auto','횟수의 합계는 57회예요. 그림그래프에서 은비 줄이 지워졌어요. 은비가 운동한 횟수는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u6-C7","difficulty":4,"kind":"sa","stem":"횟수의 합계는 57회예요. 그림그래프에서 은비 줄이 지워졌어요. 은비가 운동한 횟수는 몇 회인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["보이는 줄의 수를 읽어요 — 24, 18, 8.","모르는 수 = 합계 − 아는 수들이에요.","57 − 24 − 18 − 8 = 7회예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[24,18,null,8],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수","blank":[2]},"variant_rule":{"alt":[{"stem":"횟수의 합계는 59회예요. 그림그래프에서 도윤 줄이 지워졌어요. 도윤이 훌라후프를 한 횟수는 몇 회인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["보이는 줄의 수를 읽어요 — 17, 3, 12.","모르는 수 = 합계 − 아는 수들이에요.","59 − 17 − 3 − 12 = 27회예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[17,3,null,12],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수","blank":[2]}},{"stem":"꽃의 수의 합계는 64송이예요. 그림그래프에서 해바라기 줄이 지워졌어요. 해바라기는 몇 송이인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["보이는 줄의 수를 읽어요 — 8, 27, 14.","모르는 수 = 합계 − 아는 수들이에요.","64 − 8 − 27 − 14 = 15송이예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[8,27,14,null],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수","blank":[3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#9','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',4,'mc','auto','이 표를 큰 그림 하나가 5회, 작은 그림 하나가 1회를 나타내도록 그림그래프로 나타내면 그림을 가장 많이 그리는 것은 어느 것인가요?',ARRAY['M3-2-u6-X06','M3-2-u6-X03']::text[],true,'{"seq":9,"concept":"M3-2-u6-C7","difficulty":4,"kind":"mc","stem":"이 표를 큰 그림 하나가 5회, 작은 그림 하나가 1회를 나타내도록 그림그래프로 나타내면 그림을 가장 많이 그리는 것은 어느 것인가요?","options":[{"t":"건우","correct":true},{"t":"은비","mis":"M3-2-u6-X06"},{"t":"도윤","mis":"M3-2-u6-X03"},{"t":"지유","mis":"M3-2-u6-X06"}],"explanation":["줄마다 5로 몇 번 묶이고 몇이 남는지 봐요.","은비 8 → 4개, 건우 19 → 7개, 도윤 25 → 5개, 지유 15 → 3개.","가장 많이 그리는 것은 건우예요 — 수가 가장 큰 것과 달라요."],"asset":{"type":"picg","only":"table","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[8,19,25,15],"unit":"회","vh":"횟수","title":"훌라후프를 한 횟수","total":false},"variant_rule":{"alt":[{"stem":"이 표를 큰 그림 하나가 5송이, 작은 그림 하나가 1송이를 나타내도록 그림그래프로 나타내면 그림을 가장 많이 그리는 것은 어느 것인가요?","options":[{"t":"백합","correct":true},{"t":"장미","mis":"M3-2-u6-X03"},{"t":"튤립","mis":"M3-2-u6-X06"},{"t":"해바라기","mis":"M3-2-u6-X06"}],"explanation":["줄마다 5로 몇 번 묶이고 몇이 남는지 봐요.","장미 20 → 4개, 튤립 7 → 3개, 백합 19 → 7개, 해바라기 6 → 2개.","가장 많이 그리는 것은 백합이에요 — 수가 가장 큰 것과 달라요."],"asset":{"type":"picg","only":"table","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[20,7,19,6],"unit":"송이","vh":"꽃의 수","title":"종류별 꽃의 수","total":false}},{"stem":"이 표를 큰 그림 하나가 5장, 작은 그림 하나가 1장을 나타내도록 그림그래프로 나타내면 그림을 가장 많이 그리는 것은 어느 것인가요?","options":[{"t":"해님 모둠","correct":true},{"t":"달님 모둠","mis":"M3-2-u6-X03"},{"t":"별님 모둠","mis":"M3-2-u6-X06"},{"t":"구름 모둠","mis":"M3-2-u6-X06"}],"explanation":["줄마다 5로 몇 번 묶이고 몇이 남는지 봐요.","해님 모둠 24 → 8개, 달님 모둠 26 → 6개, 별님 모둠 11 → 3개, 구름 모둠 25 → 5개.","가장 많이 그리는 것은 해님 모둠이에요 — 수가 가장 큰 것과 달라요."],"asset":{"type":"picg","only":"table","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[24,26,11,25],"unit":"장","vh":"붙임딱지의 수","title":"모둠별 모은 칭찬 붙임딱지의 수","total":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L05_challenge#10','math',3,2,'u6','L05','g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',4,'essay','teacher','모둠이 운동한 횟수(건우 11회, 서준 22회, 은비 13회, 지유 9회)를 큰 그림 5회, 작은 그림 1회로 그림그래프에 나타냈어요. 다 그린 뒤 바르게 그렸는지 확인하는 방법 두 가지를 쓰고, 서준의 줄을 어떻게 그려야 하는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C7","difficulty":4,"kind":"essay","stem":"모둠이 운동한 횟수(건우 11회, 서준 22회, 은비 13회, 지유 9회)를 큰 그림 5회, 작은 그림 1회로 그림그래프에 나타냈어요. 다 그린 뒤 바르게 그렸는지 확인하는 방법 두 가지를 쓰고, 서준의 줄을 어떻게 그려야 하는지 써 보세요.","answer_guide":{"answer":"예: 표의 이름이 그림그래프에 빠짐없이 있는지 확인한다. 그림이 나타내는 수를 모두 더해 표의 합계 55회와 같은지 확인한다. 서준 22회는 5회 그림 4개와 1회 그림 2개로 그린다.","scoring_points":["빠진 항목이 없는지 확인한다고 썼는가","그림의 합을 표의 합계(55회)와 견준다고 썼는가","22회를 5회 그림 4개와 1회 그림 2개로 나타냈는가"]},"explanation":["항목은 표와 견줘요.","그림의 합 = 표의 합계 55회인지 봐요.","22 = 5 × 4 + 2."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_basic#1','math',3,2,'u6','L06','g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',1,'sa','auto','나 그림그래프에서 여름의 산불 발생 건수 334건을 나타낼 때 100건 그림은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C8","difficulty":1,"kind":"sa","stem":"나 그림그래프에서 여름의 산불 발생 건수 334건을 나타낼 때 100건 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나는 100건·10건·1건 세 가지 그림이에요.","334건은 100건 그림 3개, 10건 그림 3개와 1건 그림 4개예요.","100건 그림은 3개예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[194,334,242,216],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"나 그림그래프에서 화요일에 도서관을 찾은 사람 216명을 나타낼 때 100명 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나는 100명·10명·1명 세 가지 그림이에요.","216명은 100명 그림 2개, 10명 그림 1개와 1명 그림 6개예요.","100명 그림은 2개예요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수 — 가: 10·1, 나: 100·10·1","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[127,216,399,129],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수","units2":[100,10,1]}},{"stem":"나 그림그래프에서 구름 마을의 사과 생산량 211상자를 나타낼 때 100상자 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나는 100상자·10상자·1상자 세 가지 그림이에요.","211상자는 100상자 그림 2개, 10상자 그림 1개와 1상자 그림 1개예요.","100상자 그림은 2개예요."],"asset":{"type":"picg","title":"마을별 사과 생산량 — 가: 10·1, 나: 100·10·1","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[299,199,211,197],"units":[10,1],"icon":"🍎","unit":"상자","vh":"생산량","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_activ