INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_basic#7','math',3,2,'u6','L06','g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',2,'mc','auto','단위의 종류가 늘어나면 불편한 점은 무엇인가요?',ARRAY['M3-2-u6-X14','M3-2-u6-X07']::text[],true,'{"seq":7,"concept":"M3-2-u6-C8","difficulty":2,"kind":"mc","stem":"단위의 종류가 늘어나면 불편한 점은 무엇인가요?","options":[{"t":"그림의 크기를 뚜렷이 구분해 그리기 어려워요","correct":true},{"t":"큰 수를 나타낼 수 없어요","mis":"M3-2-u6-X14"},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"제목을 쓸 수 없어요","mis":"M3-2-u6-X07"}],"explanation":["단위가 늘면 그림 크기가 셋, 넷으로 늘어나요.","크기가 비슷하면 어떤 그림인지 헷갈려요.","답은 「그림의 크기를 뚜렷이 구분해 그리기 어려워요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"나 그림그래프를 읽을 때 조심할 점은 무엇인가요?","options":[{"t":"세 가지 크기의 그림을 잘 구분해 읽어요","correct":true},{"t":"그림의 개수만 세어요","mis":"M3-2-u6-X01"},{"t":"가장 큰 그림만 세어요","mis":"M3-2-u6-X06"},{"t":"작은 그림은 빼고 읽어요","mis":"M3-2-u6-X06"}],"explanation":["단위가 늘면 그림 크기가 셋, 넷으로 늘어나요.","크기가 비슷하면 어떤 그림인지 헷갈려요.","답은 「세 가지 크기의 그림을 잘 구분해 읽어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"그림의 단위를 네 가지, 다섯 가지로 계속 늘리면 어떤 점이 어려울까요?","options":[{"t":"그림의 크기를 구분하기가 더 어려워요","correct":true},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"큰 수를 나타낼 수 없어요","mis":"M3-2-u6-X14"},{"t":"항목을 쓸 수 없어요","mis":"M3-2-u6-X07"}],"explanation":["단위가 늘면 그림 크기가 셋, 넷으로 늘어나요.","크기가 비슷하면 어떤 그림인지 헷갈려요.","답은 「그림의 크기를 구분하기가 더 어려워요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_basic#8','math',3,2,'u6','L06','g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',2,'sa','auto','계절별 산불 발생 건수의 합계는 몇 건인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"계절별 산불 발생 건수의 합계는 몇 건인가요? 숫자로 쓰세요.","answer":["756"],"explanation":["계절마다 건수를 읽어요 — 봄 377, 여름 29, 가을 82, 겨울 268.","네 수를 모두 더해요.","377 + 29 + 82 + 268 = 756건이에요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 계절별 산불 발생 건수의 합계는 몇 건인가요? 숫자로 쓰세요.","answer":["694"],"explanation":["계절마다 건수를 읽어요 — 봄 312, 여름 46, 가을 95, 겨울 241.","네 수를 모두 더해요.","312 + 46 + 95 + 241 = 694건이에요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"이번에는 다른 그림이에요. 계절별 산불 발생 건수의 합계는 몇 건인가요? 숫자로 쓰세요.","answer":["652"],"explanation":["계절마다 건수를 읽어요 — 봄 286, 여름 37, 가을 124, 겨울 205.","네 수를 모두 더해요.","286 + 37 + 124 + 205 = 652건이에요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_basic#9','math',3,2,'u6','L06','g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C9',2,'mc','auto','그림의 가로와 세로를 함께 2배로 그리면 그림의 넓이는 몇 배가 되나요?',ARRAY['M3-2-u6-X15']::text[],true,'{"seq":9,"concept":"M3-2-u6-C9","difficulty":2,"kind":"mc","stem":"그림의 가로와 세로를 함께 2배로 그리면 그림의 넓이는 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M3-2-u6-X15"},{"t":"같아요","mis":"M3-2-u6-X15"},{"t":"8배","mis":"M3-2-u6-X15"}],"explanation":["가로 2배, 세로 2배로 하면 처음 그림이 가로로 2개, 세로로 2개 들어가요.","2 × 2 = 4 — 넓이는 4배예요.","그래서 크기만 보면 실제보다 훨씬 많아 보여요."],"variant_rule":{"alt":[{"stem":"작은 그림을 가로 2배, 세로 2배로 키워 그렸어요. 그림이 차지하는 넓이는 처음의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M3-2-u6-X15"},{"t":"같아요","mis":"M3-2-u6-X15"},{"t":"8배","mis":"M3-2-u6-X15"}],"explanation":["가로 2배, 세로 2배로 하면 처음 그림이 가로로 2개, 세로로 2개 들어가요.","2 × 2 = 4 — 넓이는 4배예요.","그래서 크기만 보면 실제보다 훨씬 많아 보여요."],"asset":null},{"stem":"네모 칸 그림의 가로와 세로를 모두 2배로 늘렸어요. 넓이는 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M3-2-u6-X15"},{"t":"같아요","mis":"M3-2-u6-X15"},{"t":"8배","mis":"M3-2-u6-X15"}],"explanation":["가로 2배, 세로 2배로 하면 처음 그림이 가로로 2개, 세로로 2개 들어가요.","2 × 2 = 4 — 넓이는 4배예요.","그래서 크기만 보면 실제보다 훨씬 많아 보여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_basic#10','math',3,2,'u6','L06','g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',3,'ox','auto','가와 나는 같은 자료를 나타냈으므로 겨울의 산불 발생 건수는 두 그림그래프에서 같아요.',ARRAY['M3-2-u6-X14']::text[],true,'{"seq":10,"concept":"M3-2-u6-C8","difficulty":3,"kind":"ox","stem":"가와 나는 같은 자료를 나타냈으므로 겨울의 산불 발생 건수는 두 그림그래프에서 같아요.","answer":"O","reason_options":[{"t":"단위만 다르고 나타낸 건수는 268건으로 같아서","correct":true},{"t":"그림의 개수가 달라서 건수도 달라서","mis":"M3-2-u6-X14"}],"mis":"M3-2-u6-X14","explanation":["가와 나는 같은 산불 자료예요.","가: 10건 그림 26개와 1건 그림 8개, 나: 100건 그림 2개, 10건 그림 6개와 1건 그림 8개.","둘 다 268건 — 맞아요(O)."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"가에서 봄의 그림이 나보다 많으므로 가의 봄 산불 발생 건수가 더 많아요.","answer":"X","reason_options":[{"t":"그림 개수만 다를 뿐 둘 다 312건이어서","correct":true},{"t":"그림이 많을수록 건수가 많아서","mis":"M3-2-u6-X14"}],"explanation":["그림 개수가 다른 것은 단위가 달라서예요.","가: 33개, 나: 6개 — 그래도 둘 다 312건이에요.","틀린 말이에요(X)."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"가와 나는 같은 자료를 나타냈으므로 가을의 산불 발생 건수는 두 그림그래프에서 같아요.","answer":"O","reason_options":[{"t":"단위만 다르고 나타낸 건수는 124건으로 같아서","correct":true},{"t":"그림의 개수가 달라서 건수도 달라서","mis":"M3-2-u6-X14"}],"explanation":["가와 나는 같은 산불 자료예요.","가: 10건 그림 12개와 1건 그림 4개, 나: 100건 그림 1개, 10건 그림 2개와 1건 그림 4개.","둘 다 124건 — 맞아요(O)."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}