INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#1','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',2,'sa','auto','나 그림그래프에서 가을 줄에 10건 그림은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"나 그림그래프에서 가을 줄에 10건 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["나는 100건·10건·1건 그림이에요.","173건은 100건 그림 1개, 10건 그림 7개와 1건 그림 3개예요.","10건 그림은 7개예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[368,150,173,238],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"나 그림그래프에서 화요일 줄에 1명 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["나는 100명·10명·1명 그림이에요.","137명은 100명 그림 1개, 10명 그림 3개와 1명 그림 7개예요.","1명 그림은 7개예요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수 — 가: 10·1, 나: 100·10·1","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[358,137,163,179],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수","units2":[100,10,1]}},{"stem":"나 그림그래프에서 햇살 마을 줄에 10상자 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["나는 100상자·10상자·1상자 그림이에요.","378상자는 100상자 그림 3개, 10상자 그림 7개와 1상자 그림 8개예요.","10상자 그림은 7개예요."],"asset":{"type":"picg","title":"마을별 사과 생산량 — 가: 10·1, 나: 100·10·1","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[378,286,396,197],"units":[10,1],"icon":"🍎","unit":"상자","vh":"생산량","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#2','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',2,'sa','auto','봄의 산불 발생 건수를 나타낸 그림은 가가 나보다 몇 개 더 많나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"봄의 산불 발생 건수를 나타낸 그림은 가가 나보다 몇 개 더 많나요? 숫자로 쓰세요.","answer":["27"],"explanation":["가: 10건 그림 37개와 1건 그림 7개 — 44개.","나: 100건 그림 3개, 10건 그림 7개와 1건 그림 7개 — 17개.","44 − 17 = 27개 더 많아요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"겨울의 산불 발생 건수를 나타낸 그림은 가가 나보다 몇 개 더 많나요? 숫자로 쓰세요.","answer":["18"],"explanation":["가: 10건 그림 24개와 1건 그림 1개 — 25개.","나: 100건 그림 2개, 10건 그림 4개와 1건 그림 1개 — 7개.","25 − 7 = 18개 더 많아요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"가을의 산불 발생 건수를 나타낸 그림은 가가 나보다 몇 개 더 많나요? 숫자로 쓰세요.","answer":["9"],"explanation":["가: 10건 그림 12개와 1건 그림 4개 — 16개.","나: 100건 그림 1개, 10건 그림 2개와 1건 그림 4개 — 7개.","16 − 7 = 9개 더 많아요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#3','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',3,'sa','auto','나 그림그래프에서 봄 줄에 그린 그림은 크기에 관계없이 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C8","difficulty":3,"kind":"sa","stem":"나 그림그래프에서 봄 줄에 그린 그림은 크기에 관계없이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["봄은 111건이에요.","100건 그림 1개, 10건 그림 1개와 1건 그림 1개예요.","1 + 1 + 1 = 3개예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[111,266,366,222],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"나 그림그래프에서 월요일 줄에 그린 그림은 크기에 관계없이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["월요일은 150명이에요.","100명 그림 1개와 10명 그림 5개예요.","1 + 5 = 6개예요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수 — 가: 10·1, 나: 100·10·1","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[150,304,209,184],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수","units2":[100,10,1]}},{"stem":"나 그림그래프에서 바람 마을 줄에 그린 그림은 크기에 관계없이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["바람 마을은 192상자예요.","100상자 그림 1개, 10상자 그림 9개와 1상자 그림 2개예요.","1 + 9 + 2 = 12개예요."],"asset":{"type":"picg","title":"마을별 사과 생산량 — 가: 10·1, 나: 100·10·1","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[217,192,216,234],"units":[10,1],"icon":"🍎","unit":"상자","vh":"생산량","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#4','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',3,'mc','auto','산불 예방 교육을 가을에 하자고 했어요. 알맞은 까닭은 무엇인가요?',ARRAY['M3-2-u6-X17','M3-2-u6-X15']::text[],true,'{"seq":4,"concept":"M3-2-u6-C8","difficulty":3,"kind":"mc","stem":"산불 예방 교육을 가을에 하자고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"산불이 많이 나는 겨울과 봄이 오기 전이라서","correct":true},{"t":"가을에 산불이 가장 많이 나서","mis":"M3-2-u6-X17"},{"t":"여름에 산불이 가장 많이 나서","mis":"M3-2-u6-X17"},{"t":"가을의 그림이 가장 커서","mis":"M3-2-u6-X15"}],"explanation":["그림그래프에서 계절마다 건수를 읽어요 — 봄 377, 여름 29, 가을 82, 겨울 268.","정한 때와 그래프에서 읽은 사실이 맞아야 해요.","알맞은 까닭 — 산불이 많이 나는 겨울과 봄이 오기 전이라서."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"산불 예방 교육을 봄에 하자고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"봄에 산불이 가장 많이 나서","correct":true},{"t":"봄에 산불이 가장 적게 나서","mis":"M3-2-u6-X16"},{"t":"여름에 산불이 가장 많이 나서","mis":"M3-2-u6-X17"},{"t":"봄 그림의 색이 진해서","mis":"M3-2-u6-X17"}],"explanation":["그림그래프에서 계절마다 건수를 읽어요 — 봄 312, 여름 46, 가을 95, 겨울 241.","정한 때와 그래프에서 읽은 사실이 맞아야 해요.","알맞은 까닭 — 봄에 산불이 가장 많이 나서."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"산불 예방 교육을 사계절 내내 하자고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"어느 계절에도 산불이 나서","correct":true},{"t":"여름에는 산불이 하나도 없어서","mis":"M3-2-u6-X17"},{"t":"가을에 산불이 가장 많아서","mis":"M3-2-u6-X17"},{"t":"그림그래프에 계절이 네 개라서","mis":"M3-2-u6-X17"}],"explanation":["그림그래프에서 계절마다 건수를 읽어요 — 봄 286, 여름 37, 가을 124, 겨울 205.","정한 때와 그래프에서 읽은 사실이 맞아야 해요.","알맞은 까닭 — 어느 계절에도 산불이 나서."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#5','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C9',3,'mc','auto','한 그림그래프에서 어떤 줄의 그림만 다른 줄보다 훨씬 크게 그렸어요. 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u6-X15']::text[],true,'{"seq":5,"concept":"M3-2-u6-C9","difficulty":3,"kind":"mc","stem":"한 그림그래프에서 어떤 줄의 그림만 다른 줄보다 훨씬 크게 그렸어요. 바르게 말한 것은 무엇인가요?","options":[{"t":"실제보다 많아 보여 잘못 읽을 수 있어요","correct":true},{"t":"그 줄의 수가 가장 많아요","mis":"M3-2-u6-X15"},{"t":"크게 그리면 수가 정확해져요","mis":"M3-2-u6-X15"},{"t":"그림의 크기는 아무 상관이 없어요","mis":"M3-2-u6-X15"}],"explanation":["그림을 크게 그리면 넓이가 커져 실제보다 많아 보여요.","같은 수를 나타내는 그림은 크기가 같아야 해요.","답은 「실제보다 많아 보여 잘못 읽을 수 있어요」예요."],"variant_rule":{"alt":[{"stem":"그림그래프에서 그림의 크기를 정할 때 알맞은 것은 무엇인가요?","options":[{"t":"같은 수를 나타내는 그림은 같은 크기로 그려요","correct":true},{"t":"수가 많은 줄은 그림을 더 크게 그려요","mis":"M3-2-u6-X15"},{"t":"마음에 드는 줄의 그림을 크게 그려요","mis":"M3-2-u6-X15"},{"t":"그림 크기는 아무렇게나 해요","mis":"M3-2-u6-X15"}],"explanation":["그림을 크게 그리면 넓이가 커져 실제보다 많아 보여요.","같은 수를 나타내는 그림은 크기가 같아야 해요.","답은 「같은 수를 나타내는 그림은 같은 크기로 그려요」예요."],"asset":null},{"stem":"「축구를 좋아하는 학생은 그림이 가장 커 보이니 가장 많아요.」라는 말에 대해 알맞은 것은 무엇인가요?","options":[{"t":"그림의 크기가 아니라 그림이 나타내는 수로 견주어야 해요","correct":true},{"t":"맞는 말이에요","mis":"M3-2-u6-X15"},{"t":"그림이 크면 언제나 수가 많아요","mis":"M3-2-u6-X15"},{"t":"그림이 작을수록 수가 많아요","mis":"M3-2-u6-X15"}],"explanation":["그림을 크게 그리면 넓이가 커져 실제보다 많아 보여요.","같은 수를 나타내는 그림은 크기가 같아야 해요.","답은 「그림의 크기가 아니라 그림이 나타내는 수로 견주어야 해요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#6','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C9',3,'sa','auto','그림의 가로와 세로를 함께 3배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u6-C9","difficulty":3,"kind":"sa","stem":"그림의 가로와 세로를 함께 3배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.","answer":["9"],"explanation":["가로로 3개, 세로로 3개만큼 처음 그림이 들어가요.","3 × 3 = 9.","넓이는 9배예요 — 3배로 보이지 않아요."],"variant_rule":{"alt":[{"stem":"그림의 가로와 세로를 함께 2배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["가로로 2개, 세로로 2개만큼 처음 그림이 들어가요.","2 × 2 = 4.","넓이는 4배예요 — 2배로 보이지 않아요."],"asset":null},{"stem":"그림의 가로와 세로를 함께 4배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.","answer":["16"],"explanation":["가로로 4개, 세로로 4개만큼 처음 그림이 들어가요.","4 × 4 = 16.","넓이는 16배예요 — 4배로 보이지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#7','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',3,'sa','auto','사람 수의 합계는 674명이에요. 그림그래프에서 목요일 줄이 지워졌어요. 목요일에 도서관을 찾은 사람은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u6-C8","difficulty":3,"kind":"sa","stem":"사람 수의 합계는 674명이에요. 그림그래프에서 목요일 줄이 지워졌어요. 목요일에 도서관을 찾은 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["276"],"explanation":["보이는 줄을 읽어요 — 122, 119, 157.","모르는 수 = 합계 − 아는 수들.","674 − 122 − 119 − 157 = 276명이에요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[122,119,157,null],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"사람 수","blank":[3]},"variant_rule":{"alt":[{"stem":"생산량의 합계는 1025상자예요. 그림그래프에서 바람 마을 줄이 지워졌어요. 바람 마을의 사과 생산량은 몇 상자인가요? 숫자로 쓰세요.","answer":["240"],"explanation":["보이는 줄을 읽어요 — 295, 211, 279.","모르는 수 = 합계 − 아는 수들.","1025 − 295 − 211 − 279 = 240상자예요."],"asset":{"type":"picg","title":"마을별 사과 생산량","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[295,null,211,279],"units":[100,10,1],"icon":"🍎","unit":"상자","vh":"생산량","blank":[1]}},{"stem":"학생 수의 합계는 516명이에요. 그림그래프에서 떡국 줄이 지워졌어요. 떡국을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["51"],"explanation":["보이는 줄을 읽어요 — 56, 151, 258.","모르는 수 = 합계 − 아는 수들.","516 − 56 − 151 − 258 = 51명이에요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[null,56,151,258],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[0]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#8','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',4,'sa','auto','이 건수를 가처럼 10건·1건 그림으로 나타내면 그림을 모두 몇 개 그려야 하나요? (나처럼 100건·10건·1건 그림이면 54개예요.) 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u6-C8","difficulty":4,"kind":"sa","stem":"이 건수를 가처럼 10건·1건 그림으로 나타내면 그림을 모두 몇 개 그려야 하나요? (나처럼 100건·10건·1건 그림이면 54개예요.) 숫자로 쓰세요.","answer":["99"],"explanation":["계절마다 10건 그림은 십 단위 수, 1건 그림은 일의 자리 수예요.","377 → 44개, 29 → 11개, 82 → 10개, 268 → 34개.","99개 — 나보다 45개 더 많아요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"unit":"건","vh":"발생 건수","title":"계절별 산불 발생 건수","total":false},"variant_rule":{"alt":[{"stem":"이 건수를 가처럼 10건·1건 그림으로 나타내면 그림을 모두 몇 개 그려야 하나요? (나처럼 100건·10건·1건 그림이면 37개예요.) 숫자로 쓰세요.","answer":["82"],"explanation":["계절마다 10건 그림은 십 단위 수, 1건 그림은 일의 자리 수예요.","312 → 33개, 46 → 10개, 95 → 14개, 241 → 25개.","82개 — 나보다 45개 더 많아요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"unit":"건","vh":"발생 건수","title":"계절별 산불 발생 건수","total":false}},{"stem":"이 건수를 가처럼 10건·1건 그림으로 나타내면 그림을 모두 몇 개 그려야 하나요? (나처럼 100건·10건·1건 그림이면 40개예요.) 숫자로 쓰세요.","answer":["85"],"explanation":["계절마다 10건 그림은 십 단위 수, 1건 그림은 일의 자리 수예요.","286 → 34개, 37 → 10개, 124 → 16개, 205 → 25개.","85개 — 나보다 45개 더 많아요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"unit":"건","vh":"발생 건수","title":"계절별 산불 발생 건수","total":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#9','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',4,'mc','auto','나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?',ARRAY['M3-2-u6-X01','M3-2-u6-X03']::text[],true,'{"seq":9,"concept":"M3-2-u6-C8","difficulty":4,"kind":"mc","stem":"나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?","options":[{"t":"바람 마을","correct":true},{"t":"햇살 마을","mis":"M3-2-u6-X01"},{"t":"구름 마을","mis":"M3-2-u6-X03"},{"t":"별빛 마을","mis":"M3-2-u6-X01"}],"explanation":["줄마다 100·10·1 그림의 개수를 더해요.","햇살 마을 44 → 8개, 바람 마을 285 → 15개, 구름 마을 307 → 10개, 별빛 마을 246 → 12개.","바람 마을 — 수가 가장 큰 구름 마을과 달라요."],"asset":{"type":"picg","title":"마을별 사과 생산량 — 가: 10·1, 나: 100·10·1","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[44,285,307,246],"units":[10,1],"icon":"🍎","unit":"상자","vh":"생산량","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?","options":[{"t":"잡채","correct":true},{"t":"떡국","mis":"M3-2-u6-X01"},{"t":"불고기","mis":"M3-2-u6-X01"},{"t":"비빔밥","mis":"M3-2-u6-X03"}],"explanation":["줄마다 100·10·1 그림의 개수를 더해요.","떡국 303 → 6개, 불고기 78 → 15개, 비빔밥 328 → 13개, 잡채 269 → 17개.","잡채 — 수가 가장 큰 비빔밥과 달라요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수 — 가: 10·1, 나: 100·10·1","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[303,78,328,269],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","units2":[100,10,1]}},{"stem":"이번에는 다른 그림이에요. 나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M3-2-u6-X03"},{"t":"여름","mis":"M3-2-u6-X01"},{"t":"가을","mis":"M3-2-u6-X01"}],"explanation":["줄마다 100·10·1 그림의 개수를 더해요.","봄 336 → 12개, 여름 307 → 10개, 가을 263 → 11개, 겨울 58 → 13개.","겨울 — 수가 가장 큰 봄과 달라요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[336,307,263,58],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_L06_challenge#10','math',3,2,'u6','L06','g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',4,'essay','teacher','계절별 산불 발생 건수(봄 377건, 여름 29건, 가을 82건, 겨울 268건)를 가(10건·1건)와 나(100건·10건·1건) 두 그림그래프로 나타냈어요. 겨울을 두 그래프에서 각각 어떻게 나타내는지 쓰고, 단위의 종류가 늘어날 때 좋은 점과 어려운 점을 하나씩 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C8","difficulty":4,"kind":"essay","stem":"계절별 산불 발생 건수(봄 377건, 여름 29건, 가을 82건, 겨울 268건)를 가(10건·1건)와 나(100건·10건·1건) 두 그림그래프로 나타냈어요. 겨울을 두 그래프에서 각각 어떻게 나타내는지 쓰고, 단위의 종류가 늘어날 때 좋은 점과 어려운 점을 하나씩 써 보세요.","answer_guide":{"answer":"예: 가에서 겨울은 10건 그림 26개와 1건 그림 8개, 나에서는 100건 그림 2개와 10건 그림 6개와 1건 그림 8개이다. 단위의 종류가 늘면 큰 수를 적은 그림으로 나타낼 수 있어 편리하지만, 그림의 크기를 뚜렷이 구분해 그리기 어렵다.","scoring_points":["가에서 겨울을 10건 그림 26개·1건 그림 8개로 썼는가","나에서 겨울을 100건 그림 2개·10건 그림 6개·1건 그림 8개로 썼는가","좋은 점(그림이 적다)과 어려운 점(크기 구분)을 썼는가"]},"explanation":["268 = 10 × 26 + 8.","268 = 100 × 2 + 10 × 6 + 8.","단위가 늘면 그림은 줄지만 크기 구분이 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#1','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C1',1,'sa','auto','좋아하는 채소별 학생 수 표예요. 당근을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C1","difficulty":1,"kind":"sa","stem":"좋아하는 채소별 학생 수 표예요. 당근을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["표의 「당근」 칸 아래 수를 읽어요.","표는 수를 정확히 알 수 있어요.","당근을 좋아하는 학생은 15명이에요."],"asset":{"type":"picg","only":"table","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[15,14,4,12],"unit":"명","vh":"학생 수","title":"좋아하는 채소별 학생 수"},"variant_rule":{"alt":[{"stem":"좋아하는 계절별 학생 수 표예요. 가을을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["표의 「가을」 칸 아래 수를 읽어요.","표는 수를 정확히 알 수 있어요.","가을을 좋아하는 학생은 3명이에요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[13,6,3,4],"unit":"명","vh":"학생 수","title":"좋아하는 계절별 학생 수"}},{"stem":"좋아하는 과일별 학생 수 표예요. 사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["표의 「사과」 칸 아래 수를 읽어요.","표는 수를 정확히 알 수 있어요.","사과를 좋아하는 학생은 9명이에요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["귤","사과","포도","배"],"counts":[3,9,14,5],"unit":"명","vh":"학생 수","title":"좋아하는 과일별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#2','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 로봇부에 가입한 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 로봇부에 가입한 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["9"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","로봇부 줄은 1명 그림 9개예요.","로봇부에 가입한 학생은 9명이에요."],"asset":{"type":"picg","title":"가입한 동아리별 학생 수","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[32,9,43,6],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 투호를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["12"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","투호 줄은 10명 그림 1개와 1명 그림 2개예요.","투호를 좋아하는 학생은 12명이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 학생 수","head":"민속놀이","cols":["윷놀이","투호","연날리기","제기차기"],"counts":[29,12,20,27],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"그림그래프를 보고 햇살 농장에서 기르는 오리는 몇 마리인지 구하세요. 숫자로 쓰세요.","answer":["16"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 10마리, 작은 그림 1마리.","햇살 농장 줄은 10마리 그림 1개와 1마리 그림 6개예요.","햇살 농장에서 기르는 오리는 16마리예요."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["초록 농장","햇살 농장","바람 농장","들꽃 농장"],"counts":[4,16,9,32],"units":[10,1],"icon":"🦆","unit":"마리","vh":"오리의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#3','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C4',1,'sa','auto','들꽃 농장에서 기르는 오리 38마리를 그림그래프로 나타내요. 큰 그림이 10마리, 작은 그림이 1마리를 나타낼 때 10마리 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C4","difficulty":1,"kind":"sa","stem":"들꽃 농장에서 기르는 오리 38마리를 그림그래프로 나타내요. 큰 그림이 10마리, 작은 그림이 1마리를 나타낼 때 10마리 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 그림부터 그려요.","38마리는 10마리 그림 3개와 1마리 그림 8개예요.","10마리 그림은 3개예요."],"variant_rule":{"alt":[{"stem":"판매한 운동화 26켤레를 그림그래프로 나타내요. 큰 그림이 10켤레, 작은 그림이 1켤레를 나타낼 때 10켤레 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","26켤레는 10켤레 그림 2개와 1켤레 그림 6개예요.","10켤레 그림은 2개예요."],"asset":null},{"stem":"판매한 초코도넛 37개를 그림그래프로 나타내요. 큰 그림이 10개, 작은 그림이 1개를 나타낼 때 10개 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 그림부터 그려요.","37개는 10개 그림 3개와 1개 그림 7개예요.","10개 그림은 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#4','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C4',1,'mc','auto','그림그래프로 나타내는 네 걸음 가운데 ②는 무엇인가요?  ① 알맞은 제목 → ② ? → ③ 항목 → ④ 그림',ARRAY['M3-2-u6-X07']::text[],true,'{"seq":4,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"그림그래프로 나타내는 네 걸음 가운데 ②는 무엇인가요?  ① 알맞은 제목 → ② ? → ③ 항목 → ④ 그림","options":[{"t":"그림과 단위를 정해요","correct":true},{"t":"알맞은 제목을 써요","mis":"M3-2-u6-X07"},{"t":"조사한 항목을 빠짐없이 써요","mis":"M3-2-u6-X07"},{"t":"합계를 구해요","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지를 갖추어 나타내요.","② 걸음은 「그림과 단위를 정해요」예요.","순서는 꼭 지키지 않아도 되지만 네 가지는 빠짐없이 있어야 해요."],"variant_rule":{"alt":[{"stem":"그림그래프로 나타내는 네 걸음 가운데 ④는 무엇인가요?  ① 알맞은 제목 → ② 그림과 단위 → ③ 항목 → ④ ?","options":[{"t":"수에 맞게 그림으로 나타내요","correct":true},{"t":"알맞은 제목을 써요","mis":"M3-2-u6-X07"},{"t":"그림과 단위를 정해요","mis":"M3-2-u6-X07"},{"t":"합계를 구해요","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지를 갖추어 나타내요.","④ 걸음은 「수에 맞게 그림으로 나타내요」예요.","순서는 꼭 지키지 않아도 되지만 네 가지는 빠짐없이 있어야 해요."],"asset":null},{"stem":"그림그래프로 나타내는 네 걸음 가운데 ③는 무엇인가요?  ① 알맞은 제목 → ② 그림과 단위 → ③ ? → ④ 그림","options":[{"t":"조사한 항목을 빠짐없이 써요","correct":true},{"t":"알맞은 제목을 써요","mis":"M3-2-u6-X07"},{"t":"그림과 단위를 정해요","mis":"M3-2-u6-X07"},{"t":"합계를 구해요","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지를 갖추어 나타내요.","③ 걸음은 「조사한 항목을 빠짐없이 써요」예요.","순서는 꼭 지키지 않아도 되지만 네 가지는 빠짐없이 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#5','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C6',1,'mc','auto','「친구에게 가서 하나씩 물어보고 적어요.」라고 했어요. 어떤 조사 방법인가요?',ARRAY['M3-2-u6-X11']::text[],true,'{"seq":5,"concept":"M3-2-u6-C6","difficulty":1,"kind":"mc","stem":"「친구에게 가서 하나씩 물어보고 적어요.」라고 했어요. 어떤 조사 방법인가요?","options":[{"t":"돌아다니며 묻기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"}],"explanation":["조사 방법에는 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기가 있어요.","「친구에게 가서 하나씩 물어보고 적어요.」 하는 일은 「돌아다니며 묻기」의 모습이에요.","답은 「돌아다니며 묻기」예요."],"variant_rule":{"alt":[{"stem":"「쪽지에 이름 없이 하나를 적어 통에 넣어요.」라고 했어요. 어떤 조사 방법인가요?","options":[{"t":"투표하기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["조사 방법에는 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기가 있어요.","「쪽지에 이름 없이 하나를 적어 통에 넣어요.」 하는 일은 「투표하기」의 모습이에요.","답은 「투표하기」예요."],"asset":null},{"stem":"「종이 띠 판에 색 동그라미 스티커를 붙여요.」라고 했어요. 어떤 조사 방법인가요?","options":[{"t":"붙임딱지 붙이기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["조사 방법에는 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기가 있어요.","「종이 띠 판에 색 동그라미 스티커를 붙여요.」 하는 일은 「붙임딱지 붙이기」의 모습이에요.","답은 「붙임딱지 붙이기」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#6','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C7',1,'sa','auto','지유가 훌라후프를 한 횟수 23회를 그림그래프로 나타내요. 큰 그림이 5회, 작은 그림이 1회를 나타낼 때 5회 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u6-C7","difficulty":1,"kind":"sa","stem":"지유가 훌라후프를 한 횟수 23회를 그림그래프로 나타내요. 큰 그림이 5회, 작은 그림이 1회를 나타낼 때 5회 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 그림부터 그려요.","23회는 5회 그림 4개와 1회 그림 3개예요.","5회 그림은 4개예요."],"variant_rule":{"alt":[{"stem":"장미 11송이를 그림그래프로 나타내요. 큰 그림이 5송이, 작은 그림이 1송이를 나타낼 때 5송이 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","11송이는 5송이 그림 2개와 1송이 그림 1개예요.","5송이 그림은 2개예요."],"asset":null},{"stem":"달님 모둠이 모은 붙임딱지 23장을 그림그래프로 나타내요. 큰 그림이 5장, 작은 그림이 1장을 나타낼 때 5장 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 그림부터 그려요.","23장은 5장 그림 4개와 1장 그림 3개예요.","5장 그림은 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#7','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C8',1,'sa','auto','나 그림그래프에서 비빔밥을 좋아하는 학생 367명을 나타낼 때 100명 그림은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u6-C8","difficulty":1,"kind":"sa","stem":"나 그림그래프에서 비빔밥을 좋아하는 학생 367명을 나타낼 때 100명 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나는 100명·10명·1명 세 가지 그림이에요.","367명은 100명 그림 3개, 10명 그림 6개와 1명 그림 7개예요.","100명 그림은 3개예요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수 — 가: 10·1, 나: 100·10·1","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[193,359,367,333],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"나 그림그래프에서 가을의 산불 발생 건수 120건을 나타낼 때 100건 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나는 100건·10건·1건 세 가지 그림이에요.","120건은 100건 그림 1개와 10건 그림 2개예요.","100건 그림은 1개예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[288,136,120,165],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"나 그림그래프에서 월요일에 도서관을 찾은 사람 188명을 나타낼 때 100명 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나는 100명·10명·1명 세 가지 그림이에요.","188명은 100명 그림 1개, 10명 그림 8개와 1명 그림 8개예요.","100명 그림은 1개예요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수 — 가: 10·1, 나: 100·10·1","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[188,244,371,143],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#8','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C8',1,'mc','auto','가와 나 그림그래프에서 같은 것은 무엇인가요?',ARRAY['M3-2-u6-X14']::text[],true,'{"seq":8,"concept":"M3-2-u6-C8","difficulty":1,"kind":"mc","stem":"가와 나 그림그래프에서 같은 것은 무엇인가요?","options":[{"t":"나타낸 건수(자료)가 같아요","correct":true},{"t":"그림의 개수가 같아요","mis":"M3-2-u6-X14"},{"t":"단위의 종류가 같아요","mis":"M3-2-u6-X14"},{"t":"그림의 크기 종류가 같아요","mis":"M3-2-u6-X14"}],"explanation":["두 그림그래프는 같은 산불 자료를 나타냈어요.","쓴 그림(🔥)은 같고, 가는 10·1, 나는 100·10·1로 단위의 종류가 달라요.","답은 「나타낸 건수(자료)가 같아요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"가와 나 그림그래프에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"같은 자료를 그림의 단위만 다르게 나타냈어요","correct":true},{"t":"서로 다른 자료를 나타냈어요","mis":"M3-2-u6-X14"},{"t":"가가 나보다 건수가 많아요","mis":"M3-2-u6-X14"},{"t":"나가 가보다 건수가 많아요","mis":"M3-2-u6-X14"}],"explanation":["두 그림그래프는 같은 산불 자료를 나타냈어요.","쓴 그림(🔥)은 같고, 가는 10·1, 나는 100·10·1로 단위의 종류가 달라요.","답은 「같은 자료를 그림의 단위만 다르게 나타냈어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"가와 나 그림그래프의 같은 점은 무엇인가요?","options":[{"t":"그림이 같아요","correct":true},{"t":"단위의 종류가 같아요","mis":"M3-2-u6-X14"},{"t":"그림의 수가 같아요","mis":"M3-2-u6-X14"},{"t":"같은 점이 없어요","mis":"M3-2-u6-X14"}],"explanation":["두 그림그래프는 같은 산불 자료를 나타냈어요.","쓴 그림(🔥)은 같고, 가는 10·1, 나는 100·10·1로 단위의 종류가 달라요.","답은 「그림이 같아요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#9','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C1',2,'sa','auto','좋아하는 여가 활동별 학생 수 표예요. 합계가 35명일 때 배드민턴을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u6-C1","difficulty":2,"kind":"sa","stem":"좋아하는 여가 활동별 학생 수 표예요. 합계가 35명일 때 배드민턴을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들이에요.","35 − 8 − 11 = 16명이에요."],"asset":{"type":"picg","only":"table","head":"여가 활동","cols":["배드민턴","산책","자전거 타기"],"counts":[null,8,11],"unit":"명","vh":"학생 수","title":"좋아하는 여가 활동별 학생 수","total":35},"variant_rule":{"alt":[{"stem":"여행 가고 싶어 하는 나라별 학생 수 표예요. 합계가 31명일 때 영국에 가고 싶어 하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들이에요.","31 − 5 − 12 = 14명이에요."],"asset":{"type":"picg","only":"table","head":"나라","cols":["미국","일본","영국"],"counts":[5,12,null],"unit":"명","vh":"학생 수","title":"여행 가고 싶어 하는 나라별 학생 수","total":31}},{"stem":"좋아하는 과일별 학생 수 표예요. 합계가 30명일 때 사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들이에요.","30 − 6 − 8 = 16명이에요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["귤","사과","포도"],"counts":[6,null,8],"unit":"명","vh":"학생 수","title":"좋아하는 과일별 학생 수","total":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#10','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',2,'mc','auto','그림그래프에서 책을 가장 많이 빌린 반은 어느 반인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X16','M3-2-u6-X04']::text[],true,'{"seq":10,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"그림그래프에서 책을 가장 많이 빌린 반은 어느 반인가요?","options":[{"t":"4반","correct":true},{"t":"1반","mis":"M3-2-u6-X03"},{"t":"2반","mis":"M3-2-u6-X16"},{"t":"3반","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 1반 36, 2반 3, 3반 28, 4반 40.","가장 많은 것은 「4반」이에요."],"asset":{"type":"picg","title":"반별 빌린 책의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[36,3,28,40],"units":[10,1],"icon":"📕","unit":"권","vh":"책의 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 나무를 가장 많이 심은 마을은 어느 마을인가요?","options":[{"t":"별빛 마을","correct":true},{"t":"햇살 마을","mis":"M3-2-u6-X03"},{"t":"바람 마을","mis":"M3-2-u6-X04"},{"t":"구름 마을","mis":"M3-2-u6-X16"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 햇살 마을 22, 바람 마을 36, 구름 마을 17, 별빛 마을 40.","가장 많은 것은 「별빛 마을」이에요."],"asset":{"type":"picg","title":"마을별 심은 나무의 수","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[22,36,17,40],"units":[10,1],"icon":"🌳","unit":"그루","vh":"나무의 수"}},{"stem":"그림그래프에서 빈 병을 가장 많이 모은 반은 어느 반인가요?","options":[{"t":"2반","correct":true},{"t":"1반","mis":"M3-2-u6-X04"},{"t":"3반","mis":"M3-2-u6-X16"},{"t":"4반","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 1반 18, 2반 32, 3반 7, 4반 30.","가장 많은 것은 「2반」이에요."],"asset":{"type":"picg","title":"반별 모은 빈 병의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[18,32,7,30],"units":[10,1],"icon":"🍾","unit":"개","vh":"빈 병의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind