INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#11','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',2,'mc','auto','㉠과 ㉡은 그림이 3개씩이에요. 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X16']::text[],true,'{"seq":11,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"㉠과 ㉡은 그림이 3개씩이에요. 바르게 말한 것은 무엇인가요?","options":[{"t":"㉡이 ㉠보다 많아요","correct":true},{"t":"㉠과 ㉡은 같아요","mis":"M3-2-u6-X03"},{"t":"㉠이 ㉡보다 많아요","mis":"M3-2-u6-X16"},{"t":"알 수 없어요","mis":"M3-2-u6-X03"}],"explanation":["그림의 개수가 같아도 크기가 다르면 나타내는 수가 달라요.","㉠은 12, ㉡은 21이에요.","㉡이 ㉠보다 많아요."],"asset":{"type":"picg","title":"그림의 수가 같은 두 줄","head":"농장","cols":["㉠","㉡"],"counts":[12,21],"units":[10,1],"icon":"🦆","unit":"마리","vh":"오리의 수"},"variant_rule":{"alt":[{"stem":"㉠과 ㉡은 그림이 4개씩이에요. 바르게 말한 것은 무엇인가요?","options":[{"t":"㉠이 ㉡보다 많아요","correct":true},{"t":"㉠과 ㉡은 같아요","mis":"M3-2-u6-X03"},{"t":"㉡이 ㉠보다 많아요","mis":"M3-2-u6-X16"},{"t":"알 수 없어요","mis":"M3-2-u6-X03"}],"explanation":["그림의 개수가 같아도 크기가 다르면 나타내는 수가 달라요.","㉠은 31, ㉡은 13이에요.","㉠이 ㉡보다 많아요."],"asset":{"type":"picg","title":"그림의 수가 같은 두 줄","head":"종류","cols":["㉠","㉡"],"counts":[31,13],"units":[10,1],"icon":"👟","unit":"켤레","vh":"신발의 수"}},{"stem":"㉠과 ㉡은 그림이 5개씩이에요. 바르게 말한 것은 무엇인가요?","options":[{"t":"㉠이 ㉡보다 많아요","correct":true},{"t":"㉠과 ㉡은 같아요","mis":"M3-2-u6-X03"},{"t":"㉡이 ㉠보다 많아요","mis":"M3-2-u6-X16"},{"t":"알 수 없어요","mis":"M3-2-u6-X03"}],"explanation":["그림의 개수가 같아도 크기가 다르면 나타내는 수가 달라요.","㉠은 41, ㉡은 23이에요.","㉠이 ㉡보다 많아요."],"asset":{"type":"picg","title":"그림의 수가 같은 두 줄","head":"종류","cols":["㉠","㉡"],"counts":[41,23],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_cod