INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#12','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C4',2,'mc','auto','판매한 장화 37켤레를 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":12,"concept":"M3-2-u6-C4","difficulty":2,"kind":"mc","stem":"판매한 장화 37켤레를 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10켤레 그림 3개와 1켤레 그림 7개","correct":true},{"t":"10켤레 그림 7개와 1켤레 그림 3개","mis":"M3-2-u6-X05"},{"t":"10켤레 그림 3개","mis":"M3-2-u6-X06"},{"t":"10켤레 그림 4개와 1켤레 그림 7개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 10켤레예요.","37켤레는 큰 그림 3개, 남은 7켤레는 작은 그림 7개예요.","답은 「10켤레 그림 3개와 1켤레 그림 7개」예요."],"variant_rule":{"alt":[{"stem":"판매한 크림도넛 35개를 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10개 그림 3개와 1개 그림 5개","correct":true},{"t":"10개 그림 5개와 1개 그림 3개","mis":"M3-2-u6-X05"},{"t":"10개 그림 3개","mis":"M3-2-u6-X06"},{"t":"10개 그림 4개와 1개 그림 5개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 10개예요.","35개는 큰 그림 3개, 남은 5개는 작은 그림 5개예요.","답은 「10개 그림 3개와 1개 그림 5개」예요."],"asset":null},{"stem":"2반에서 빌린 책 24권을 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10권 그림 2개와 1권 그림 4개","correct":true},{"t":"10권 그림 4개와 1권 그림 2개","mis":"M3-2-u6-X05"},{"t":"10권 그림 2개","mis":"M3-2-u6-X06"},{"t":"10권 그림 3개와 1권 그림 4개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 10권이에요.","24권은 큰 그림 2개, 남은 4권은 작은 그림 4개예요.","답은 「10권 그림 2개와 1권 그림 4개」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#13','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C5',2,'mc','auto','가장 적은 학생이 좋아하는 전통 음식을 더 맛있게 만들어 보려고 해요. 무엇을 고르면 될까요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16']::text[],true,'{"seq":13,"concept":"M3-2-u6-C5","difficulty":2,"kind":"mc","stem":"가장 적은 학생이 좋아하는 전통 음식을 더 맛있게 만들어 보려고 해요. 무엇을 고르면 될까요?","options":[{"t":"비빔밥","correct":true},{"t":"떡국","mis":"M3-2-u6-X04"},{"t":"불고기","mis":"M3-2-u6-X16"},{"t":"잡채","mis":"M3-2-u6-X04"}],"explanation":["그림그래프에서 줄마다 수를 읽어요 — 떡국 335, 불고기 379, 비빔밥 98, 잡채 187.","가장 적은 것을 찾아요.","「비빔밥」이에요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[335,379,98,187],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"가장 많은 학생이 좋아하는 전통 음식을 급식에 넣으려고 해요. 무엇을 넣으면 될까요?","options":[{"t":"불고기","correct":true},{"t":"떡국","mis":"M3-2-u6-X16"},{"t":"비빔밥","mis":"M3-2-u6-X04"},{"t":"잡채","mis":"M3-2-u6-X04"}],"explanation":["그림그래프에서 줄마다 수를 읽어요 — 떡국 93, 불고기 252, 비빔밥 182, 잡채 139.","가장 많은 것을 찾아요.","「불고기」예요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[93,252,182,139],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"가장 적은 학생이 좋아하는 채소를 더 맛있게 만들어 보려고 해요. 무엇을 고르면 될까요?","options":[{"t":"시금치","correct":true},{"t":"당근","mis":"M3-2-u6-X04"},{"t":"오이","mis":"M3-2-u6-X16"},{"t":"콩나물","mis":"M3-2-u6-X04"}],"explanation":["그림그래프에서 줄마다 수를 읽어요 — 당근 39, 시금치 15, 오이 48, 콩나물 40.","가장 적은 것을 찾아요.","「시금치」예요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[39,15,48,40],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#14','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C6',2,'mc','auto','우리 학년이 직접 자료를 모을 수 있는 주제는 무엇인가요?',ARRAY['M3-2-u6-X10']::text[],true,'{"seq":14,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"우리 학년이 직접 자료를 모을 수 있는 주제는 무엇인가요?","options":[{"t":"우리 학년이 좋아하는 급식 반찬","correct":true},{"t":"세계 모든 사람이 좋아하는 동물","mis":"M3-2-u6-X10"},{"t":"우리나라 어른들이 가장 많이 타는 차","mis":"M3-2-u6-X10"},{"t":"지구에 사는 새의 수","mis":"M3-2-u6-X10"}],"explanation":["주제는 우리가 직접 모을 수 있어야 해요.","그리고 무엇을 조사하는지 분명해야 해요.","답은 「우리 학년이 좋아하는 급식 반찬」이에요."],"variant_rule":{"alt":[{"stem":"무엇을 조사하는지 분명한 주제는 무엇인가요?","options":[{"t":"우리 반이 한 달 동안 읽은 책의 수","correct":true},{"t":"우리 반 친구들의 이것저것","mis":"M3-2-u6-X10"},{"t":"재미있는 것","mis":"M3-2-u6-X10"},{"t":"여러 가지 좋은 것","mis":"M3-2-u6-X10"}],"explanation":["주제는 우리가 직접 모을 수 있어야 해요.","그리고 무엇을 조사하는지 분명해야 해요.","답은 「우리 반이 한 달 동안 읽은 책의 수」예요."],"asset":null},{"stem":"우리 반이 직접 조사하기 어려운 주제는 무엇인가요?","options":[{"t":"우리나라 모든 어린이가 좋아하는 과일","correct":true},{"t":"우리 반이 좋아하는 운동","mis":"M3-2-u6-X10"},{"t":"우리 모둠이 좋아하는 색깔","mis":"M3-2-u6-X10"},{"t":"우리 반이 배우고 싶은 악기","mis":"M3-2-u6-X10"}],"explanation":["주제는 우리가 직접 모을 수 있어야 해요.","그리고 무엇을 조사하는지 분명해야 해요.","답은 「우리나라 모든 어린이가 좋아하는 과일」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#15','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C7',2,'mc','auto','그림그래프에 빠진 항목이 없는지 알아보려면 무엇과 견주면 되나요?',ARRAY['M3-2-u6-X15','M3-2-u6-X13','M3-2-u6-X07']::text[],true,'{"seq":15,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"그림그래프에 빠진 항목이 없는지 알아보려면 무엇과 견주면 되나요?","options":[{"t":"표의 항목","correct":true},{"t":"그림의 크기","mis":"M3-2-u6-X15"},{"t":"그림의 색깔","mis":"M3-2-u6-X13"},{"t":"제목의 글자 수","mis":"M3-2-u6-X07"}],"explanation":["다 그린 뒤에는 빠짐과 틀림을 확인해요.","항목은 표와, 그림의 합은 표의 합계와 견줘요.","답은 「표의 항목」이에요."],"variant_rule":{"alt":[{"stem":"그림을 덜 그리거나 더 그린 곳이 있는지 알아보는 방법은 무엇인가요?","options":[{"t":"그림이 나타내는 수를 모두 더해 표의 합계와 견주어요","correct":true},{"t":"그림의 개수만 세어 봐요","mis":"M3-2-u6-X01"},{"t":"가장 큰 그림만 세어 봐요","mis":"M3-2-u6-X04"},{"t":"제목을 다시 읽어요","mis":"M3-2-u6-X07"}],"explanation":["다 그린 뒤에는 빠짐과 틀림을 확인해요.","항목은 표와, 그림의 합은 표의 합계와 견줘요.","답은 「그림이 나타내는 수를 모두 더해 표의 합계와 견주어요」예요."],"asset":null},{"stem":"그림그래프를 다 그린 뒤 무엇을 확인하면 좋을까요?","options":[{"t":"그림이 나타내는 수의 합이 표의 합계와 같은지","correct":true},{"t":"그림이 모두 같은 색인지","mis":"M3-2-u6-X13"},{"t":"제목이 가장 긴지","mis":"M3-2-u6-X07"},{"t":"그림이 모두 작은지","mis":"M3-2-u6-X06"}],"explanation":["다 그린 뒤에는 빠짐과 틀림을 확인해요.","항목은 표와, 그림의 합은 표의 합계와 견줘요.","답은 「그림이 나타내는 수의 합이 표의 합계와 같은지」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#16','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C8',2,'mc','auto','나 그림그래프처럼 100건 그림을 하나 더 두면 좋은 점은 무엇인가요?',ARRAY['M3-2-u6-X14','M3-2-u6-X07']::text[],true,'{"seq":16,"concept":"M3-2-u6-C8","difficulty":2,"kind":"mc","stem":"나 그림그래프처럼 100건 그림을 하나 더 두면 좋은 점은 무엇인가요?","options":[{"t":"그림을 적게 그려도 돼요","correct":true},{"t":"그림을 크게 그리기 쉬워요","mis":"M3-2-u6-X14"},{"t":"건수가 늘어나요","mis":"M3-2-u6-X14"},{"t":"제목을 쓰지 않아도 돼요","mis":"M3-2-u6-X07"}],"explanation":["봄 377건 — 가는 10건 그림 37개와 1건 그림 7개, 나는 100건 그림 3개와 10건 그림 7개와 1건 그림 7개예요.","그래서 그림 개수가 줄어요.","답은 「그림을 적게 그려도 돼요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"봄 377건을 나타낼 때 나가 가보다 좋은 점은 무엇인가요?","options":[{"t":"그림 개수가 훨씬 적어요","correct":true},{"t":"그림 개수가 훨씬 많아요","mis":"M3-2-u6-X14"},{"t":"건수가 더 정확해져요","mis":"M3-2-u6-X14"},{"t":"그림을 구분하기 쉬워요","mis":"M3-2-u6-X14"}],"explanation":["단위의 종류가 늘면 큰 수를 큰 그림 몇 개로 줄여 나타낼 수 있어요.","그래서 그림 개수가 줄어요.","답은 「그림 개수가 훨씬 적어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"단위의 종류가 늘어나면 편리한 점은 무엇인가요?","options":[{"t":"큰 수를 적은 그림으로 나타낼 수 있어요","correct":true},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"그림의 크기를 구분하기 쉬워요","mis":"M3-2-u6-X14"},{"t":"합계가 커져요","mis":"M3-2-u6-X14"}],"explanation":["단위의 종류가 늘면 큰 수를 큰 그림 몇 개로 줄여 나타낼 수 있어요.","그래서 그림 개수가 줄어요.","답은 「큰 수를 적은 그림으로 나타낼 수 있어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#17','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',3,'mc','auto','배우고 싶어 하는 악기별 학생 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 플루트는 7명이에요.  ㉡ 가장 적은 것은 오카리나예요.  ㉢ 가야금은 오카리나보다 15명 더 많아요.',ARRAY['M3-2-u6-X16','M3-2-u6-X01']::text[],true,'{"seq":17,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"배우고 싶어 하는 악기별 학생 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 플루트는 7명이에요.  ㉡ 가장 적은 것은 오카리나예요.  ㉢ 가야금은 오카리나보다 15명 더 많아요.","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M3-2-u6-X16"},{"t":"㉢","mis":"M3-2-u6-X16"},{"t":"모두 옳아요","mis":"M3-2-u6-X01"}],"explanation":["줄마다 수를 읽어요 — 가야금 39, 오카리나 24, 우쿨렐레 42, 플루트 43.","말 하나하나를 그래프와 맞춰 봐요.","옳지 않은 것은 ㉠이에요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[39,24,42,43],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"좋아하는 여가 활동별 학생 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 배드민턴은 47명이에요.  ㉡ 가장 적은 것은 배드민턴이에요.  ㉢ 배드민턴은 산책보다 30명 더 많아요.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u6-X16"},{"t":"㉢","mis":"M3-2-u6-X16"},{"t":"모두 옳아요","mis":"M3-2-u6-X16"}],"explanation":["줄마다 수를 읽어요 — 배드민턴 47, 산책 17, 자전거 타기 3, 줄넘기 40.","말 하나하나를 그래프와 맞춰 봐요.","옳지 않은 것은 ㉡이에요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[47,17,3,40],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"좋아하는 채소별 학생 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 콩나물은 5명이에요.  ㉡ 가장 적은 것은 당근이에요.  ㉢ 시금치는 당근보다 33명 더 많아요.","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M3-2-u6-X16"},{"t":"㉢","mis":"M3-2-u6-X16"},{"t":"모두 옳아요","mis":"M3-2-u6-X01"}],"explanation":["줄마다 수를 읽어요 — 당근 13, 시금치 46, 오이 15, 콩나물 23.","말 하나하나를 그래프와 맞춰 봐요.","옳지 않은 것은 ㉠이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[13,46,15,23],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#18','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C4',3,'mc','auto','표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?',ARRAY['M3-2-u6-X13']::text[],true,'{"seq":18,"concept":"M3-2-u6-C4","difficulty":3,"kind":"mc","stem":"표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"자전거 타기","correct":true},{"t":"배드민턴","mis":"M3-2-u6-X13"},{"t":"산책","mis":"M3-2-u6-X13"},{"t":"줄넘기","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","자전거 타기 줄은 1명 그림 5개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「자전거 타기」예요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[34,29,5,26],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","table":true,"pieces":[[3,4],[2,9],[5,0],[2,6]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"시금치","correct":true},{"t":"당근","mis":"M3-2-u6-X13"},{"t":"오이","mis":"M3-2-u6-X13"},{"t":"콩나물","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","시금치 줄은 10명 그림 2개와 1명 그림 1개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「시금치」예요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[35,21,29,45],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","table":true,"pieces":[[3,5],[1,2],[2,9],[4,5]]}},{"stem":"이번에는 다른 그림이에요. 표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"박물관","correct":true},{"t":"놀이공원","mis":"M3-2-u6-X13"},{"t":"과학관","mis":"M3-2-u6-X13"},{"t":"동물원","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","박물관 줄은 10명 그림 2개와 1명 그림 5개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「박물관」이에요."],"asset":{"type":"picg","title":"가고 싶어 하는 체험 학습 장소별 학생 수","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[37,25,17,15],"units":[10,1],"icon":"🙂","unit":"명","v