INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#19','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C5',3,'mc','auto','그림그래프를 보고 「식혜를 더 맛있게 만들어 봐요.」라고 정했어요. 알맞은 까닭은 무엇인가요?',ARRAY['M3-2-u6-X17','M3-2-u6-X04']::text[],true,'{"seq":19,"concept":"M3-2-u6-C5","difficulty":3,"kind":"mc","stem":"그림그래프를 보고 「식혜를 더 맛있게 만들어 봐요.」라고 정했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"좋아하는 학생이 가장 적어서 더 많은 학생이 좋아하게 하려고요","correct":true},{"t":"가장 많은 학생이 좋아하기 때문이에요","mis":"M3-2-u6-X17"},{"t":"그림을 가장 많이 그렸기 때문이에요","mis":"M3-2-u6-X04"},{"t":"이름이 가장 짧기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["정한 일과 그림그래프에서 읽은 사실이 맞아야 해요.","줄마다 수 — 떡국 124, 불고기 95, 비빔밥 71, 식혜 38.","알맞은 까닭 — 좋아하는 학생이 가장 적어서 더 많은 학생이 좋아하게 하려고요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜"],"counts":[124,95,71,38],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 「오이 반찬을 자주 내요.」라고 정했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"좋아하는 학생이 가장 많기 때문이에요","correct":true},{"t":"좋아하는 학생이 가장 적기 때문이에요","mis":"M3-2-u6-X17"},{"t":"작은 그림이 가장 많기 때문이에요","mis":"M3-2-u6-X04"},{"t":"채소 이름이 두 글자이기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["정한 일과 그림그래프에서 읽은 사실이 맞아야 해요.","줄마다 수 — 당근 18, 시금치 10, 오이 24, 콩나물 15.","알맞은 까닭 — 좋아하는 학생이 가장 많기 때문이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[18,10,24,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"그림그래프를 보고 「떡국을 급식에 넣어요.」라고 정했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"가장 많은 학생이 좋아하기 때문이에요","correct":true},{"t":"가장 적은 학생이 좋아하기 때문이에요","mis":"M3-2-u6-X17"},{"t":"그림이 가장 예쁘기 때문이에요","mis":"M3-2-u6-X17"},{"t":"표의 맨 앞에 있기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["정한 일과 그림그래프에서 읽은 사실이 맞아야 해요.","줄마다 수 — 떡국 130, 불고기 82, 비빔밥 64, 잡채 51.","알맞은 까닭 — 가장 많은 학생이 좋아하기 때문이에요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[130,82,64,51],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#20','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C6',3,'mc','auto','우리 반 28명이 모두 하나씩 골랐는데 표의 합계가 26명이에요. 가장 먼저 할 일은 무엇인가요?',ARRAY['M3-2-u6-X13','M3-2-u6-X10']::text[],true,'{"seq":20,"concept":"M3-2-u6-C6","difficulty":3,"kind":"mc","stem":"우리 반 28명이 모두 하나씩 골랐는데 표의 합계가 26명이에요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"빠뜨린 자료가 없는지 다시 세어 봐요","correct":true},{"t":"합계를 28명으로 고쳐 써요","mis":"M3-2-u6-X13"},{"t":"그대로 그림그래프를 그려요","mis":"M3-2-u6-X13"},{"t":"항목을 하나 더 만들어요","mis":"M3-2-u6-X10"}],"explanation":["합계는 조사한 사람 수와 같아야 해요.","28명과 26명이 달라 빠뜨린 자료가 있어요.","다시 세어 확인해요."],"variant_rule":{"alt":[{"stem":"우리 반 26명이 모두 하나씩 골랐는데 표의 합계가 25명이에요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"빠뜨린 자료가 없는지 다시 세어 봐요","correct":true},{"t":"합계를 26명으로 고쳐 써요","mis":"M3-2-u6-X13"},{"t":"그대로 그림그래프를 그려요","mis":"M3-2-u6-X13"},{"t":"항목을 하나 더 만들어요","mis":"M3-2-u6-X10"}],"explanation":["합계는 조사한 사람 수와 같아야 해요.","26명과 25명이 달라 빠뜨린 자료가 있어요.","다시 세어 확인해요."],"asset":null},{"stem":"우리 반 30명이 모두 하나씩 골랐는데 표의 합계가 29명이에요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"빠뜨린 자료가 없는지 다시 세어 봐요","correct":true},{"t":"합계를 30명으로 고쳐 써요","mis":"M3-2-u6-X13"},{"t":"그대로 그림그래프를 그려요","mis":"M3-2-u6-X13"},{"t":"항목을 하나 더 만들어요","mis":"M3-2-u6-X10"}],"explanation":["합계는 조사한 사람 수와 같아야 해요.","30명과 29명이 달라 빠뜨린 자료가 있어요.","다시 세어 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#21','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C7',3,'sa','auto','표를 보고 그린 그림그래프에서 도윤 줄을 덜 그렸어요. 1회 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"표를 보고 그린 그림그래프에서 도윤 줄을 덜 그렸어요. 1회 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["표에서 도윤은 18회예요.","그림은 17회만 나타내고 있어요.","18 − 17 = 1개 더 그려요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[17,27,18,19],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수","table":true,"pieces":[[3,2],[5,2],[3,2],[3,4]]},"variant_rule":{"alt":[{"stem":"표를 보고 그린 그림그래프에서 장미 줄을 덜 그렸어요. 1송이 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["표에서 장미는 19송이예요.","그림은 17송이만 나타내고 있어요.","19 − 17 = 2개 더 그려요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[19,9,14,24],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수","table":true,"pieces":[[3,2],[1,4],[2,4],[4,4]]}},{"stem":"표를 보고 그린 그림그래프에서 달님 모둠 줄을 덜 그렸어요. 1장 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["표에서 달님 모둠은 8장이에요.","그림은 6장만 나타내고 있어요.","8 − 6 = 2개 더 그려요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[3,8,7,27],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수","table":true,"pieces":[[0,3],[1,1],[1,2],[5,2]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#22','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C9',3,'mc','auto','그림그래프에서 그림의 크기를 정할 때 알맞은 것은 무엇인가요?',ARRAY['M3-2-u6-X15']::text[],true,'{"seq":22,"concept":"M3-2-u6-C9","difficulty":3,"kind":"mc","stem":"그림그래프에서 그림의 크기를 정할 때 알맞은 것은 무엇인가요?","options":[{"t":"같은 수를 나타내는 그림은 같은 크기로 그려요","correct":true},{"t":"수가 많은 줄은 그림을 더 크게 그려요","mis":"M3-2-u6-X15"},{"t":"마음에 드는 줄의 그림을 크게 그려요","mis":"M3-2-u6-X15"},{"t":"그림 크기는 아무렇게나 해요","mis":"M3-2-u6-X15"}],"explanation":["그림을 크게 그리면 넓이가 커져 실제보다 많아 보여요.","같은 수를 나타내는 그림은 크기가 같아야 해요.","답은 「같은 수를 나타내는 그림은 같은 크기로 그려요」예요."],"variant_rule":{"alt":[{"stem":"「축구를 좋아하는 학생은 그림이 가장 커 보이니 가장 많아요.」라는 말에 대해 알맞은 것은 무엇인가요?","options":[{"t":"그림의 크기가 아니라 그림이 나타내는 수로 견주어야 해요","correct":true},{"t":"맞는 말이에요","mis":"M3-2-u6-X15"},{"t":"그림이 크면 언제나 수가 많아요","mis":"M3-2-u6-X15"},{"t":"그림이 작을수록 수가 많아요","mis":"M3-2-u6-X15"}],"explanation":["그림을 크게 그리면 넓이가 커져 실제보다 많아 보여요.","같은 수를 나타내는 그림은 크기가 같아야 해요.","답은 「그림의 크기가 아니라 그림이 나타내는 수로 견주어야 해요」예요."],"asset":null},{"stem":"한 그림그래프에서 어떤 줄의 그림만 다른 줄보다 훨씬 크게 그렸어요. 바르게 말한 것은 무엇인가요?","options":[{"t":"실제보다 많아 보여 잘못 읽을 수 있어요","correct":true},{"t":"그 줄의 수가 가장 많아요","mis":"M3-2-u6-X15"},{"t":"크게 그리면 수가 정확해져요","mis":"M3-2-u6-X15"},{"t":"그림의 크기는 아무 상관이 없어요","mis":"M3-2-u6-X15"}],"explanation":["그림을 크게 그리면 넓이가 커져 실제보다 많아 보여요.","같은 수를 나타내는 그림은 크기가 같아야 해요.","답은 「실제보다 많아 보여 잘못 읽을 수 있어요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#23','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',4,'sa','auto','학생 수의 합계는 108명이에요. 그림그래프에서 축구부 줄이 지워졌어요. 축구부에 가입한 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u6-C3","difficulty":4,"kind":"sa","stem":"학생 수의 합계는 108명이에요. 그림그래프에서 축구부 줄이 지워졌어요. 축구부에 가입한 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["보이는 줄의 수를 읽어요 — 40, 9, 34.","모르는 수 = 합계 − 아는 수들이에요.","108 − 40 − 9 − 34 = 25명이에요."],"asset":{"type":"picg","title":"가입한 동아리별 학생 수","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[40,9,null,34],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[2]},"variant_rule":{"alt":[{"stem":"학생 수의 합계는 188명이에요. 그림그래프에서 투호 줄이 지워졌어요. 투호를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["보이는 줄의 수를 읽어요 — 49, 47, 48.","모르는 수 = 합계 − 아는 수들이에요.","188 − 49 − 47 − 48 = 44명이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 학생 수","head":"민속놀이","cols":["윷놀이","투호","연날리기","제기차기"],"counts":[49,null,47,48],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[1]}},{"stem":"오리의 수의 합계는 132마리예요. 그림그래프에서 햇살 농장 줄이 지워졌어요. 햇살 농장에서 기르는 오리는 몇 마리인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["보이는 줄의 수를 읽어요 — 32, 41, 21.","모르는 수 = 합계 − 아는 수들이에요.","132 − 32 − 41 − 21 = 38마리예요."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["초록 농장","햇살 농장","바람 농장","들꽃 농장"],"counts":[32,null,41,21],"units":[10,1],"icon":"🦆","unit":"마리","vh":"오리의 수","blank":[1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#24','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C4',4,'mc','auto','이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X01']::text[],true,'{"seq":24,"concept":"M3-2-u6-C4","difficulty":4,"kind":"mc","stem":"이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?","options":[{"t":"오이","correct":true},{"t":"당근","mis":"M3-2-u6-X03"},{"t":"시금치","mis":"M3-2-u6-X01"},{"t":"콩나물","mis":"M3-2-u6-X01"}],"explanation":["그림 수 = 십의 자리 수 + 일의 자리 수예요.","당근 14 → 5개, 시금치 36 → 9개, 오이 22 → 4개, 콩나물 26 → 8개.","가장 적게 그리는 것은 오이예요 — 수가 가장 작은 것과 다를 수 있어요."],"asset":{"type":"picg","only":"table","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[14,36,22,26],"unit":"명","vh":"학생 수","title":"좋아하는 채소별 학생 수","total":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?","options":[{"t":"동물원","correct":true},{"t":"놀이공원","mis":"M3-2-u6-X01"},{"t":"박물관","mis":"M3-2-u6-X03"},{"t":"과학관","mis":"M3-2-u6-X01"}],"explanation":["그림 수 = 십의 자리 수 + 일의 자리 수예요.","놀이공원 35 → 8개, 박물관 14 → 5개, 과학관 32 → 5개, 동물원 40 → 4개.","가장 적게 그리는 것은 동물원이에요 — 수가 가장 작은 것과 다를 수 있어요."],"asset":{"type":"picg","only":"table","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[35,14,32,40],"unit":"명","vh":"학생 수","title":"가고 싶어 하는 체험 학습 장소별 학생 수","total":false}},{"stem":"이번에는 다른 그림이에요. 이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?","options":[{"t":"미술부","correct":true},{"t":"합창부","mis":"M3-2-u6-X01"},{"t":"로봇부","mis":"M3-2-u6-X01"},{"t":"축구부","mis":"M3-2-u6-X03"}],"explanation":["그림 수 = 십의 자리 수 + 일의 자리 수예요.","합창부 34 → 7개, 로봇부 25 → 7개, 축구부 7 → 7개, 미술부 12 → 3개.","가장 적게 그리는 것은 미술부예요 — 수가 가장 작은 것과 다를 수 있어요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[34,25,7,12],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수","total":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_a#25','math',3,2,'u6','','g3_2_math_u6_review_a','unit_review','M3-2-u6-C2',4,'essay','teacher','도넛 가게에서 판매한 도넛의 수를 큰 그림 10개, 작은 그림 1개로 나타냈어요. 크림도넛 줄은 큰 그림 3개와 작은 그림 5개예요. 「그림이 8개니까 8개 팔았어.」라는 말이 잘못된 까닭을 쓰고, 크림도넛을 몇 개 팔았는지 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u6-C2","difficulty":4,"kind":"essay","stem":"도넛 가게에서 판매한 도넛의 수를 큰 그림 10개, 작은 그림 1개로 나타냈어요. 크림도넛 줄은 큰 그림 3개와 작은 그림 5개예요. 「그림이 8개니까 8개 팔았어.」라는 말이 잘못된 까닭을 쓰고, 크림도넛을 몇 개 팔았는지 구해 보세요.","answer_guide":{"answer":"예: 큰 그림과 작은 그림이 나타내는 수가 다른데 그림의 개수만 세었다. 큰 그림 3개는 30개, 작은 그림 5개는 5개이므로 크림도넛은 35개 팔았다.","scoring_points":["그림의 개수만 세었다고 까닭을 썼는가","큰 그림 3개 = 30개, 작은 그림 5개 = 5개로 읽었는가","35개를 구했는가"]},"explanation":["그림 뜻을 먼저 봐요.","30 + 5 = 35.","35개 팔았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#1','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C1',1,'mc','auto','◯ 그래프를 보고 가장 많은 학생이 좋아하는 동물을 고르세요.',ARRAY['M3-2-u6-X09','M3-2-u6-X16']::text[],true,'{"seq":1,"concept":"M3-2-u6-C1","difficulty":1,"kind":"mc","stem":"◯ 그래프를 보고 가장 많은 학생이 좋아하는 동물을 고르세요.","options":[{"t":"앵무새","correct":true},{"t":"개","mis":"M3-2-u6-X09"},{"t":"고양이","mis":"M3-2-u6-X09"},{"t":"토끼","mis":"M3-2-u6-X16"}],"explanation":["◯ 그래프는 ◯의 높이로 많고 적음을 한눈에 알 수 있어요.","◯가 가장 높이 올라간 것은 앵무새.","답은 「앵무새」예요."],"asset":{"type":"pgraph","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼"],"counts":[7,8,3,2],"unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"◯ 그래프를 보고 가장 적은 학생이 좋아하는 과일을 고르세요.","options":[{"t":"자두","correct":true},{"t":"포도","mis":"M3-2-u6-X09"},{"t":"키위","mis":"M3-2-u6-X16"},{"t":"감","mis":"M3-2-u6-X09"}],"explanation":["◯ 그래프는 ◯의 높이로 많고 적음을 한눈에 알 수 있어요.","◯가 가장 적게 그려진 것은 자두.","답은 「자두」예요."],"asset":{"type":"pgraph","topic":"fruit","title":"우리 반 학생들이 좋아하는 과일별 학생 수","head":"과일","cols":["자두","포도","키위","감"],"counts":[3,7,8,6],"unit":"명","vh":"학생 수"}},{"stem":"◯ 그래프를 보고 가장 많은 학생이 태어난 계절을 고르세요.","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M3-2-u6-X09"},{"t":"여름","mis":"M3-2-u6-X16"},{"t":"가을","mis":"M3-2-u6-X09"}],"explanation":["◯ 그래프는 ◯의 높이로 많고 적음을 한눈에 알 수 있어요.","◯가 가장 높이 올라간 것은 겨울.","답은 「겨울」이에요."],"asset":{"type":"pgraph","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[3,2,4,5],"unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#2','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C2',1,'mc','auto','그림그래프에서 큰 그림 🍩 한 개는 몇 개를 나타내나요?',ARRAY['M3-2-u6-X02']::text[],true,'{"seq":2,"concept":"M3-2-u6-C2","difficulty":1,"kind":"mc","stem":"그림그래프에서 큰 그림 🍩 한 개는 몇 개를 나타내나요?","options":[{"t":"10개","correct":true},{"t":"1개","mis":"M3-2-u6-X02"},{"t":"5개","mis":"M3-2-u6-X02"},{"t":"100개","mis":"M3-2-u6-X02"}],"explanation":["그림그래프 아래의 그림 뜻을 봐요.","큰 그림은 10개, 작은 그림은 1개예요.","큰 그림 한 개는 10개예요."],"asset":{"type":"picg","title":"종류별 판매한 도넛의 수","head":"종류","cols":["크림도넛","초코도넛","딸기도넛","꿀도넛"],"counts":[30,32,11,25],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 작은 그림 📕 한 개는 몇 권을 나타내나요?","options":[{"t":"1권","correct":true},{"t":"10권","mis":"M3-2-u6-X02"},{"t":"5권","mis":"M3-2-u6-X02"},{"t":"100권","mis":"M3-2-u6-X02"}],"explanation":["그림그래프 아래의 그림 뜻을 봐요.","큰 그림은 10권, 작은 그림은 1권이에요.","작은 그림 한 개는 1권이에요."],"asset":{"type":"picg","title":"반별 빌린 책의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[29,10,7,11],"units":[10,1],"icon":"📕","unit":"권","vh":"책의 수"}},{"stem":"그림그래프에서 큰 그림 🌳 한 개는 몇 그루를 나타내나요?","options":[{"t":"10그루","correct":true},{"t":"1그루","mis":"M3-2-u6-X02"},{"t":"5그루","mis":"M3-2-u6-X02"},{"t":"100그루","mis":"M3-2-u6-X02"}],"explanation":["그림그래프 아래의 그림 뜻을 봐요.","큰 그림은 10그루, 작은 그림은 1그루예요.","큰 그림 한 개는 10그루예요."],"asset":{"type":"picg","title":"마을별 심은 나무의 수","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[34,49,32,43],"units":[10,1],"icon":"🌳","unit":"그루","vh":"나무의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_v