INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#3','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C4',1,'sa','auto','판매한 크림도넛 33개를 그림그래프로 나타내요. 큰 그림이 10개, 작은 그림이 1개를 나타낼 때 1개 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C4","difficulty":1,"kind":"sa","stem":"판매한 크림도넛 33개를 그림그래프로 나타내요. 큰 그림이 10개, 작은 그림이 1개를 나타낼 때 1개 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 그림부터 그려요.","33개는 10개 그림 3개와 1개 그림 3개예요.","1개 그림은 3개예요."],"variant_rule":{"alt":[{"stem":"2반에서 빌린 책 38권을 그림그래프로 나타내요. 큰 그림이 10권, 작은 그림이 1권을 나타낼 때 1권 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["8"],"explanation":["큰 그림부터 그려요.","38권은 10권 그림 3개와 1권 그림 8개예요.","1권 그림은 8개예요."],"asset":null},{"stem":"구름 마을에 심은 나무 47그루를 그림그래프로 나타내요. 큰 그림이 10그루, 작은 그림이 1그루를 나타낼 때 1그루 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["7"],"explanation":["큰 그림부터 그려요.","47그루는 10그루 그림 4개와 1그루 그림 7개예요.","1그루 그림은 7개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#4','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C4',1,'mc','auto','큰 그림과 작은 그림을 그릴 때 알맞은 방법은 무엇인가요?',ARRAY['M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":4,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"큰 그림과 작은 그림을 그릴 때 알맞은 방법은 무엇인가요?","options":[{"t":"큰 그림을 먼저 그리고 남은 수를 작은 그림으로 그려요","correct":true},{"t":"작은 그림을 먼저 그리고 남은 수를 큰 그림으로 그려요","mis":"M3-2-u6-X06"},{"t":"작은 그림만 수만큼 그려요","mis":"M3-2-u6-X06"},{"t":"큰 그림만 수만큼 그려요","mis":"M3-2-u6-X02"}],"explanation":["그림그래프는 큰 그림부터 그려요.","그러면 큰 그림의 개수로 많고 적음을 바로 견줄 수 있어요.","답은 「큰 그림을 먼저 그리고 남은 수를 작은 그림으로 그려요」예요."],"variant_rule":{"alt":[{"stem":"그림그래프로 나타낼 때 어떤 그림을 먼저 그리면 수를 견주기 쉬운가요?","options":[{"t":"큰 수를 나타내는 그림","correct":true},{"t":"작은 수를 나타내는 그림","mis":"M3-2-u6-X06"},{"t":"아무 그림이나","mis":"M3-2-u6-X07"},{"t":"가장 예쁜 그림","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 큰 그림부터 그려요.","그러면 큰 그림의 개수로 많고 적음을 바로 견줄 수 있어요.","답은 「큰 수를 나타내는 그림」이에요."],"asset":null},{"stem":"표의 수를 그림그래프로 옮길 때 먼저 정해야 하는 것은 무엇인가요?","options":[{"t":"그림과 그림이 나타내는 수(단위)","correct":true},{"t":"그림의 색깔","mis":"M3-2-u6-X07"},{"t":"그림을 그릴 연필","mis":"M3-2-u6-X07"},{"t":"그래프의 크기","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 큰 그림부터 그려요.","그러면 큰 그림의 개수로 많고 적음을 바로 견줄 수 있어요.","답은 「그림과 그림이 나타내는 수(단위)」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#5','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C6',1,'mc','auto','그림그래프로 나타내기 좋게 항목을 정하려고 해요. 항목의 수로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u6-X10']::text[],true,'{"seq":5,"concept":"M3-2-u6-C6","difficulty":1,"kind":"mc","stem":"그림그래프로 나타내기 좋게 항목을 정하려고 해요. 항목의 수로 알맞은 것은 무엇인가요?","options":[{"t":"4~6개","correct":true},{"t":"1개","mis":"M3-2-u6-X10"},{"t":"20개","mis":"M3-2-u6-X10"},{"t":"정하지 않아요","mis":"M3-2-u6-X10"}],"explanation":["항목이 너무 적으면 견줄 것이 없고, 너무 많으면 정리하기 어려워요.","그래서 4~6개 사이로 정해요.","답은 「4~6개」예요."],"variant_rule":{"alt":[{"stem":"좋아하는 운동을 조사할 때 항목의 수로 알맞은 것은 무엇인가요?","options":[{"t":"4~6개","correct":true},{"t":"1개","mis":"M3-2-u6-X10"},{"t":"20개","mis":"M3-2-u6-X10"},{"t":"정하지 않아요","mis":"M3-2-u6-X10"}],"explanation":["항목이 너무 적으면 견줄 것이 없고, 너무 많으면 정리하기 어려워요.","그래서 4~6개 사이로 정해요.","답은 「4~6개」예요."],"asset":null},{"stem":"조사할 항목은 몇 개쯤으로 정하면 좋을까요?","options":[{"t":"4~6개","correct":true},{"t":"1개","mis":"M3-2-u6-X10"},{"t":"20개","mis":"M3-2-u6-X10"},{"t":"정하지 않아요","mis":"M3-2-u6-X10"}],"explanation":["항목이 너무 적으면 견줄 것이 없고, 너무 많으면 정리하기 어려워요.","그래서 4~6개 사이로 정해요.","답은 「4~6개」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#6','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C7',1,'sa','auto','해님 모둠이 모은 붙임딱지 21장을 그림그래프로 나타내요. 큰 그림이 5장, 작은 그림이 1장을 나타낼 때 1장 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u6-C7","difficulty":1,"kind":"sa","stem":"해님 모둠이 모은 붙임딱지 21장을 그림그래프로 나타내요. 큰 그림이 5장, 작은 그림이 1장을 나타낼 때 1장 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["1"],"explanation":["큰 그림부터 그려요.","21장은 5장 그림 4개와 1장 그림 1개예요.","1장 그림은 1개예요."],"variant_rule":{"alt":[{"stem":"서준이 운동한 횟수 17회를 그림그래프로 나타내요. 큰 그림이 5회, 작은 그림이 1회를 나타낼 때 1회 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","17회는 5회 그림 3개와 1회 그림 2개예요.","1회 그림은 2개예요."],"asset":null},{"stem":"도윤이 훌라후프를 한 횟수 27회를 그림그래프로 나타내요. 큰 그림이 5회, 작은 그림이 1회를 나타낼 때 1회 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","27회는 5회 그림 5개와 1회 그림 2개예요.","1회 그림은 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#7','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C8',1,'sa','auto','가 그림그래프에서 겨울의 산불 발생 건수 199건을 나타낼 때 10건 그림은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u6-C8","difficulty":1,"kind":"sa","stem":"가 그림그래프에서 겨울의 산불 발생 건수 199건을 나타낼 때 10건 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["가는 10건·1건 두 가지 그림이라 100건 그림이 없어요.","199건은 10건 그림 19개와 1건 그림 9개예요.","10건 그림은 19개예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[334,165,194,199],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"가 그림그래프에서 월요일에 도서관을 찾은 사람 243명을 나타낼 때 10명 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["가는 10명·1명 두 가지 그림이라 100명 그림이 없어요.","243명은 10명 그림 24개와 1명 그림 3개예요.","10명 그림은 24개예요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수 — 가: 10·1, 나: 100·10·1","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[243,131,392,173],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수","units2":[100,10,1]}},{"stem":"가 그림그래프에서 구름 마을의 사과 생산량 392상자를 나타낼 때 10상자 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["가는 10상자·1상자 두 가지 그림이라 100상자 그림이 없어요.","392상자는 10상자 그림 39개와 1상자 그림 2개예요.","10상자 그림은 39개예요."],"asset":{"type":"picg","title":"마을별 사과 생산량 — 가: 10·1, 나: 100·10·1","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[224,364,392,166],"units":[10,1],"icon":"🍎","unit":"상자","vh":"생산량","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#8','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C8',1,'mc','auto','나 그림그래프가 가와 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u6-X02','M3-2-u6-X13','M3-2-u6-X14']::text[],true,'{"seq":8,"concept":"M3-2-u6-C8","difficulty":1,"kind":"mc","stem":"나 그림그래프가 가와 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"100건을 나타내는 그림이 있어요","correct":true},{"t":"1건을 나타내는 그림이 없어요","mis":"M3-2-u6-X02"},{"t":"겨울이 빠졌어요","mis":"M3-2-u6-X13"},{"t":"건수가 더 많아요","mis":"M3-2-u6-X14"}],"explanation":["같은 자료라서 건수는 같아요.","가는 10건·1건, 나는 100건·10건·1건 — 단위의 종류가 달라 그림 개수가 달라요.","답은 「100건을 나타내는 그림이 있어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"가와 나 그림그래프의 다른 점은 무엇인가요?","options":[{"t":"단위의 종류가 달라요","correct":true},{"t":"조사한 계절이 달라요","mis":"M3-2-u6-X14"},{"t":"산불 발생 건수가 달라요","mis":"M3-2-u6-X14"},{"t":"그림이 달라요","mis":"M3-2-u6-X14"}],"explanation":["같은 자료라서 건수는 같아요.","가는 10건·1건, 나는 100건·10건·1건 — 단위의 종류가 달라 그림 개수가 달라요.","답은 「단위의 종류가 달라요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"가와 나 그림그래프에서 다른 것은 무엇인가요?","options":[{"t":"그린 그림의 개수","correct":true},{"t":"봄의 산불 발생 건수","mis":"M3-2-u6-X14"},{"t":"조사한 계절","mis":"M3-2-u6-X14"},{"t":"그림의 모양","mis":"M3-2-u6-X14"}],"explanation":["같은 자료라서 건수는 같아요.","가는 10건·1건, 나는 100건·10건·1건 — 단위의 종류가 달라 그림 개수가 달라요.","답은 「그린 그림의 개수」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#9','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C1',2,'sa','auto','좋아하는 과일별 학생 수 표예요. 사과와 배를 좋아하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u6-C1","difficulty":2,"kind":"sa","stem":"좋아하는 과일별 학생 수 표예요. 사과와 배를 좋아하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["사과는 21명, 배는 27명이에요.","모두 몇인지 물으면 더해요.","21 + 27 = 48명이에요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["귤","사과","포도","배"],"counts":[9,21,22,27],"unit":"명","vh":"학생 수","title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"배우고 싶어 하는 악기별 학생 수 표예요. 가야금과 오카리나를 배우고 싶어 하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["가야금은 28명, 오카리나는 27명이에요.","모두 몇인지 물으면 더해요.","28 + 27 = 55명이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[28,27,26,30],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수"}},{"stem":"여행 가고 싶어 하는 나라별 학생 수 표예요. 프랑스와 미국에 가고 싶어 하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["프랑스는 10명, 미국은 26명이에요.","모두 몇인지 물으면 더해요.","10 + 26 = 36명이에요."],"asset":{"type":"picg","only":"table","head":"나라","cols":["미국","일본","영국","프랑스"],"counts":[26,27,19,10],"unit":"명","vh":"학생 수","title":"여행 가고 싶어 하는 나라별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#10','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',2,'mc','auto','그림그래프에서 가장 적은 학생이 배우고 싶어 하는 악기는 무엇인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X03','M3-2-u6-X04']::text[],true,'{"seq":10,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"그림그래프에서 가장 적은 학생이 배우고 싶어 하는 악기는 무엇인가요?","options":[{"t":"가야금","correct":true},{"t":"오카리나","mis":"M3-2-u6-X16"},{"t":"우쿨렐레","mis":"M3-2-u6-X03"},{"t":"플루트","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 가장 적은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 가야금 18, 오카리나 47, 우쿨렐레 19, 플루트 20.","가장 적은 것은 「가야금」이에요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[18,47,19,20],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 가장 적은 학생이 좋아하는 여가 활동은 무엇인가요?","options":[{"t":"자전거 타기","correct":true},{"t":"배드민턴","mis":"M3-2-u6-X16"},{"t":"산책","mis":"M3-2-u6-X04"},{"t":"줄넘기","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 가장 적은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 배드민턴 33, 산책 20, 자전거 타기 12, 줄넘기 25.","가장 적은 것은 「자전거 타기」예요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[33,20,12,25],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"그림그래프에서 가장 적은 학생이 좋아하는 채소는 무엇인가요?","options":[{"t":"당근","correct":true},{"t":"시금치","mis":"M3-2-u6-X03"},{"t":"오이","mis":"M3-2-u6-X16"},{"t":"콩나물","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 가장 적은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 당근 28, 시금치 43, 오이 45, 콩나물 40.","가장 적은 것은 「당근」이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[28,43,45,40],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#11','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',2,'sa','auto','그림그래프에서 1반에서 빌린 책은 2반에서 빌린 책보다 몇 권 더 많나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-2-u6-C3","difficulty":2,"kind":"sa","stem":"그림그래프에서 1반에서 빌린 책은 2반에서 빌린 책보다 몇 권 더 많나요? 숫자로 쓰세요.","answer":["8"],"explanation":["1반은 32권, 2반은 24권이에요.","더 많은 수에서 적은 수를 빼요.","32 − 24 = 8권이에요."],"asset":{"type":"picg","title":"반별 빌린 책의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[32,24,46,47],"units":[10,1],"icon":"📕","unit":"권","vh":"책의 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 구름 마을에 심은 나무는 바람 마을에 심은 나무보다 몇 그루 더 많나요? 숫자로 쓰세요.","answer":["28"],"explanation":["구름 마을은 38그루, 바람 마을은 10그루예요.","더 많은 수에서 적은 수를 빼요.","38 − 10 = 28그루예요."],"asset":{"type":"picg","title":"마을별 심은 나무의 수","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[8,10,38,27],"units":[10,1],"icon":"🌳","unit":"그루","vh":"나무의 수"}},{"stem":"그림그래프에서 1반에서 모은 빈 병은 3반에서 모은 빈 병보다 몇 개 더 많나요? 숫자로 쓰세요.","answer":["21"],"explanation":["1반은 26개, 3반은 5개예요.","더 많은 수에서 적은 수를 빼요.","26 − 5 = 21개예요."],"asset":{"type":"picg","title":"반별 모은 빈 병의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[26,39,5,30],"units":[10,1],"icon":"🍾","unit":"개","vh":"빈 병의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#12','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C4',2,'sa','auto','그림그래프를 보고 불고기를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u6-C4","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 불고기를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["167"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 100명, 가운데 그림 10명, 작은 그림 1명.","불고기 줄은 100명 그림 1개, 10명 그림 6개와 1명 그림 7개예요.","불고기를 좋아하는 학생은 167명이에요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[76,167,103,252],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 가을의 산불 발생 건수는 몇 건인지 구하세요. 숫자로 쓰세요.","answer":["211"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 100건, 가운데 그림 10건, 작은 그림 1건.","가을 줄은 100건 그림 2개, 10건 그림 1개와 1건 그림 1개예요.","가을의 산불 발생 건수는 211건이에요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[399,221,211,287],"units":[100,10,1],"icon":"🔥","unit":"건","vh":"발생 건수"}},{"stem":"그림그래프를 보고 목요일에 도서관을 찾은 사람은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["181"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 100명, 가운데 그림 10명, 작은 그림 1명.","목요일 줄은 100명 그림 1개, 10명 그림 8개와 1명 그림 1개예요.","목요일에 도서관을 찾은 사람은 181명이에요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[386,201,217,181],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"사람 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#13','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C5',2,'mc','auto','그림그래프를 보고 무엇을 조사했는지 알려면 무엇을 보면 되나요?',ARRAY['M3-2-u6-X01','M3-2-u6-X07']::text[],true,'{"seq":13,"concept":"M3-2-u6-C5","difficulty":2,"kind":"mc","stem":"그림그래프를 보고 무엇을 조사했는지 알려면 무엇을 보면 되나요?","options":[{"t":"제목","correct":true},{"t":"가장 큰 그림","mis":"M3-2-u6-X01"},{"t":"그림의 색깔","mis":"M3-2-u6-X07"},{"t":"작은 그림의 개수","mis":"M3-2-u6-X01"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지로 이루어져요.","단위가 없으면 그림을 읽을 수 없어요.","답은 「제목」이에요."],"variant_rule":{"alt":[{"stem":"그림그래프에 그림이 나타내는 수를 쓰지 않으면 어떤 일이 생기나요?","options":[{"t":"그림이 몇을 나타내는지 몰라 수를 읽을 수 없어요","correct":true},{"t":"제목을 알 수 없어요","mis":"M3-2-u6-X07"},{"t":"항목이 늘어나요","mis":"M3-2-u6-X07"},{"t":"아무 일도 없어요","mis":"M3-2-u6-X02"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지로 이루어져요.","단위가 없으면 그림을 읽을 수 없어요.","답은 「그림이 몇을 나타내는지 몰라 수를 읽을 수 없어요」예요."],"asset":null},{"stem":"그림그래프에 꼭 있어야 하는 것이 아닌 것은 무엇인가요?","options":[{"t":"조사한 사람의 이름","correct":true},{"t":"제목","mis":"M3-2-u6-X07"},{"t":"그림이 나타내는 수","mis":"M3-2-u6-X07"},{"t":"조사한 항목","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지로 이루어져요.","단위가 없으면 그림을 읽을 수 없어요.","답은 「조사한 사람의 이름」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#14','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C6',2,'mc','auto','조사 계획부터 그림그래프까지, 차례로 바르게 쓴 것은 무엇인가요?',ARRAY['M3-2-u6-X12']::text[],true,'{"seq":14,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"조사 계획부터 그림그래프까지, 차례로 바르게 쓴 것은 무엇인가요?","options":[{"t":"주제와 대상·항목 → 조사 방법·수집 → 표 → 그림그래프","correct":true},{"t":"조사 방법·수집 → 그림그래프 → 주제와 대상·항목 → 표","mis":"M3-2-u6-X12"},{"t":"그림그래프 → 표 → 조사 방법·수집 → 주제와 대상·항목","mis":"M3-2-u6-X12"},{"t":"표 → 주제와 대상·항목 → 그림그래프 → 조사 방법·수집","mis":"M3-2-u6-X12"}],"explanation":["무엇을 누구에게 물을지 먼저 정해요.","모은 자료는 표로 정리하고, 표를 보고 그림그래프로 나타내요.","답은 주제와 대상·항목 → 조사 방법·수집 → 표 → 그림그래프."],"variant_rule":{"alt":[{"stem":"자료를 모아 그림그래프로 나타내는 순서로 알맞은 것은 무엇인가요?","options":[{"t":"주제와 대상·항목 → 조사 방법·수집 → 표 → 그림그래프","correct":true},{"t":"그림그래프 → 표 → 조사 방법·수집 → 주제와 대상·항목","mis":"M3-2-u6-X12"},{"t":"표 → 주제와 대상·항목 → 그림그래프 → 조사 방법·수집","mis":"M3-2-u6-X12"},{"t":"조사 방법·수집 → 그림그래프 → 주제와 대상·항목 → 표","mis":"M3-2-u6-X12"}],"explanation":["무엇을 누구에게 물을지 먼저 정해요.","모은 자료는 표로 정리하고, 표를 보고 그림그래프로 나타내요.","답은 주제와 대상·항목 → 조사 방법·수집 → 표 → 그림그래프."],"asset":null},{"stem":"우리 모둠이 조사해 그림그래프를 만들어요. 하는 순서로 알맞은 것은 무엇인가요?","options":[{"t":"주제와 대상·항목 → 조사 방법·수집 → 표 → 그림그래프","correct":true},{"t":"표 → 주제와 대상·항목 → 그림그래프 → 조사 방법·수집","mis":"M3-2-u6-X12"},{"t":"조사 방법·수집 → 그림그래프 → 주제와 대상·항목 → 표","mis":"M3-2-u6-X12"},{"t":"그림그래프 → 표 → 조사 방법·수집 → 주제와 대상·항목","mis":"M3-2-u6-X12"}],"explanation":["무엇을 누구에게 물을지 먼저 정해요.","모은 자료는 표로 정리하고, 표를 보고 그림그래프로 나타내요.","답은 주제와 대상·항목 → 조사 방법·수집 → 표 → 그림그래프."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant,