INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#15','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C7',2,'sa','auto','그림그래프를 보고 해바라기는 몇 송이인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M3-2-u6-C7","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 해바라기는 몇 송이인지 구하세요. 숫자로 쓰세요.","answer":["15"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5송이, 작은 그림 1송이.","해바라기 줄은 5송이 그림 3개예요.","해바라기는 15송이예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[20,9,29,15],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 해님 모둠이 모은 붙임딱지는 몇 장인지 구하세요. 숫자로 쓰세요.","answer":["12"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5장, 작은 그림 1장.","해님 모둠 줄은 5장 그림 2개와 1장 그림 2개예요.","해님 모둠이 모은 붙임딱지는 12장이에요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[12,3,5,19],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수"}},{"stem":"그림그래프를 보고 건우가 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["15"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","건우 줄은 5회 그림 3개예요.","건우가 운동한 횟수는 15회예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[15,9,28,21],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#16','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C8',2,'mc','auto','그림의 단위를 네 가지, 다섯 가지로 계속 늘리면 어떤 점이 어려울까요?',ARRAY['M3-2-u6-X14','M3-2-u6-X07']::text[],true,'{"seq":16,"concept":"M3-2-u6-C8","difficulty":2,"kind":"mc","stem":"그림의 단위를 네 가지, 다섯 가지로 계속 늘리면 어떤 점이 어려울까요?","options":[{"t":"그림의 크기를 구분하기가 더 어려워요","correct":true},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"큰 수를 나타낼 수 없어요","mis":"M3-2-u6-X14"},{"t":"항목을 쓸 수 없어요","mis":"M3-2-u6-X07"}],"explanation":["단위가 늘면 그림 크기가 셋, 넷으로 늘어나요.","크기가 비슷하면 어떤 그림인지 헷갈려요.","답은 「그림의 크기를 구분하기가 더 어려워요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"단위의 종류가 늘어나면 불편한 점은 무엇인가요?","options":[{"t":"그림의 크기를 뚜렷이 구분해 그리기 어려워요","correct":true},{"t":"큰 수를 나타낼 수 없어요","mis":"M3-2-u6-X14"},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"제목을 쓸 수 없어요","mis":"M3-2-u6-X07"}],"explanation":["단위가 늘면 그림 크기가 셋, 넷으로 늘어나요.","크기가 비슷하면 어떤 그림인지 헷갈려요.","답은 「그림의 크기를 뚜렷이 구분해 그리기 어려워요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"나 그림그래프를 읽을 때 조심할 점은 무엇인가요?","options":[{"t":"세 가지 크기의 그림을 잘 구분해 읽어요","correct":true},{"t":"그림의 개수만 세어요","mis":"M3-2-u6-X01"},{"t":"가장 큰 그림만 세어요","mis":"M3-2-u6-X06"},{"t":"작은 그림은 빼고 읽어요","mis":"M3-2-u6-X06"}],"explanation":["단위가 늘면 그림 크기가 셋, 넷으로 늘어나요.","크기가 비슷하면 어떤 그림인지 헷갈려요.","답은 「세 가지 크기의 그림을 잘 구분해 읽어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#17','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',3,'mc','auto','그림그래프를 보고 가장 많은 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16','M3-2-u6-X03']::text[],true,'{"seq":17,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"그림그래프를 보고 가장 많은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"당근 → 콩나물 → 시금치 → 오이","correct":true},{"t":"오이 → 콩나물 → 당근 → 시금치","mis":"M3-2-u6-X04"},{"t":"오이 → 시금치 → 콩나물 → 당근","mis":"M3-2-u6-X16"},{"t":"콩나물 → 당근 → 시금치 → 오이","mis":"M3-2-u6-X03"}],"explanation":["줄마다 수를 읽어요 — 당근 31, 시금치 22, 오이 9, 콩나물 24.","그림 개수가 아니라 나타내는 수로 차례를 정해요.","당근 → 콩나물 → 시금치 → 오이."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[31,22,9,24],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 가장 적은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"과학관 → 박물관 → 동물원 → 놀이공원","correct":true},{"t":"박물관 → 동물원 → 놀이공원 → 과학관","mis":"M3-2-u6-X04"},{"t":"놀이공원 → 동물원 → 박물관 → 과학관","mis":"M3-2-u6-X16"},{"t":"박물관 → 과학관 → 동물원 → 놀이공원","mis":"M3-2-u6-X03"}],"explanation":["줄마다 수를 읽어요 — 놀이공원 23, 박물관 10, 과학관 9, 동물원 14.","그림 개수가 아니라 나타내는 수로 차례를 정해요.","과학관 → 박물관 → 동물원 → 놀이공원."],"asset":{"type":"picg","title":"가고 싶어 하는 체험 학습 장소별 학생 수","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[23,10,9,14],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"이번에는 다른 그림이에요. 그림그래프를 보고 가장 많은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"합창부 → 미술부 → 로봇부 → 축구부","correct":true},{"t":"미술부 → 합창부 → 로봇부 → 축구부","mis":"M3-2-u6-X04"},{"t":"축구부 → 로봇부 → 미술부 → 합창부","mis":"M3-2-u6-X16"},{"t":"합창부 → 로봇부 → 축구부 → 미술부","mis":"M3-2-u6-X04"}],"explanation":["줄마다 수를 읽어요 — 합창부 26, 로봇부 14, 축구부 5, 미술부 19.","그림 개수가 아니라 나타내는 수로 차례를 정해요.","합창부 → 미술부 → 로봇부 → 축구부."],"asset":{"type":"picg","title":"가입한 동아리별 학생 수","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[26,14,5,19],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#18','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C4',3,'sa','auto','이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-2-u6-C4","difficulty":3,"kind":"sa","stem":"이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.","answer":["25"],"explanation":["줄마다 큰 그림과 작은 그림의 개수를 구해요.","36 → 9개, 30 → 3개, 24 → 6개, 25 → 7개.","9 + 3 + 6 + 7 = 25개예요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[36,30,24,25],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수","total":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.","answer":["26"],"explanation":["줄마다 큰 그림과 작은 그림의 개수를 구해요.","16 → 7개, 40 → 4개, 18 → 9개, 33 → 6개.","7 + 4 + 9 + 6 = 26개예요."],"asset":{"type":"picg","only":"table","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[16,40,18,33],"unit":"명","vh":"학생 수","title":"좋아하는 여가 활동별 학생 수","total":false}},{"stem":"이번에는 다른 그림이에요. 이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.","answer":["29"],"explanation":["줄마다 큰 그림과 작은 그림의 개수를 구해요.","8 → 8개, 29 → 11개, 6 → 6개, 4 → 4개.","8 + 11 + 6 + 4 = 29개예요."],"asset":{"type":"picg","only":"table","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[8,29,6,4],"unit":"명","vh":"학생 수","title":"좋아하는 채소별 학생 수","total":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#19','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C5',3,'mc','auto','산불 예방 교육을 사계절 내내 하자고 했어요. 알맞은 까닭은 무엇인가요?',ARRAY['M3-2-u6-X17']::text[],true,'{"seq":19,"concept":"M3-2-u6-C5","difficulty":3,"kind":"mc","stem":"산불 예방 교육을 사계절 내내 하자고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"어느 계절에도 산불이 나서","correct":true},{"t":"여름에는 산불이 하나도 없어서","mis":"M3-2-u6-X17"},{"t":"가을에 산불이 가장 많아서","mis":"M3-2-u6-X17"},{"t":"그림그래프에 계절이 네 개라서","mis":"M3-2-u6-X17"}],"explanation":["그림그래프에서 계절마다 건수를 읽어요 — 봄 286, 여름 37, 가을 124, 겨울 205.","정한 때와 그래프에서 읽은 사실이 맞아야 해요.","알맞은 까닭 — 어느 계절에도 산불이 나서."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"산불 예방 교육을 가을에 하자고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"산불이 많이 나는 겨울과 봄이 오기 전이라서","correct":true},{"t":"가을에 산불이 가장 많이 나서","mis":"M3-2-u6-X17"},{"t":"여름에 산불이 가장 많이 나서","mis":"M3-2-u6-X17"},{"t":"가을의 그림이 가장 커서","mis":"M3-2-u6-X15"}],"explanation":["그림그래프에서 계절마다 건수를 읽어요 — 봄 377, 여름 29, 가을 82, 겨울 268.","정한 때와 그래프에서 읽은 사실이 맞아야 해요.","알맞은 까닭 — 산불이 많이 나는 겨울과 봄이 오기 전이라서."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"산불 예방 교육을 봄에 하자고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"봄에 산불이 가장 많이 나서","correct":true},{"t":"봄에 산불이 가장 적게 나서","mis":"M3-2-u6-X16"},{"t":"여름에 산불이 가장 많이 나서","mis":"M3-2-u6-X17"},{"t":"봄 그림의 색이 진해서","mis":"M3-2-u6-X17"}],"explanation":["그림그래프에서 계절마다 건수를 읽어요 — 봄 312, 여름 46, 가을 95, 겨울 241.","정한 때와 그래프에서 읽은 사실이 맞아야 해요.","알맞은 까닭 — 봄에 산불이 가장 많이 나서."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#20','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C6',3,'sa','auto','표의 한 칸이 지워졌어요. 합계를 보고 박물관에 가고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-2-u6-C6","difficulty":3,"kind":"sa","stem":"표의 한 칸이 지워졌어요. 합계를 보고 박물관에 가고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["24"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들.","66 − 16 − 12 − 14 = 24예요."],"asset":{"type":"picg","only":"table","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[16,null,12,14],"unit":"명","vh":"학생 수","title":"가고 싶어 하는 체험 학습 장소별 학생 수","total":66},"variant_rule":{"alt":[{"stem":"표의 한 칸이 지워졌어요. 합계를 보고 오카리나를 배우고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["35"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들.","95 − 26 − 16 − 18 = 35예요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[26,null,16,18],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수","total":95}},{"stem":"표의 한 칸이 지워졌어요. 합계를 보고 합창부에 가입한 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["29"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들.","107 − 26 − 28 − 24 = 29예요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[null,26,28,24],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수","total":107}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#21','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C7',3,'sa','auto','표를 보고 그림그래프를 그리고 있어요. 비어 있는 달님 모둠 줄에 5장 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"표를 보고 그림그래프를 그리고 있어요. 비어 있는 달님 모둠 줄에 5장 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["표에서 달님 모둠은 13장이에요.","5장 그림 2개와 1장 그림 3개예요.","2개예요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[23,13,26,12],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수","table":true,"blank":[1]},"variant_rule":{"alt":[{"stem":"표를 보고 그림그래프를 그리고 있어요. 비어 있는 건우 줄에 1회 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["표에서 건우는 22회예요.","5회 그림 4개와 1회 그림 2개예요.","2개예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[22,17,16,28],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수","table":true,"blank":[0]}},{"stem":"표를 보고 그림그래프를 그리고 있어요. 비어 있는 건우 줄에 5회 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["표에서 건우는 18회예요.","5회 그림 3개와 1회 그림 3개예요.","3개예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[29,18,27,21],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수","table":true,"blank":[1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#22','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C9',3,'sa','auto','그림의 가로와 세로를 함께 4배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M3-2-u6-C9","difficulty":3,"kind":"sa","stem":"그림의 가로와 세로를 함께 4배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.","answer":["16"],"explanation":["가로로 4개, 세로로 4개만큼 처음 그림이 들어가요.","4 × 4 = 16.","넓이는 16배예요 — 4배로 보이지 않아요."],"variant_rule":{"alt":[{"stem":"그림의 가로와 세로를 함께 3배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.","answer":["9"],"explanation":["가로로 3개, 세로로 3개만큼 처음 그림이 들어가요.","3 × 3 = 9.","넓이는 9배예요 — 3배로 보이지 않아요."],"asset":null},{"stem":"그림의 가로와 세로를 함께 2배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["가로로 2개, 세로로 2개만큼 처음 그림이 들어가요.","2 × 2 = 4.","넓이는 4배예요 — 2배로 보이지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#23','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',4,'sa','auto','㉠은 그림이 6개, ㉡은 그림이 4개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u6-C3","difficulty":4,"kind":"sa","stem":"㉠은 그림이 6개, ㉡은 그림이 4개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.","answer":["7"],"explanation":["그림이 많다고 수가 많은 것은 아니에요.","㉠은 24, ㉡은 31이라 ㉡이 더 많아요.","31 − 24 = 7이에요."],"asset":{"type":"picg","title":"그림의 개수와 수","head":"농장","cols":["㉠","㉡"],"counts":[24,31],"units":[10,1],"icon":"🦆","unit":"마리","vh":"오리의 수"},"variant_rule":{"alt":[{"stem":"㉠은 그림이 6개, ㉡은 그림이 5개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.","answer":["8"],"explanation":["그림이 많다고 수가 많은 것은 아니에요.","㉠은 15, ㉡은 23이라 ㉡이 더 많아요.","23 − 15 = 8이에요."],"asset":{"type":"picg","title":"그림의 개수와 수","head":"종류","cols":["㉠","㉡"],"counts":[15,23],"units":[10,1],"icon":"👟","unit":"켤레","vh":"신발의 수"}},{"stem":"㉠은 그림이 8개, ㉡은 그림이 4개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.","answer":["5"],"explanation":["그림이 많다고 수가 많은 것은 아니에요.","㉠은 17, ㉡은 22라 ㉡이 더 많아요.","22 − 17 = 5예요."],"asset":{"type":"picg","title":"그림의 개수와 수","head":"종류","cols":["㉠","㉡"],"counts":[17,22],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#24','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C4',4,'mc','auto','나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?',ARRAY['M3-2-u6-X01','M3-2-u6-X03']::text[],true,'{"seq":24,"concept":"M3-2-u6-C4","difficulty":4,"kind":"mc","stem":"나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?","options":[{"t":"바람 마을","correct":true},{"t":"햇살 마을","mis":"M3-2-u6-X01"},{"t":"구름 마을","mis":"M3-2-u6-X03"},{"t":"별빛 마을","mis":"M3-2-u6-X01"}],"explanation":["줄마다 100·10·1 그림의 개수를 더해요.","햇살 마을 225 → 9개, 바람 마을 78 → 15개, 구름 마을 355 → 13개, 별빛 마을 315 → 9개.","바람 마을 — 수가 가장 큰 구름 마을과 달라요."],"asset":{"type":"picg","title":"마을별 사과 생산량 — 가: 10·1, 나: 100·10·1","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[225,78,355,315],"units":[10,1],"icon":"🍎","unit":"상자","vh":"생산량","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?","options":[{"t":"떡국","correct":true},{"t":"불고기","mis":"M3-2-u6-X01"},{"t":"비빔밥","mis":"M3-2-u6-X01"},{"t":"잡채","mis":"M3-2-u6-X03"}],"explanation":["줄마다 100·10·1 그림의 개수를 더해요.","떡국 85 → 13개, 불고기 40 → 4개, 비빔밥 254 → 11개, 잡채 314 → 8개.","떡국 — 수가 가장 큰 잡채와 달라요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수 — 가: 10·1, 나: 100·10·1","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[85,40,254,314],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","units2":[100,10,1]}},{"stem":"이번에는 다른 그림이에요. 나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M3-2-u6-X01"},{"t":"여름","mis":"M3-2-u6-X03"},{"t":"가을","mis":"M3-2-u6-X01"}],"explanation":["줄마다 100·10·1 그림의 개수를 더해요.","봄 214 → 7개, 여름 236 → 11개, 가을 130 → 4개, 겨울 79 → 16개.","겨울 — 수가 가장 큰 여름과 달라요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[214,236,130,79],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_b#25','math',3,2,'u6','','g3_2_math_u6_review_b','unit_review','M3-2-u6-C7',4,'essay','teacher','종류별 꽃의 수(장미 23송이, 튤립 18송이, 백합 18송이, 해바라기 7송이)를 큰 그림 5송이, 작은 그림 1송이로 그림그래프에 나타내려고 해요. 장미와 해바라기 줄을 어떻게 그리는지 쓰고, 다 그린 뒤 확인할 것을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u6-C7","difficulty":4,"kind":"essay","stem":"종류별 꽃의 수(장미 23송이, 튤립 18송이, 백합 18송이, 해바라기 7송이)를 큰 그림 5송이, 작은 그림 1송이로 그림그래프에 나타내려고 해요. 장미와 해바라기 줄을 어떻게 그리는지 쓰고, 다 그린 뒤 확인할 것을 써 보세요.","answer_guide":{"answer":"예: 장미 23송이는 5송이 그림 4개와 1송이 그림 3개, 해바라기 7송이는 5송이 그림 1개와 1송이 그림 2개로 그린다. 다 그린 뒤 꽃이 빠짐없이 있는지, 그림이 나타내는 수의 합이 66송이인지 확인한다.","scoring_points":["장미를 5송이 그림 4개·1송이 그림 3개로 썼는가","해바라기를 5송이 그림 1개·1송이 그림 2개로 썼는가","빠진 항목·그림의 합(66송이)을 확인한다고 썼는가"]},"explanation":["23 = 5 × 4 + 3.","7 = 5 × 1 + 2.","합 23 + 18 + 18 + 7 = 66."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#1','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C1',1,'sa','auto','좋아하는 과일별 학생 수 표예요. 사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C1","difficulty":1,"kind":"sa","stem":"좋아하는 과일별 학생 수 표예요. 사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["표의 「사과」 칸 아래 수를 읽어요.","표는 수를 정확히 알 수 있어요.","사과를 좋아하는 학생은 9명이에요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["귤","사과","포도","배"],"counts":[3,9,14,5],"unit":"명","vh":"학생 수","title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"여행 가고 싶어 하는 나라별 학생 수 표예요. 프랑스에 가고 싶어 하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["표의 「프랑스」 칸 아래 수를 읽어요.","표는 수를 정확히 알 수 있어요.","프랑스에 가고 싶어 하는 학생은 15명이에요."],"asset":{"type":"picg","only":"table","head":"나라","cols":["미국","일본","영국","프랑스"],"counts":[3,13,9,15],"unit":"명","vh":"학생 수","title":"여행 가고 싶어 하는 나라별 학생 수"}},{"stem":"좋아하는 채소별 학생 수 표예요. 당근을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["표의 「당근」 칸 아래 수를 읽어요.","표는 수를 정확히 알 수 있어요.","당근을 좋아하는 학생은 9명이에요."],"asset":{"type":"picg","only":"table","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[9,5,15,11],"unit":"명","vh":"학생 수","title":"좋아하는 채소별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#2','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 햇살 농장에서 기르는 오리는 몇 마리인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 햇살 농장에서 기르는 오리는 몇 마리인지 구하세요. 숫자로 쓰세요.","answer":["16"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 10마리, 작은 그림 1마리.","햇살 농장 줄은 10마리 그림 1개와 1마리 그림 6개예요.","햇살 농장에서 기르는 오리는 16마리예요."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["초록 농장","햇살 농장","바람 농장","들꽃 농장"],"counts":[4,16,9,32],"units":[10,1],"icon":"🦆","unit":"마리","vh":"오리의 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 판매한 샌들은 몇 켤레인지 구하세요. 숫자로 쓰세요.","answer":["5"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 10켤레, 작은 그림 1켤레.","샌들 줄은 1켤레 그림 5개예요.","판매한 샌들은 5켤레예요."],"asset":{"type":"picg","title":"종류별 판매한 신발의 수","head":"종류","cols":["운동화","구두","샌들","장화"],"counts":[20,43,5,45],"units":[10,1],"icon":"👟","unit":"켤레","vh":"신발의 수"}},{"stem":"그림그래프를 보고 판매한 꿀도넛은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["11"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 10개, 작은 그림 1개.","꿀도넛 줄은 10개 그림 1개와 1개 그림 1개예요.","판매한 꿀도넛은 11개예요."],"asset":{"type":"picg","title":"종류별 판매한 도넛의 수","head":"종류","cols":["크림도넛","초코도넛","딸기도넛","꿀도넛"],"counts":[40,29,33,11],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#3','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C4',1,'sa','auto','판매한 초코도넛 37개를 그림그래프로 나타내요. 큰 그림이 10개, 작은 그림이 1개를 나타낼 때 10개 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C4","difficulty":1,"kind":"sa","stem":"판매한 초코도넛 37개를 그림그래프로 나타내요. 큰 그림이 10개, 작은 그림이 1개를 나타낼 때 10개 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 그림부터 그려요.","37개는 10개 그림 3개와 1개 그림 7개예요.","10개 그림은 3개예요."],"variant_rule":{"alt":[{"stem":"3반에서 빌린 책 24권을 그림그래프로 나타내요. 큰 그림이 10권, 작은 그림이 1권을 나타낼 때 10권 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","24권은 10권 그림 2개와 1권 그림 4개예요.","10권 그림은 2개예요."],"asset":null},{"stem":"별빛 마을에 심은 나무 37그루를 그림그래프로 나타내요. 큰 그림이 10그루, 작은 그림이 1그루를 나타낼 때 10그루 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 그림부터 그려요.","37그루는 10그루 그림 3개와 1그루 그림 7개예요.","10그루 그림은 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#4','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C4',1,'mc','auto','그림그래프로 나타내는 네 걸음 가운데 ③는 무엇인가요?  ① 알맞은 제목 → ② 그림과 단위 → ③ ? → ④ 그림',ARRAY['M3-2-u6-X07']::text[],true,'{"seq":4,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"그림그래프로 나타내는 네 걸음 가운데 ③는 무엇인가요?  ① 알맞은 제목 → ② 그림과 단위 → ③ ? → ④ 그림","options":[{"t":"조사한 항목을 빠짐없이 써요","correct":true},{"t":"알맞은 제목을 써요","mis":"M3-2-u6-X07"},{"t":"그림과 단위를 정해요","mis":"M3-2-u6-X07"},{"t":"합계를 구해요","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지를 갖추어 나타내요.","③ 걸음은 「조사한 항목을 빠짐없이 써요」예요.","순서는 꼭 지키지 않아도 되지만 네 가지는 빠짐없이 있어야 해요."],"variant_rule":{"alt":[{"stem":"그림그래프로 나타내는 네 걸음 가운데 ②는 무엇인가요?  ① 알맞은 제목 → ② ? → ③ 항목 → ④ 그림","options":[{"t":"그림과 단위를 정해요","correct":true},{"t":"알맞은 제목을 써요","mis":"M3-2-u6-X07"},{"t":"조사한 항목을 빠짐없이 써요","mis":"M3-2-u6-X07"},{"t":"합계를 구해요","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지를 갖추어 나타내요.","② 걸음은 「그림과 단위를 정해요」예요.","순서는 꼭 지키지 않아도 되지만 네 가지는 빠짐없이 있어야 해요."],"asset":null},{"stem":"그림그래프로 나타내는 네 걸음 가운데 ④는 무엇인가요?  ① 알맞은 제목 → ② 그림과 단위 → ③ 항목 → ④ ?","options":[{"t":"수에 맞게 그림으로 나타내요","correct":true},{"t":"알맞은 제목을 써요","mis":"M3-2-u6-X07"},{"t":"그림과 단위를 정해요","mis":"M3-2-u6-X07"},{"t":"합계를 구해요","mis":"M3-2-u6-X07"}],"explanation":["그림그래프는 제목·그림과 단위·항목·그림 네 가지를 갖추어 나타내요.","④ 걸음은 「수에 맞게 그림으로 나타내요」예요.","순서는 꼭 지키지 않아도 되지만 네 가지는 빠짐없이 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#5','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C6',1,'mc','auto','「종이 띠 판에 색 동그라미 스티커를 붙여요.」라고 했어요. 어떤 조사 방법인가요?',ARRAY['M3-2-u6-X11']::text[],true,'{"seq":5,"concept":"M3-2-u6-C6","difficulty":1,"kind":"mc","stem":"「종이 띠 판에 색 동그라미 스티커를 붙여요.」라고 했어요. 어떤 조사 방법인가요?","options":[{"t":"붙임딱지 붙이기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["조사 방법에는 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기가 있어요.","「종이 띠 판에 색 동그라미 스티커를 붙여요.」 하는 일은 「붙임딱지 붙이기」의 모습이에요.","답은 「붙임딱지 붙이기」예요."],"variant_rule":{"alt":[{"stem":"「상자에 종이를 넣어요.」라고 했어요. 어떤 조사 방법인가요?","options":[{"t":"투표하기","correct":true},{"t":"손 들기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["조사 방법에는 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기가 있어요.","「상자에 종이를 넣어요.」 하는 일은 「투표하기」의 모습이에요.","답은 「투표하기」예요."],"asset":null},{"stem":"「좋아하는 것에 손을 들어 주세요.」라고 했어요. 어떤 조사 방법인가요?","options":[{"t":"손 들기","correct":true},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["조사 방법에는 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기가 있어요.","「좋아하는 것에 손을 들어 주세요.」 하는 일은 「손 들기」의 모습이에요.","답은 「손 들기」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#6','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C7',1,'sa','auto','달님 모둠이 모은 붙임딱지 23장을 그림그래프로 나타내요. 큰 그림이 5장, 작은 그림이 1장을 나타낼 때 5장 그림은 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u6-C7","difficulty":1,"kind":"sa","stem":"달님 모둠이 모은 붙임딱지 23장을 그림그래프로 나타내요. 큰 그림이 5장, 작은 그림이 1장을 나타낼 때 5장 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 그림부터 그려요.","23장은 5장 그림 4개와 1장 그림 3개예요.","5장 그림은 4개예요."],"variant_rule":{"alt":[{"stem":"은비가 운동한 횟수 12회를 그림그래프로 나타내요. 큰 그림이 5회, 작은 그림이 1회를 나타낼 때 5회 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 그림부터 그려요.","12회는 5회 그림 2개와 1회 그림 2개예요.","5회 그림은 2개예요."],"asset":null},{"stem":"지유가 훌라후프를 한 횟수 16회를 그림그래프로 나타내요. 큰 그림이 5회, 작은 그림이 1회를 나타낼 때 5회 그림은 몇 개 그리나요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 그림부터 그려요.","16회는 5회 그림 3개와 1회 그림 1개예요.","5회 그림은 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#7','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C8',1,'sa','auto','나 그림그래프에서 월요일에 도서관을 찾은 사람 188명을 나타낼 때 100명 그림은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u6-C8","difficulty":1,"kind":"sa","stem":"나 그림그래프에서 월요일에 도서관을 찾은 사람 188명을 나타낼 때 100명 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나는 100명·10명·1명 세 가지 그림이에요.","188명은 100명 그림 1개, 10명 그림 8개와 1명 그림 8개예요.","100명 그림은 1개예요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수 — 가: 10·1, 나: 100·10·1","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[188,244,371,143],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"나 그림그래프에서 구름 마을의 사과 생산량 235상자를 나타낼 때 100상자 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나는 100상자·10상자·1상자 세 가지 그림이에요.","235상자는 100상자 그림 2개, 10상자 그림 3개와 1상자 그림 5개예요.","100상자 그림은 2개예요."],"asset":{"type":"picg","title":"마을별 사과 생산량 — 가: 10·1, 나: 100·10·1","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[268,249,235,194],"units":[10,1],"icon":"🍎","unit":"상자","vh":"생산량","units2":[100,10,1]}},{"stem":"나 그림그래프에서 떡국을 좋아하는 학생 246명을 나타낼 때 100명 그림은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나는 100명·10명·1명 세 가지 그림이에요.","246명은 100명 그림 2개, 10명 그림 4개와 1명 그림 6개예요.","100명 그림은 2개예요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수 — 가: 10·1, 나: 100·10·1","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[246,336,157,146],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#8','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C8',1,'mc','auto','가와 나 그림그래프의 같은 점은 무엇인가요?',ARRAY['M3-2-u6-X14']::text[],true,'{"seq":8,"concept":"M3-2-u6-C8","difficulty":1,"kind":"mc","stem":"가와 나 그림그래프의 같은 점은 무엇인가요?","options":[{"t":"그림이 같아요","correct":true},{"t":"단위의 종류가 같아요","mis":"M3-2-u6-X14"},{"t":"그림의 수가 같아요","mis":"M3-2-u6-X14"},{"t":"같은 점이 없어요","mis":"M3-2-u6-X14"}],"explanation":["두 그림그래프는 같은 산불 자료를 나타냈어요.","쓴 그림(🔥)은 같고, 가는 10·1, 나는 100·10·1로 단위의 종류가 달라요.","답은 「그림이 같아요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"가와 나 그림그래프에서 같은 것은 무엇인가요?","options":[{"t":"나타낸 건수(자료)가 같아요","correct":true},{"t":"그림의 개수가 같아요","mis":"M3-2-u6-X14"},{"t":"단위의 종류가 같아요","mis":"M3-2-u6-X14"},{"t":"그림의 크기 종류가 같아요","mis":"M3-2-u6-X14"}],"explanation":["두 그림그래프는 같은 산불 자료를 나타냈어요.","쓴 그림(🔥)은 같고, 가는 10·1, 나는 100·10·1로 단위의 종류가 달라요.","답은 「나타낸 건수(자료)가 같아요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"가와 나 그림그래프에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"같은 자료를 그림의 단위만 다르게 나타냈어요","correct":true},{"t":"서로 다른 자료를 나타냈어요","mis":"M3-2-u6-X14"},{"t":"가가 나보다 건수가 많아요","mis":"M3-2-u6-X14"},{"t":"나가 가보다 건수가 많아요","mis":"M3-2-u6-X14"}],"explanation":["두 그림그래프는 같은 산불 자료를 나타냈어요.","쓴 그림(🔥)은 같고, 가는 10·1, 나는 100·10·1로 단위의 종류가 달라요.","답은 「같은 자료를 그림의 단위만 다르게 나타냈어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#9','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C1',2,'sa','auto','좋아하는 과일별 학생 수 표예요. 합계가 30명일 때 사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u6-C1","difficulty":2,"kind":"sa","stem":"좋아하는 과일별 학생 수 표예요. 합계가 30명일 때 사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들이에요.","30 − 6 − 8 = 16명이에요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["귤","사과","포도"],"counts":[6,null,8],"unit":"명","vh":"학생 수","title":"좋아하는 과일별 학생 수","total":30},"variant_rule":{"alt":[{"stem":"좋아하는 계절별 학생 수 표예요. 합계가 28명일 때 겨울을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들이에요.","28 − 6 − 7 − 5 = 10명이에요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[6,7,5,null],"unit":"명","vh":"학생 수","title":"좋아하는 계절별 학생 수","total":28}},{"stem":"좋아하는 여가 활동별 학생 수 표예요. 합계가 25명일 때 배드민턴을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들이에요.","25 − 5 − 8 = 12명이에요."],"asset":{"type":"picg","only":"table","head":"여가 활동","cols":["배드민턴","산책","자전거 타기"],"counts":[null,5,8],"unit":"명","vh":"학생 수","title":"좋아하는 여가 활동별 학생 수","total":25}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#10','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',2,'mc','auto','그림그래프에서 빈 병을 가장 많이 모은 반은 어느 반인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16','M3-2-u6-X03']::text[],true,'{"seq":10,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"그림그래프에서 빈 병을 가장 많이 모은 반은 어느 반인가요?","options":[{"t":"2반","correct":true},{"t":"1반","mis":"M3-2-u6-X04"},{"t":"3반","mis":"M3-2-u6-X16"},{"t":"4반","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 1반 18, 2반 32, 3반 7, 4반 30.","가장 많은 것은 「2반」이에요."],"asset":{"type":"picg","title":"반별 모은 빈 병의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[18,32,7,30],"units":[10,1],"icon":"🍾","unit":"개","vh":"빈 병의 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 가장 많은 학생이 배우고 싶어 하는 악기는 무엇인가요?","options":[{"t":"가야금","correct":true},{"t":"오카리나","mis":"M3-2-u6-X16"},{"t":"우쿨렐레","mis":"M3-2-u6-X03"},{"t":"플루트","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 가야금 42, 오카리나 6, 우쿨렐레 8, 플루트 18.","가장 많은 것은 「가야금」이에요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[42,6,8,18],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"그림그래프에서 가장 많은 학생이 좋아하는 여가 활동은 무엇인가요?","options":[{"t":"줄넘기","correct":true},{"t":"배드민턴","mis":"M3-2-u6-X04"},{"t":"산책","mis":"M3-2-u6-X03"},{"t":"자전거 타기","mis":"M3-2-u6-X16"}],"explanation":["큰 그림이 가장 많은 줄부터 봐요.","그림을 모두 센 개수가 아니라 나타내는 수로 견줘요 — 배드민턴 37, 산책 34, 자전거 타기 18, 줄넘기 44.","가장 많은 것은 「줄넘기」예요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"여가 활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[37,34,18,44],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EX