INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#12','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C4',2,'mc','auto','2반에서 빌린 책 24권을 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":12,"concept":"M3-2-u6-C4","difficulty":2,"kind":"mc","stem":"2반에서 빌린 책 24권을 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10권 그림 2개와 1권 그림 4개","correct":true},{"t":"10권 그림 4개와 1권 그림 2개","mis":"M3-2-u6-X05"},{"t":"10권 그림 2개","mis":"M3-2-u6-X06"},{"t":"10권 그림 3개와 1권 그림 4개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 10권이에요.","24권은 큰 그림 2개, 남은 4권은 작은 그림 4개예요.","답은 「10권 그림 2개와 1권 그림 4개」예요."],"variant_rule":{"alt":[{"stem":"구름 마을에 심은 나무 48그루를 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10그루 그림 4개와 1그루 그림 8개","correct":true},{"t":"10그루 그림 8개와 1그루 그림 4개","mis":"M3-2-u6-X05"},{"t":"10그루 그림 4개","mis":"M3-2-u6-X06"},{"t":"10그루 그림 5개와 1그루 그림 8개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 10그루예요.","48그루는 큰 그림 4개, 남은 8그루는 작은 그림 8개예요.","답은 「10그루 그림 4개와 1그루 그림 8개」예요."],"asset":null},{"stem":"4반에서 모은 빈 병 35개를 그림그래프로 나타내려고 해요. 큰 그림부터 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10개 그림 3개와 1개 그림 5개","correct":true},{"t":"10개 그림 5개와 1개 그림 3개","mis":"M3-2-u6-X05"},{"t":"10개 그림 3개","mis":"M3-2-u6-X06"},{"t":"10개 그림 4개와 1개 그림 5개","mis":"M3-2-u6-X02"}],"explanation":["큰 그림이 10개예요.","35개는 큰 그림 3개, 남은 5개는 작은 그림 5개예요.","답은 「10개 그림 3개와 1개 그림 5개」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#13','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C5',2,'mc','auto','가장 적은 학생이 좋아하는 채소를 더 맛있게 만들어 보려고 해요. 무엇을 고르면 될까요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16']::text[],true,'{"seq":13,"concept":"M3-2-u6-C5","difficulty":2,"kind":"mc","stem":"가장 적은 학생이 좋아하는 채소를 더 맛있게 만들어 보려고 해요. 무엇을 고르면 될까요?","options":[{"t":"시금치","correct":true},{"t":"당근","mis":"M3-2-u6-X04"},{"t":"오이","mis":"M3-2-u6-X16"},{"t":"콩나물","mis":"M3-2-u6-X04"}],"explanation":["그림그래프에서 줄마다 수를 읽어요 — 당근 39, 시금치 15, 오이 48, 콩나물 40.","가장 적은 것을 찾아요.","「시금치」예요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[39,15,48,40],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"가장 많은 학생이 좋아하는 과일을 급식에 넣으려고 해요. 무엇을 넣으면 될까요?","options":[{"t":"사과","correct":true},{"t":"귤","mis":"M3-2-u6-X16"},{"t":"포도","mis":"M3-2-u6-X04"},{"t":"배","mis":"M3-2-u6-X04"}],"explanation":["그림그래프에서 줄마다 수를 읽어요 — 귤 18, 사과 38, 포도 35, 배 29.","가장 많은 것을 찾아요.","「사과」예요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["귤","사과","포도","배"],"counts":[18,38,35,29],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"가장 적은 학생이 좋아하는 전통 음식을 더 맛있게 만들어 보려고 해요. 무엇을 고르면 될까요?","options":[{"t":"잡채","correct":true},{"t":"떡국","mis":"M3-2-u6-X04"},{"t":"불고기","mis":"M3-2-u6-X04"},{"t":"비빔밥","mis":"M3-2-u6-X16"}],"explanation":["그림그래프에서 줄마다 수를 읽어요 — 떡국 274, 불고기 254, 비빔밥 357, 잡채 67.","가장 적은 것을 찾아요.","「잡채」예요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[274,254,357,67],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#14','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C6',2,'mc','auto','우리 반이 직접 조사하기 어려운 주제는 무엇인가요?',ARRAY['M3-2-u6-X10']::text[],true,'{"seq":14,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"우리 반이 직접 조사하기 어려운 주제는 무엇인가요?","options":[{"t":"우리나라 모든 어린이가 좋아하는 과일","correct":true},{"t":"우리 반이 좋아하는 운동","mis":"M3-2-u6-X10"},{"t":"우리 모둠이 좋아하는 색깔","mis":"M3-2-u6-X10"},{"t":"우리 반이 배우고 싶은 악기","mis":"M3-2-u6-X10"}],"explanation":["주제는 우리가 직접 모을 수 있어야 해요.","그리고 무엇을 조사하는지 분명해야 해요.","답은 「우리나라 모든 어린이가 좋아하는 과일」이에요."],"variant_rule":{"alt":[{"stem":"우리 학년이 직접 자료를 모을 수 있는 주제는 무엇인가요?","options":[{"t":"우리 학년이 좋아하는 급식 반찬","correct":true},{"t":"세계 모든 사람이 좋아하는 동물","mis":"M3-2-u6-X10"},{"t":"우리나라 어른들이 가장 많이 타는 차","mis":"M3-2-u6-X10"},{"t":"지구에 사는 새의 수","mis":"M3-2-u6-X10"}],"explanation":["주제는 우리가 직접 모을 수 있어야 해요.","그리고 무엇을 조사하는지 분명해야 해요.","답은 「우리 학년이 좋아하는 급식 반찬」이에요."],"asset":null},{"stem":"무엇을 조사하는지 분명한 주제는 무엇인가요?","options":[{"t":"우리 반이 한 달 동안 읽은 책의 수","correct":true},{"t":"우리 반 친구들의 이것저것","mis":"M3-2-u6-X10"},{"t":"재미있는 것","mis":"M3-2-u6-X10"},{"t":"여러 가지 좋은 것","mis":"M3-2-u6-X10"}],"explanation":["주제는 우리가 직접 모을 수 있어야 해요.","그리고 무엇을 조사하는지 분명해야 해요.","답은 「우리 반이 한 달 동안 읽은 책의 수」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#15','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C7',2,'mc','auto','그림그래프를 다 그린 뒤 무엇을 확인하면 좋을까요?',ARRAY['M3-2-u6-X13','M3-2-u6-X07','M3-2-u6-X06']::text[],true,'{"seq":15,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"그림그래프를 다 그린 뒤 무엇을 확인하면 좋을까요?","options":[{"t":"그림이 나타내는 수의 합이 표의 합계와 같은지","correct":true},{"t":"그림이 모두 같은 색인지","mis":"M3-2-u6-X13"},{"t":"제목이 가장 긴지","mis":"M3-2-u6-X07"},{"t":"그림이 모두 작은지","mis":"M3-2-u6-X06"}],"explanation":["다 그린 뒤에는 빠짐과 틀림을 확인해요.","항목은 표와, 그림의 합은 표의 합계와 견줘요.","답은 「그림이 나타내는 수의 합이 표의 합계와 같은지」예요."],"variant_rule":{"alt":[{"stem":"그림그래프에 빠진 항목이 없는지 알아보려면 무엇과 견주면 되나요?","options":[{"t":"표의 항목","correct":true},{"t":"그림의 크기","mis":"M3-2-u6-X15"},{"t":"그림의 색깔","mis":"M3-2-u6-X13"},{"t":"제목의 글자 수","mis":"M3-2-u6-X07"}],"explanation":["다 그린 뒤에는 빠짐과 틀림을 확인해요.","항목은 표와, 그림의 합은 표의 합계와 견줘요.","답은 「표의 항목」이에요."],"asset":null},{"stem":"그림을 덜 그리거나 더 그린 곳이 있는지 알아보는 방법은 무엇인가요?","options":[{"t":"그림이 나타내는 수를 모두 더해 표의 합계와 견주어요","correct":true},{"t":"그림의 개수만 세어 봐요","mis":"M3-2-u6-X01"},{"t":"가장 큰 그림만 세어 봐요","mis":"M3-2-u6-X04"},{"t":"제목을 다시 읽어요","mis":"M3-2-u6-X07"}],"explanation":["다 그린 뒤에는 빠짐과 틀림을 확인해요.","항목은 표와, 그림의 합은 표의 합계와 견줘요.","답은 「그림이 나타내는 수를 모두 더해 표의 합계와 견주어요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#16','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C8',2,'mc','auto','단위의 종류가 늘어나면 편리한 점은 무엇인가요?',ARRAY['M3-2-u6-X14']::text[],true,'{"seq":16,"concept":"M3-2-u6-C8","difficulty":2,"kind":"mc","stem":"단위의 종류가 늘어나면 편리한 점은 무엇인가요?","options":[{"t":"큰 수를 적은 그림으로 나타낼 수 있어요","correct":true},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"그림의 크기를 구분하기 쉬워요","mis":"M3-2-u6-X14"},{"t":"합계가 커져요","mis":"M3-2-u6-X14"}],"explanation":["단위의 종류가 늘면 큰 수를 큰 그림 몇 개로 줄여 나타낼 수 있어요.","그래서 그림 개수가 줄어요.","답은 「큰 수를 적은 그림으로 나타낼 수 있어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"나 그림그래프처럼 100건 그림을 하나 더 두면 좋은 점은 무엇인가요?","options":[{"t":"그림을 적게 그려도 돼요","correct":true},{"t":"그림을 크게 그리기 쉬워요","mis":"M3-2-u6-X14"},{"t":"건수가 늘어나요","mis":"M3-2-u6-X14"},{"t":"제목을 쓰지 않아도 돼요","mis":"M3-2-u6-X07"}],"explanation":["봄 377건 — 가는 10건 그림 37개와 1건 그림 7개, 나는 100건 그림 3개와 10건 그림 7개와 1건 그림 7개예요.","그래서 그림 개수가 줄어요.","답은 「그림을 적게 그려도 돼요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"봄 377건을 나타낼 때 나가 가보다 좋은 점은 무엇인가요?","options":[{"t":"그림 개수가 훨씬 적어요","correct":true},{"t":"그림 개수가 훨씬 많아요","mis":"M3-2-u6-X14"},{"t":"건수가 더 정확해져요","mis":"M3-2-u6-X14"},{"t":"그림을 구분하기 쉬워요","mis":"M3-2-u6-X14"}],"explanation":["단위의 종류가 늘면 큰 수를 큰 그림 몇 개로 줄여 나타낼 수 있어요.","그래서 그림 개수가 줄어요.","답은 「그림 개수가 훨씬 적어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#17','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',3,'mc','auto','좋아하는 채소별 학생 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 콩나물은 5명이에요.  ㉡ 가장 적은 것은 당근이에요.  ㉢ 시금치는 당근보다 33명 더 많아요.',ARRAY['M3-2-u6-X16','M3-2-u6-X01']::text[],true,'{"seq":17,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"좋아하는 채소별 학생 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 콩나물은 5명이에요.  ㉡ 가장 적은 것은 당근이에요.  ㉢ 시금치는 당근보다 33명 더 많아요.","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M3-2-u6-X16"},{"t":"㉢","mis":"M3-2-u6-X16"},{"t":"모두 옳아요","mis":"M3-2-u6-X01"}],"explanation":["줄마다 수를 읽어요 — 당근 13, 시금치 46, 오이 15, 콩나물 23.","말 하나하나를 그래프와 맞춰 봐요.","옳지 않은 것은 ㉠이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[13,46,15,23],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"가고 싶어 하는 체험 학습 장소별 학생 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 과학관은 19명이에요.  ㉡ 가장 적은 것은 동물원이에요.  ㉢ 놀이공원은 박물관보다 63명 더 많아요.","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u6-X16"},{"t":"㉡","mis":"M3-2-u6-X16"},{"t":"모두 옳아요","mis":"M3-2-u6-X08"}],"explanation":["줄마다 수를 읽어요 — 놀이공원 34, 박물관 29, 과학관 19, 동물원 8.","말 하나하나를 그래프와 맞춰 봐요.","옳지 않은 것은 ㉢이에요."],"asset":{"type":"picg","title":"가고 싶어 하는 체험 학습 장소별 학생 수","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[34,29,19,8],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"가입한 동아리별 학생 수 그림그래프예요. 옳지 않은 것을 고르세요.  ㉠ 축구부는 24명이에요.  ㉡ 가장 적은 것은 미술부예요.  ㉢ 합창부는 미술부보다 46명 더 많아요.","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u6-X16"},{"t":"㉡","mis":"M3-2-u6-X16"},{"t":"모두 옳아요","mis":"M3-2-u6-X08"}],"explanation":["줄마다 수를 읽어요 — 합창부 29, 로봇부 41, 축구부 24, 미술부 17.","말 하나하나를 그래프와 맞춰 봐요.","옳지 않은 것은 ㉢이에요."],"asset":{"type":"picg","title":"가입한 동아리별 학생 수","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[29,41,24,17],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#18','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C4',3,'mc','auto','표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?',ARRAY['M3-2-u6-X13']::text[],true,'{"seq":18,"concept":"M3-2-u6-C4","difficulty":3,"kind":"mc","stem":"표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"박물관","correct":true},{"t":"놀이공원","mis":"M3-2-u6-X13"},{"t":"과학관","mis":"M3-2-u6-X13"},{"t":"동물원","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","박물관 줄은 10명 그림 2개와 1명 그림 5개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「박물관」이에요."],"asset":{"type":"picg","title":"가고 싶어 하는 체험 학습 장소별 학생 수","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[37,25,17,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","table":true,"pieces":[[3,7],[5,2],[1,7],[1,5]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"미술부","correct":true},{"t":"합창부","mis":"M3-2-u6-X13"},{"t":"로봇부","mis":"M3-2-u6-X13"},{"t":"축구부","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","미술부 줄은 10명 그림 1개와 1명 그림 4개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「미술부」예요."],"asset":{"type":"picg","title":"가입한 동아리별 학생 수","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[19,43,7,14],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","table":true,"pieces":[[1,9],[4,3],[0,7],[4,1]]}},{"stem":"이번에는 다른 그림이에요. 표를 보고 그림그래프로 나타냈어요. 잘못 나타낸 줄은 어느 것인가요?","options":[{"t":"윷놀이","correct":true},{"t":"투호","mis":"M3-2-u6-X13"},{"t":"연날리기","mis":"M3-2-u6-X13"},{"t":"제기차기","mis":"M3-2-u6-X13"}],"explanation":["줄마다 그림이 나타내는 수를 표의 수와 맞춰 봐요.","윷놀이 줄은 10명 그림 1개와 1명 그림 6개를 그려야 하는데 개수를 바꾸어 그렸어요.","잘못 나타낸 줄은 「윷놀이」예요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 학생 수","head":"민속놀이","cols":["윷놀이","투호","연날리기","제기차기"],"counts":[16,21,14,27],"units":[10,1],"icon":"🙂","unit":"명