INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#19','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C5',3,'mc','auto','그림그래프를 보고 「떡국을 급식에 넣어요.」라고 정했어요. 알맞은 까닭은 무엇인가요?',ARRAY['M3-2-u6-X17']::text[],true,'{"seq":19,"concept":"M3-2-u6-C5","difficulty":3,"kind":"mc","stem":"그림그래프를 보고 「떡국을 급식에 넣어요.」라고 정했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"가장 많은 학생이 좋아하기 때문이에요","correct":true},{"t":"가장 적은 학생이 좋아하기 때문이에요","mis":"M3-2-u6-X17"},{"t":"그림이 가장 예쁘기 때문이에요","mis":"M3-2-u6-X17"},{"t":"표의 맨 앞에 있기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["정한 일과 그림그래프에서 읽은 사실이 맞아야 해요.","줄마다 수 — 떡국 130, 불고기 82, 비빔밥 64, 잡채 51.","알맞은 까닭 — 가장 많은 학생이 좋아하기 때문이에요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","잡채"],"counts":[130,82,64,51],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 「식혜를 더 맛있게 만들어 봐요.」라고 정했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"좋아하는 학생이 가장 적어서 더 많은 학생이 좋아하게 하려고요","correct":true},{"t":"가장 많은 학생이 좋아하기 때문이에요","mis":"M3-2-u6-X17"},{"t":"그림을 가장 많이 그렸기 때문이에요","mis":"M3-2-u6-X04"},{"t":"이름이 가장 짧기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["정한 일과 그림그래프에서 읽은 사실이 맞아야 해요.","줄마다 수 — 떡국 124, 불고기 95, 비빔밥 71, 식혜 38.","알맞은 까닭 — 좋아하는 학생이 가장 적어서 더 많은 학생이 좋아하게 하려고요."],"asset":{"type":"picg","title":"좋아하는 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜"],"counts":[124,95,71,38],"units":[100,10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"그림그래프를 보고 「오이 반찬을 자주 내요.」라고 정했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"좋아하는 학생이 가장 많기 때문이에요","correct":true},{"t":"좋아하는 학생이 가장 적기 때문이에요","mis":"M3-2-u6-X17"},{"t":"작은 그림이 가장 많기 때문이에요","mis":"M3-2-u6-X04"},{"t":"채소 이름이 두 글자이기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["정한 일과 그림그래프에서 읽은 사실이 맞아야 해요.","줄마다 수 — 당근 18, 시금치 10, 오이 24, 콩나물 15.","알맞은 까닭 — 좋아하는 학생이 가장 많기 때문이에요."],"asset":{"type":"picg","title":"좋아하는 채소별 학생 수","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[18,10,24,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#20','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C6',3,'mc','auto','우리 반 30명이 모두 하나씩 골랐는데 표의 합계가 29명이에요. 가장 먼저 할 일은 무엇인가요?',ARRAY['M3-2-u6-X13','M3-2-u6-X10']::text[],true,'{"seq":20,"concept":"M3-2-u6-C6","difficulty":3,"kind":"mc","stem":"우리 반 30명이 모두 하나씩 골랐는데 표의 합계가 29명이에요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"빠뜨린 자료가 없는지 다시 세어 봐요","correct":true},{"t":"합계를 30명으로 고쳐 써요","mis":"M3-2-u6-X13"},{"t":"그대로 그림그래프를 그려요","mis":"M3-2-u6-X13"},{"t":"항목을 하나 더 만들어요","mis":"M3-2-u6-X10"}],"explanation":["합계는 조사한 사람 수와 같아야 해요.","30명과 29명이 달라 빠뜨린 자료가 있어요.","다시 세어 확인해요."],"variant_rule":{"alt":[{"stem":"우리 반 28명이 모두 하나씩 골랐는데 표의 합계가 26명이에요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"빠뜨린 자료가 없는지 다시 세어 봐요","correct":true},{"t":"합계를 28명으로 고쳐 써요","mis":"M3-2-u6-X13"},{"t":"그대로 그림그래프를 그려요","mis":"M3-2-u6-X13"},{"t":"항목을 하나 더 만들어요","mis":"M3-2-u6-X10"}],"explanation":["합계는 조사한 사람 수와 같아야 해요.","28명과 26명이 달라 빠뜨린 자료가 있어요.","다시 세어 확인해요."],"asset":null},{"stem":"우리 반 26명이 모두 하나씩 골랐는데 표의 합계가 25명이에요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"빠뜨린 자료가 없는지 다시 세어 봐요","correct":true},{"t":"합계를 26명으로 고쳐 써요","mis":"M3-2-u6-X13"},{"t":"그대로 그림그래프를 그려요","mis":"M3-2-u6-X13"},{"t":"항목을 하나 더 만들어요","mis":"M3-2-u6-X10"}],"explanation":["합계는 조사한 사람 수와 같아야 해요.","26명과 25명이 달라 빠뜨린 자료가 있어요.","다시 세어 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#21','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C7',3,'sa','auto','표를 보고 그린 그림그래프에서 달님 모둠 줄을 덜 그렸어요. 1장 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"표를 보고 그린 그림그래프에서 달님 모둠 줄을 덜 그렸어요. 1장 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["표에서 달님 모둠은 8장이에요.","그림은 6장만 나타내고 있어요.","8 − 6 = 2개 더 그려요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[3,8,7,27],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수","table":true,"pieces":[[0,3],[1,1],[1,2],[5,2]]},"variant_rule":{"alt":[{"stem":"표를 보고 그린 그림그래프에서 건우 줄을 덜 그렸어요. 1회 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["표에서 건우는 9회예요.","그림은 6회만 나타내고 있어요.","9 − 6 = 3개 더 그려요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[9,4,3,18],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수","table":true,"pieces":[[1,1],[0,4],[0,3],[3,3]]}},{"stem":"표를 보고 그린 그림그래프에서 은비 줄을 덜 그렸어요. 1회 그림을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["표에서 은비는 7회예요.","그림은 5회만 나타내고 있어요.","7 − 5 = 2개 더 그려요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[7,8,27,3],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수","table":true,"pieces":[[1,0],[1,3],[5,2],[0,3]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#22','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C9',3,'mc','auto','한 그림그래프에서 어떤 줄의 그림만 다른 줄보다 훨씬 크게 그렸어요. 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u6-X15']::text[],true,'{"seq":22,"concept":"M3-2-u6-C9","difficulty":3,"kind":"mc","stem":"한 그림그래프에서 어떤 줄의 그림만 다른 줄보다 훨씬 크게 그렸어요. 바르게 말한 것은 무엇인가요?","options":[{"t":"실제보다 많아 보여 잘못 읽을 수 있어요","correct":true},{"t":"그 줄의 수가 가장 많아요","mis":"M3-2-u6-X15"},{"t":"크게 그리면 수가 정확해져요","mis":"M3-2-u6-X15"},{"t":"그림의 크기는 아무 상관이 없어요","mis":"M3-2-u6-X15"}],"explanation":["그림을 크게 그리면 넓이가 커져 실제보다 많아 보여요.","같은 수를 나타내는 그림은 크기가 같아야 해요.","답은 「실제보다 많아 보여 잘못 읽을 수 있어요」예요."],"variant_rule":{"alt":[{"stem":"그림그래프에서 그림의 크기를 정할 때 알맞은 것은 무엇인가요?","options":[{"t":"같은 수를 나타내는 그림은 같은 크기로 그려요","correct":true},{"t":"수가 많은 줄은 그림을 더 크게 그려요","mis":"M3-2-u6-X15"},{"t":"마음에 드는 줄의 그림을 크게 그려요","mis":"M3-2-u6-X15"},{"t":"그림 크기는 아무렇게나 해요","mis":"M3-2-u6-X15"}],"explanation":["그림을 크게 그리면 넓이가 커져 실제보다 많아 보여요.","같은 수를 나타내는 그림은 크기가 같아야 해요.","답은 「같은 수를 나타내는 그림은 같은 크기로 그려요」예요."],"asset":null},{"stem":"「축구를 좋아하는 학생은 그림이 가장 커 보이니 가장 많아요.」라는 말에 대해 알맞은 것은 무엇인가요?","options":[{"t":"그림의 크기가 아니라 그림이 나타내는 수로 견주어야 해요","correct":true},{"t":"맞는 말이에요","mis":"M3-2-u6-X15"},{"t":"그림이 크면 언제나 수가 많아요","mis":"M3-2-u6-X15"},{"t":"그림이 작을수록 수가 많아요","mis":"M3-2-u6-X15"}],"explanation":["그림을 크게 그리면 넓이가 커져 실제보다 많아 보여요.","같은 수를 나타내는 그림은 크기가 같아야 해요.","답은 「그림의 크기가 아니라 그림이 나타내는 수로 견주어야 해요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#23','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',4,'sa','auto','오리의 수의 합계는 132마리예요. 그림그래프에서 햇살 농장 줄이 지워졌어요. 햇살 농장에서 기르는 오리는 몇 마리인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u6-C3","difficulty":4,"kind":"sa","stem":"오리의 수의 합계는 132마리예요. 그림그래프에서 햇살 농장 줄이 지워졌어요. 햇살 농장에서 기르는 오리는 몇 마리인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["보이는 줄의 수를 읽어요 — 32, 41, 21.","모르는 수 = 합계 − 아는 수들이에요.","132 − 32 − 41 − 21 = 38마리예요."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["초록 농장","햇살 농장","바람 농장","들꽃 농장"],"counts":[32,null,41,21],"units":[10,1],"icon":"🦆","unit":"마리","vh":"오리의 수","blank":[1]},"variant_rule":{"alt":[{"stem":"신발의 수의 합계는 94켤레예요. 그림그래프에서 샌들 줄이 지워졌어요. 판매한 샌들은 몇 켤레인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["보이는 줄의 수를 읽어요 — 16, 42, 11.","모르는 수 = 합계 − 아는 수들이에요.","94 − 16 − 42 − 11 = 25켤레예요."],"asset":{"type":"picg","title":"종류별 판매한 신발의 수","head":"종류","cols":["운동화","구두","샌들","장화"],"counts":[16,42,null,11],"units":[10,1],"icon":"👟","unit":"켤레","vh":"신발의 수","blank":[2]}},{"stem":"도넛의 수의 합계는 102개예요. 그림그래프에서 딸기도넛 줄이 지워졌어요. 판매한 딸기도넛은 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["보이는 줄의 수를 읽어요 — 38, 6, 48.","모르는 수 = 합계 − 아는 수들이에요.","102 − 38 − 6 − 48 = 10개예요."],"asset":{"type":"picg","title":"종류별 판매한 도넛의 수","head":"종류","cols":["크림도넛","초코도넛","딸기도넛","꿀도넛"],"counts":[38,6,null,48],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수","blank":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#24','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C4',4,'mc','auto','이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?',ARRAY['M3-2-u6-X01','M3-2-u6-X03']::text[],true,'{"seq":24,"concept":"M3-2-u6-C4","difficulty":4,"kind":"mc","stem":"이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?","options":[{"t":"미술부","correct":true},{"t":"합창부","mis":"M3-2-u6-X01"},{"t":"로봇부","mis":"M3-2-u6-X01"},{"t":"축구부","mis":"M3-2-u6-X03"}],"explanation":["그림 수 = 십의 자리 수 + 일의 자리 수예요.","합창부 34 → 7개, 로봇부 25 → 7개, 축구부 7 → 7개, 미술부 12 → 3개.","가장 적게 그리는 것은 미술부예요 — 수가 가장 작은 것과 다를 수 있어요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[34,25,7,12],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수","total":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?","options":[{"t":"제기차기","correct":true},{"t":"윷놀이","mis":"M3-2-u6-X01"},{"t":"투호","mis":"M3-2-u6-X01"},{"t":"연날리기","mis":"M3-2-u6-X03"}],"explanation":["그림 수 = 십의 자리 수 + 일의 자리 수예요.","윷놀이 32 → 5개, 투호 49 → 13개, 연날리기 3 → 3개, 제기차기 10 → 1개.","가장 적게 그리는 것은 제기차기예요 — 수가 가장 작은 것과 다를 수 있어요."],"asset":{"type":"picg","only":"table","head":"민속놀이","cols":["윷놀이","투호","연날리기","제기차기"],"counts":[32,49,3,10],"unit":"명","vh":"학생 수","title":"좋아하는 민속놀이별 학생 수","total":false}},{"stem":"이 표를 큰 그림 하나가 10마리, 작은 그림 하나가 1마리를 나타내도록 그림그래프로 나타내요. 그림을 가장 적게 그리는 것은 어느 것인가요?","options":[{"t":"초록 농장","correct":true},{"t":"햇살 농장","mis":"M3-2-u6-X01"},{"t":"바람 농장","mis":"M3-2-u6-X03"},{"t":"들꽃 농장","mis":"M3-2-u6-X01"}],"explanation":["그림 수 = 십의 자리 수 + 일의 자리 수예요.","초록 농장 20 → 2개, 햇살 농장 14 → 5개, 바람 농장 7 → 7개, 들꽃 농장 39 → 12개.","가장 적게 그리는 것은 초록 농장이에요 — 수가 가장 작은 것과 다를 수 있어요."],"asset":{"type":"picg","only":"table","head":"농장","cols":["초록 농장","햇살 농장","바람 농장","들꽃 농장"],"counts":[20,14,7,39],"unit":"마리","vh":"오리의 수","title":"농장별 기르는 오리의 수","total":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_c#25','math',3,2,'u6','','g3_2_math_u6_review_c','unit_review','M3-2-u6-C9',4,'essay','teacher','친구가 그림그래프에서 축구를 좋아하는 학생의 그림만 가로와 세로를 2배로 크게 그렸어요. 이렇게 그리면 어떤 문제가 생기는지 쓰고, 바르게 그리는 방법을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u6-C9","difficulty":4,"kind":"essay","stem":"친구가 그림그래프에서 축구를 좋아하는 학생의 그림만 가로와 세로를 2배로 크게 그렸어요. 이렇게 그리면 어떤 문제가 생기는지 쓰고, 바르게 그리는 방법을 써 보세요.","answer_guide":{"answer":"예: 가로와 세로를 2배로 하면 넓이가 4배가 되어 축구를 좋아하는 학생이 실제보다 훨씬 많아 보인다. 같은 수를 나타내는 그림은 모두 같은 크기로 그리고, 그림이 나타내는 수로 읽게 해야 한다.","scoring_points":["넓이가 4배가 된다고 썼는가","실제보다 많아 보여 잘못 읽게 된다고 썼는가","같은 수의 그림은 같은 크기로 그린다고 썼는가"]},"explanation":["2 × 2 = 4 — 넓이는 4배.","크기에 속아 많아 보여요.","같은 크기로 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#1','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C1',1,'mc','auto','◯ 그래프를 보고 가장 많은 학생이 태어난 계절을 고르세요.',ARRAY['M3-2-u6-X09','M3-2-u6-X16']::text[],true,'{"seq":1,"concept":"M3-2-u6-C1","difficulty":1,"kind":"mc","stem":"◯ 그래프를 보고 가장 많은 학생이 태어난 계절을 고르세요.","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M3-2-u6-X09"},{"t":"여름","mis":"M3-2-u6-X16"},{"t":"가을","mis":"M3-2-u6-X09"}],"explanation":["◯ 그래프는 ◯의 높이로 많고 적음을 한눈에 알 수 있어요.","◯가 가장 높이 올라간 것은 겨울.","답은 「겨울」이에요."],"asset":{"type":"pgraph","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[3,2,4,5],"unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"◯ 그래프를 보고 가장 적은 학생이 좋아하는 동물을 고르세요.","options":[{"t":"고양이","correct":true},{"t":"개","mis":"M3-2-u6-X16"},{"t":"앵무새","mis":"M3-2-u6-X09"},{"t":"토끼","mis":"M3-2-u6-X09"}],"explanation":["◯ 그래프는 ◯의 높이로 많고 적음을 한눈에 알 수 있어요.","◯가 가장 적게 그려진 것은 고양이.","답은 「고양이」예요."],"asset":{"type":"pgraph","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼"],"counts":[7,5,3,4],"unit":"명","vh":"학생 수"}},{"stem":"◯ 그래프를 보고 가장 많은 학생이 좋아하는 과일을 고르세요.","options":[{"t":"감","correct":true},{"t":"자두","mis":"M3-2-u6-X09"},{"t":"포도","mis":"M3-2-u6-X09"},{"t":"키위","mis":"M3-2-u6-X16"}],"explanation":["◯ 그래프는 ◯의 높이로 많고 적음을 한눈에 알 수 있어요.","◯가 가장 높이 올라간 것은 감.","답은 「감」이에요."],"asset":{"type":"pgraph","topic":"fruit","title":"우리 반 학생들이 좋아하는 과일별 학생 수","head":"과일","cols":["자두","포도","키위","감"],"counts":[6,5,2,8],"unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#2','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C2',1,'mc','auto','그림그래프에서 큰 그림 🌳 한 개는 몇 그루를 나타내나요?',ARRAY['M3-2-u6-X02']::text[],true,'{"seq":2,"concept":"M3-2-u6-C2","difficulty":1,"kind":"mc","stem":"그림그래프에서 큰 그림 🌳 한 개는 몇 그루를 나타내나요?","options":[{"t":"10그루","correct":true},{"t":"1그루","mis":"M3-2-u6-X02"},{"t":"5그루","mis":"M3-2-u6-X02"},{"t":"100그루","mis":"M3-2-u6-X02"}],"explanation":["그림그래프 아래의 그림 뜻을 봐요.","큰 그림은 10그루, 작은 그림은 1그루예요.","큰 그림 한 개는 10그루예요."],"asset":{"type":"picg","title":"마을별 심은 나무의 수","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[34,49,32,43],"units":[10,1],"icon":"🌳","unit":"그루","vh":"나무의 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 작은 그림 🍾 한 개는 몇 개를 나타내나요?","options":[{"t":"1개","correct":true},{"t":"10개","mis":"M3-2-u6-X02"},{"t":"5개","mis":"M3-2-u6-X02"},{"t":"100개","mis":"M3-2-u6-X02"}],"explanation":["그림그래프 아래의 그림 뜻을 봐요.","큰 그림은 10개, 작은 그림은 1개예요.","작은 그림 한 개는 1개예요."],"asset":{"type":"picg","title":"반별 모은 빈 병의 수","head":"반","cols":["1반","2반","3반","4반"],"counts":[27,41,20,24],"units":[10,1],"icon":"🍾","unit":"개","vh":"빈 병의 수"}},{"stem":"그림그래프에서 큰 그림 🙂 한 개는 몇 명을 나타내나요?","options":[{"t":"10명","correct":true},{"t":"1명","mis":"M3-2-u6-X02"},{"t":"5명","mis":"M3-2-u6-X02"},{"t":"100명","mis":"M3-2-u6-X02"}],"explanation":["그림그래프 아래의 그림 뜻을 봐요.","큰 그림은 10명, 작은 그림은 1명이에요.","큰 그림 한 개는 10명이에요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[25,21,36,7],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUD