INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#15','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C7',2,'sa','auto','그림그래프를 보고 건우가 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M3-2-u6-C7","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 건우가 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["15"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","건우 줄은 5회 그림 3개예요.","건우가 운동한 횟수는 15회예요."],"asset":{"type":"picg","title":"한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[15,9,28,21],"units":[5,1],"icon":"🏃","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 도윤이 훌라후프를 한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["22"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","도윤 줄은 5회 그림 4개와 1회 그림 2개예요.","도윤이 훌라후프를 한 횟수는 22회예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[21,28,22,17],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}},{"stem":"그림그래프를 보고 튤립은 몇 송이인지 구하세요. 숫자로 쓰세요.","answer":["26"],"explanation":["그림 뜻을 먼저 봐요 — 큰 그림 5송이, 작은 그림 1송이.","튤립 줄은 5송이 그림 5개와 1송이 그림 1개예요.","튤립은 26송이예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[13,26,3,17],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#16','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C8',2,'mc','auto','나 그림그래프를 읽을 때 조심할 점은 무엇인가요?',ARRAY['M3-2-u6-X01','M3-2-u6-X06']::text[],true,'{"seq":16,"concept":"M3-2-u6-C8","difficulty":2,"kind":"mc","stem":"나 그림그래프를 읽을 때 조심할 점은 무엇인가요?","options":[{"t":"세 가지 크기의 그림을 잘 구분해 읽어요","correct":true},{"t":"그림의 개수만 세어요","mis":"M3-2-u6-X01"},{"t":"가장 큰 그림만 세어요","mis":"M3-2-u6-X06"},{"t":"작은 그림은 빼고 읽어요","mis":"M3-2-u6-X06"}],"explanation":["단위가 늘면 그림 크기가 셋, 넷으로 늘어나요.","크기가 비슷하면 어떤 그림인지 헷갈려요.","답은 「세 가지 크기의 그림을 잘 구분해 읽어요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"그림의 단위를 네 가지, 다섯 가지로 계속 늘리면 어떤 점이 어려울까요?","options":[{"t":"그림의 크기를 구분하기가 더 어려워요","correct":true},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"큰 수를 나타낼 수 없어요","mis":"M3-2-u6-X14"},{"t":"항목을 쓸 수 없어요","mis":"M3-2-u6-X07"}],"explanation":["단위가 늘면 그림 크기가 셋, 넷으로 늘어나요.","크기가 비슷하면 어떤 그림인지 헷갈려요.","답은 「그림의 크기를 구분하기가 더 어려워요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"단위의 종류가 늘어나면 불편한 점은 무엇인가요?","options":[{"t":"그림의 크기를 뚜렷이 구분해 그리기 어려워요","correct":true},{"t":"큰 수를 나타낼 수 없어요","mis":"M3-2-u6-X14"},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"제목을 쓸 수 없어요","mis":"M3-2-u6-X07"}],"explanation":["단위가 늘면 그림 크기가 셋, 넷으로 늘어나요.","크기가 비슷하면 어떤 그림인지 헷갈려요.","답은 「그림의 크기를 뚜렷이 구분해 그리기 어려워요」예요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#17','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',3,'mc','auto','그림그래프를 보고 가장 많은 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16']::text[],true,'{"seq":17,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"그림그래프를 보고 가장 많은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"합창부 → 미술부 → 로봇부 → 축구부","correct":true},{"t":"미술부 → 합창부 → 로봇부 → 축구부","mis":"M3-2-u6-X04"},{"t":"축구부 → 로봇부 → 미술부 → 합창부","mis":"M3-2-u6-X16"},{"t":"합창부 → 로봇부 → 축구부 → 미술부","mis":"M3-2-u6-X04"}],"explanation":["줄마다 수를 읽어요 — 합창부 26, 로봇부 14, 축구부 5, 미술부 19.","그림 개수가 아니라 나타내는 수로 차례를 정해요.","합창부 → 미술부 → 로봇부 → 축구부."],"asset":{"type":"picg","title":"가입한 동아리별 학생 수","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[26,14,5,19],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 가장 적은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"윷놀이 → 제기차기 → 연날리기 → 투호","correct":true},{"t":"제기차기 → 투호 → 윷놀이 → 연날리기","mis":"M3-2-u6-X04"},{"t":"투호 → 연날리기 → 제기차기 → 윷놀이","mis":"M3-2-u6-X16"},{"t":"제기차기 → 윷놀이 → 연날리기 → 투호","mis":"M3-2-u6-X03"}],"explanation":["줄마다 수를 읽어요 — 윷놀이 7, 투호 23, 연날리기 19, 제기차기 14.","그림 개수가 아니라 나타내는 수로 차례를 정해요.","윷놀이 → 제기차기 → 연날리기 → 투호."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 학생 수","head":"민속놀이","cols":["윷놀이","투호","연날리기","제기차기"],"counts":[7,23,19,14],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"이번에는 다른 그림이에요. 그림그래프를 보고 가장 많은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"초록 농장 → 들꽃 농장 → 바람 농장 → 햇살 농장","correct":true},{"t":"바람 농장 → 햇살 농장 → 들꽃 농장 → 초록 농장","mis":"M3-2-u6-X04"},{"t":"햇살 농장 → 바람 농장 → 들꽃 농장 → 초록 농장","mis":"M3-2-u6-X16"},{"t":"들꽃 농장 → 초록 농장 → 바람 농장 → 햇살 농장","mis":"M3-2-u6-X03"}],"explanation":["줄마다 수를 읽어요 — 초록 농장 30, 햇살 농장 9, 바람 농장 19, 들꽃 농장 22.","그림 개수가 아니라 나타내는 수로 차례를 정해요.","초록 농장 → 들꽃 농장 → 바람 농장 → 햇살 농장."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["초록 농장","햇살 농장","바람 농장","들꽃 농장"],"counts":[30,9,19,22],"units":[10,1],"icon":"🦆","unit":"마리","vh":"오리의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#18','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C4',3,'sa','auto','이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-2-u6-C4","difficulty":3,"kind":"sa","stem":"이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.","answer":["29"],"explanation":["줄마다 큰 그림과 작은 그림의 개수를 구해요.","8 → 8개, 29 → 11개, 6 → 6개, 4 → 4개.","8 + 11 + 6 + 4 = 29개예요."],"asset":{"type":"picg","only":"table","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[8,29,6,4],"unit":"명","vh":"학생 수","title":"좋아하는 채소별 학생 수","total":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.","answer":["32"],"explanation":["줄마다 큰 그림과 작은 그림의 개수를 구해요.","7 → 7개, 4 → 4개, 19 → 10개, 47 → 11개.","7 + 4 + 10 + 11 = 32개예요."],"asset":{"type":"picg","only":"table","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[7,4,19,47],"unit":"명","vh":"학생 수","title":"가고 싶어 하는 체험 학습 장소별 학생 수","total":false}},{"stem":"이번에는 다른 그림이에요. 이 표를 큰 그림 하나가 10명, 작은 그림 하나가 1명을 나타내도록 그림그래프로 나타내면 그림은 모두 몇 개 그리나요? 숫자로 쓰세요.","answer":["35"],"explanation":["줄마다 큰 그림과 작은 그림의 개수를 구해요.","38 → 11개, 15 → 6개, 49 → 13개, 32 → 5개.","11 + 6 + 13 + 5 = 35개예요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[38,15,49,32],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수","total":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#19','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C5',3,'mc','auto','산불 예방 교육을 봄에 하자고 했어요. 알맞은 까닭은 무엇인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X17']::text[],true,'{"seq":19,"concept":"M3-2-u6-C5","difficulty":3,"kind":"mc","stem":"산불 예방 교육을 봄에 하자고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"봄에 산불이 가장 많이 나서","correct":true},{"t":"봄에 산불이 가장 적게 나서","mis":"M3-2-u6-X16"},{"t":"여름에 산불이 가장 많이 나서","mis":"M3-2-u6-X17"},{"t":"봄 그림의 색이 진해서","mis":"M3-2-u6-X17"}],"explanation":["그림그래프에서 계절마다 건수를 읽어요 — 봄 312, 여름 46, 가을 95, 겨울 241.","정한 때와 그래프에서 읽은 사실이 맞아야 해요.","알맞은 까닭 — 봄에 산불이 가장 많이 나서."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[312,46,95,241],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"산불 예방 교육을 사계절 내내 하자고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"어느 계절에도 산불이 나서","correct":true},{"t":"여름에는 산불이 하나도 없어서","mis":"M3-2-u6-X17"},{"t":"가을에 산불이 가장 많아서","mis":"M3-2-u6-X17"},{"t":"그림그래프에 계절이 네 개라서","mis":"M3-2-u6-X17"}],"explanation":["그림그래프에서 계절마다 건수를 읽어요 — 봄 286, 여름 37, 가을 124, 겨울 205.","정한 때와 그래프에서 읽은 사실이 맞아야 해요.","알맞은 까닭 — 어느 계절에도 산불이 나서."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[286,37,124,205],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}},{"stem":"산불 예방 교육을 가을에 하자고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"산불이 많이 나는 겨울과 봄이 오기 전이라서","correct":true},{"t":"가을에 산불이 가장 많이 나서","mis":"M3-2-u6-X17"},{"t":"여름에 산불이 가장 많이 나서","mis":"M3-2-u6-X17"},{"t":"가을의 그림이 가장 커서","mis":"M3-2-u6-X15"}],"explanation":["그림그래프에서 계절마다 건수를 읽어요 — 봄 377, 여름 29, 가을 82, 겨울 268.","정한 때와 그래프에서 읽은 사실이 맞아야 해요.","알맞은 까닭 — 산불이 많이 나는 겨울과 봄이 오기 전이라서."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#20','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C6',3,'sa','auto','표의 한 칸이 지워졌어요. 합계를 보고 합창부에 가입한 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-2-u6-C6","difficulty":3,"kind":"sa","stem":"표의 한 칸이 지워졌어요. 합계를 보고 합창부에 가입한 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["29"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들.","107 − 26 − 28 − 24 = 29예요."],"asset":{"type":"picg","only":"table","head":"동아리","cols":["합창부","로봇부","축구부","미술부"],"counts":[null,26,28,24],"unit":"명","vh":"학생 수","title":"가입한 동아리별 학생 수","total":107},"variant_rule":{"alt":[{"stem":"표의 한 칸이 지워졌어요. 합계를 보고 동물원에 가고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["20"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들.","84 − 19 − 16 − 29 = 20이에요."],"asset":{"type":"picg","only":"table","head":"장소","cols":["놀이공원","박물관","과학관","동물원"],"counts":[19,16,29,null],"unit":"명","vh":"학생 수","title":"가고 싶어 하는 체험 학습 장소별 학생 수","total":84}},{"stem":"표의 한 칸이 지워졌어요. 합계를 보고 오카리나를 배우고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["33"],"explanation":["합계는 모두 더한 수예요.","모르는 수 = 합계 − 아는 수들.","107 − 12 − 27 − 35 = 33이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[12,null,27,35],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수","total":107}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#21','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C7',3,'sa','auto','표를 보고 그림그래프를 그리고 있어요. 비어 있는 건우 줄에 5회 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"표를 보고 그림그래프를 그리고 있어요. 비어 있는 건우 줄에 5회 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["표에서 건우는 18회예요.","5회 그림 3개와 1회 그림 3개예요.","3개예요."],"asset":{"type":"picg","title":"훌라후프를 한 횟수","head":"이름","cols":["은비","건우","도윤","지유"],"counts":[29,18,27,21],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수","table":true,"blank":[1]},"variant_rule":{"alt":[{"stem":"표를 보고 그림그래프를 그리고 있어요. 비어 있는 튤립 줄에 1송이 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["표에서 튤립은 24송이예요.","5송이 그림 4개와 1송이 그림 4개예요.","4개예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"꽃","cols":["장미","튤립","백합","해바라기"],"counts":[15,24,22,16],"units":[5,1],"icon":"🌷","unit":"송이","vh":"꽃의 수","table":true,"blank":[1]}},{"stem":"표를 보고 그림그래프를 그리고 있어요. 비어 있는 해님 모둠 줄에 5장 그림은 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["표에서 해님 모둠은 17장이에요.","5장 그림 3개와 1장 그림 2개예요.","3개예요."],"asset":{"type":"picg","title":"모둠별 모은 칭찬 붙임딱지의 수","head":"모둠","cols":["해님 모둠","달님 모둠","별님 모둠","구름 모둠"],"counts":[17,24,23,13],"units":[5,1],"icon":"⭐","unit":"장","vh":"붙임딱지의 수","table":true,"blank":[0]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#22','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C9',3,'sa','auto','그림의 가로와 세로를 함께 2배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M3-2-u6-C9","difficulty":3,"kind":"sa","stem":"그림의 가로와 세로를 함께 2배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["가로로 2개, 세로로 2개만큼 처음 그림이 들어가요.","2 × 2 = 4.","넓이는 4배예요 — 2배로 보이지 않아요."],"variant_rule":{"alt":[{"stem":"그림의 가로와 세로를 함께 4배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.","answer":["16"],"explanation":["가로로 4개, 세로로 4개만큼 처음 그림이 들어가요.","4 × 4 = 16.","넓이는 16배예요 — 4배로 보이지 않아요."],"asset":null},{"stem":"그림의 가로와 세로를 함께 3배로 그리면 넓이는 몇 배가 되나요? 숫자로 쓰세요.","answer":["9"],"explanation":["가로로 3개, 세로로 3개만큼 처음 그림이 들어가요.","3 × 3 = 9.","넓이는 9배예요 — 3배로 보이지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#23','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',4,'sa','auto','㉠은 그림이 8개, ㉡은 그림이 4개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u6-C3","difficulty":4,"kind":"sa","stem":"㉠은 그림이 8개, ㉡은 그림이 4개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.","answer":["5"],"explanation":["그림이 많다고 수가 많은 것은 아니에요.","㉠은 17, ㉡은 22라 ㉡이 더 많아요.","22 − 17 = 5예요."],"asset":{"type":"picg","title":"그림의 개수와 수","head":"종류","cols":["㉠","㉡"],"counts":[17,22],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"},"variant_rule":{"alt":[{"stem":"㉠은 그림이 7개, ㉡은 그림이 5개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.","answer":["7"],"explanation":["그림이 많다고 수가 많은 것은 아니에요.","㉠은 34, ㉡은 41이라 ㉡이 더 많아요.","41 − 34 = 7이에요."],"asset":{"type":"picg","title":"그림의 개수와 수","head":"반","cols":["㉠","㉡"],"counts":[34,41],"units":[10,1],"icon":"📕","unit":"권","vh":"책의 수"}},{"stem":"㉠은 그림이 9개, ㉡은 그림이 6개예요. 그런데 어느 쪽이 더 많은지 견주어 보고, 두 수의 차를 구하세요. 숫자로 쓰세요.","answer":["6"],"explanation":["그림이 많다고 수가 많은 것은 아니에요.","㉠은 27, ㉡은 33이라 ㉡이 더 많아요.","33 − 27 = 6이에요."],"asset":{"type":"picg","title":"그림의 개수와 수","head":"마을","cols":["㉠","㉡"],"counts":[27,33],"units":[10,1],"icon":"🌳","unit":"그루","vh":"나무의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#24','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C4',4,'mc','auto','나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?',ARRAY['M3-2-u6-X01','M3-2-u6-X03']::text[],true,'{"seq":24,"concept":"M3-2-u6-C4","difficulty":4,"kind":"mc","stem":"나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M3-2-u6-X01"},{"t":"여름","mis":"M3-2-u6-X03"},{"t":"가을","mis":"M3-2-u6-X01"}],"explanation":["줄마다 100·10·1 그림의 개수를 더해요.","봄 214 → 7개, 여름 236 → 11개, 가을 130 → 4개, 겨울 79 → 16개.","겨울 — 수가 가장 큰 여름과 달라요."],"asset":{"type":"picg","title":"계절별 산불 발생 건수 — 가: 10·1, 나: 100·10·1","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[214,236,130,79],"units":[10,1],"icon":"🔥","unit":"건","vh":"발생 건수","units2":[100,10,1]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?","options":[{"t":"월요일","correct":true},{"t":"화요일","mis":"M3-2-u6-X01"},{"t":"수요일","mis":"M3-2-u6-X01"},{"t":"목요일","mis":"M3-2-u6-X03"}],"explanation":["줄마다 100·10·1 그림의 개수를 더해요.","월요일 369 → 18개, 화요일 183 → 12개, 수요일 291 → 12개, 목요일 380 → 11개.","월요일 — 수가 가장 큰 목요일과 달라요."],"asset":{"type":"picg","title":"요일별 도서관을 찾은 사람 수 — 가: 10·1, 나: 100·10·1","head":"요일","cols":["월요일","화요일","수요일","목요일"],"counts":[369,183,291,380],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수","units2":[100,10,1]}},{"stem":"이번에는 다른 그림이에요. 나 그림그래프에서 그림을 크기에 관계없이 가장 많이 그린 줄은 어느 것인가요?","options":[{"t":"바람 마을","correct":true},{"t":"햇살 마을","mis":"M3-2-u6-X01"},{"t":"구름 마을","mis":"M3-2-u6-X01"},{"t":"별빛 마을","mis":"M3-2-u6-X03"}],"explanation":["줄마다 100·10·1 그림의 개수를 더해요.","햇살 마을 130 → 4개, 바람 마을 179 → 17개, 구름 마을 86 → 14개, 별빛 마을 283 → 13개.","바람 마을 — 수가 가장 큰 별빛 마을과 달라요."],"asset":{"type":"picg","title":"마을별 사과 생산량 — 가: 10·1, 나: 100·10·1","head":"마을","cols":["햇살 마을","바람 마을","구름 마을","별빛 마을"],"counts":[130,179,86,283],"units":[10,1],"icon":"🍎","unit":"상자","vh":"생산량","units2":[100,10,1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u6_review_d#25','math',3,2,'u6','','g3_2_math_u6_review_d','unit_review','M3-2-u6-C5',4,'essay','teacher','3학년과 4학년이 좋아하는 민속놀이를 각각 그림그래프로 나타냈어요. 두 학년 모두 윷놀이가 가장 많고, 3학년은 투호, 4학년은 연날리기가 가장 적어요. 학년 민속놀이 대회 종목을 하나 정하고 그림그래프에서 읽은 사실로 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u6-C5","difficulty":4,"kind":"essay","stem":"3학년과 4학년이 좋아하는 민속놀이를 각각 그림그래프로 나타냈어요. 두 학년 모두 윷놀이가 가장 많고, 3학년은 투호, 4학년은 연날리기가 가장 적어요. 학년 민속놀이 대회 종목을 하나 정하고 그림그래프에서 읽은 사실로 까닭을 써 보세요.","answer_guide":{"answer":"예: 윷놀이로 정하겠다. 두 그림그래프 모두 윷놀이를 좋아하는 학생이 가장 많아 두 학년이 함께 즐길 수 있기 때문이다.","scoring_points":["대회 종목을 정해 썼는가","두 그림그래프에서 읽은 사실(가장 많음 등)로 까닭을 썼는가","두 그래프를 함께 견주었는가"]},"explanation":["두 그래프의 같은 점을 찾아요.","모두 윷놀이가 가장 많아요.","읽은 사실로 까닭을 대요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
